/**
 * Purpose: Open the open print package workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function openPrintPackage(printCandidates, filters = {}) {
  const listIds = [...new Set(printCandidates.flatMap((candidate) => candidate.listIds || []))];
  if (!listIds.length) return;
  const params = new URLSearchParams({ listId: listIds.join(",") });
  for (const [key, value] of Object.entries(filters)) {
    if (value) params.set(key, value);
  }
  launchManagedPrint(`/api/print/package?${params.toString()}`);
}

/**
 * Purpose: Run the run assignment action workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function runAssignmentAction(action, assignmentId) {
  const found = assignmentById(assignmentId);
  const assignment = found.assignment;
  if (!assignment?.id) {
    showInlineError("Assignment not found.", true);
    return;
  }
  if (found.bay?.bayCode) state.selectedBayCode = found.bay.bayCode;
  if (action === "sdi") {
    openSdiPanel(assignment.id);
    return;
  }
  if (action === "manage") {
    openManageItemsPanel(assignment.id);
    return;
  }
  if (action === "clear" || action === "move") {
    // Clear and move now use the Manage Items workflow so a whole Job Nr. group moves together.
    openManageItemsPanel(assignment.id);
  }
}

/**
 * Purpose: Run the selected print stage inputs workflow for the browser application.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
const PRINT_PREVIEW_PAGE_SIZE = 18;
const PRINT_PRESET_STORAGE_KEY = "deliveryScannerPrintPresetsV205";
const PRINT_PRESET_LEGACY_STORAGE_KEY = "deliveryScannerPrintPresetsV197";
const PRINT_ACTIVE_PRESET_STORAGE_KEY = "deliveryScannerActivePrintPresetV205";
const PRINT_DEFAULT_PRESET_STORAGE_KEY = "deliveryScannerDefaultPrintPresetV227";
const PRINT_SYSTEM_DEFAULT_PRESET_NAME = "Default";
const PRINT_LEGACY_SYSTEM_DEFAULT_PRESET_NAME = "System Default";
const PRINT_SYSTEM_DEFAULT_PRESET = Object.freeze({
  routeGroups: Object.freeze(["airport"]),
  statuses: Object.freeze([]),
  attention: Object.freeze([]),
  glassTypes: Object.freeze([]),
  glassFamilies: Object.freeze([]),
  outputType: "pdf",
  copies: 1,
  orientation: "portrait",
});
const PRINT_ROUTE_GROUPS = [
  { value: "airport", label: "Airport Road" },
  { value: "indian_trail", label: "Indian Trail" },
  { value: "greenville", label: "Greenville" },
  { value: "cpu", label: "CPU" },
  { value: "dtc", label: "DTC" },
];

/** Return the visible exact glass-type checkboxes, excluding the All Glass control. */
function selectedPrintGlassInputs() {
  return [...(els.printOptionsGlassType?.querySelectorAll('input[data-print-glass-type]') || [])];
}

/** Return checked values from one maintained filter container. */
function selectedPrintFilterValues(container, selector) {
  return [...(container?.querySelectorAll(selector) || [])]
    .filter((input) => input.checked)
    .map((input) => String(input.value || "").trim())
    .filter(Boolean);
}

/** Return selected status values; All Status means no status restriction. */
function selectedPrintStatusValues() {
  if (els.printStatusOptions?.querySelector('input[data-print-status-all]')?.checked) return [];
  return selectedPrintFilterValues(els.printStatusOptions, 'input[data-print-status]:not([data-print-status-all])');
}

/** Return selected attention values; All Attention includes rows with no attention flags. */
function selectedPrintAttentionValues() {
  if (els.printAttentionOptions?.querySelector('input[data-print-attention-all]')?.checked) return [];
  return selectedPrintFilterValues(els.printAttentionOptions, 'input[data-print-attention]:not([data-print-attention-all])');
}

/** Return a stable comparison key for an imported or selected glass type. */
function printGlassTypeMatchKey(value) {
  return String(value || "")
    .normalize("NFKC")
    .replace(/[“”″]/g, '"')
    .replace(/[‘’′]/g, "'")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

/** Commit a manual exact-glass choice and replace any preset family rule. */
function commitPrintGlassSelectionFromControls() {
  const allInput = els.printOptionsGlassType?.querySelector('input[data-print-all-glass]');
  const inputs = selectedPrintGlassInputs();
  if (!allInput || !inputs.length) return;
  const exactValues = inputs
    .filter((input) => input.checked)
    .map((input) => String(input.dataset.printGlassValue || input.value || "").trim())
    .filter(Boolean);
  state.printAllGlass = Boolean(allInput.checked) || exactValues.length === 0;
  state.printGlassTypes = state.printAllGlass ? [] : [...new Set(exactValues)];
  // Manual changes intentionally become an exact rule. Preset family rules are
  // retained across date/route rerenders until the user changes Glass Types.
  state.printGlassFamilies = [];
  state.printGlassRuleTypes = state.printAllGlass ? [] : [...state.printGlassTypes];
}

/** Return true when one product matches the maintained preset glass-family rule. */
function printGlassMatchesFamilyRule(label, families = state.printGlassFamilies) {
  const selectedFamilies = new Set((families || []).map((value) => String(value || "").trim().toLowerCase()));
  return selectedFamilies.has(printGlassCategoryForLabel(label));
}

/** Report whether an exact/family glass rule should be reapplied after a rerender. */
function hasPrintGlassSelectionRule() {
  return Boolean((state.printGlassFamilies || []).length || (state.printGlassRuleTypes || []).length);
}

/** Return true when the unrestricted All Glass choice is selected. */
function allPrintGlassTypesSelected() {
  return state.printAllGlass !== false;
}

/** Return exact glass types from stable state instead of transient loading markup. */
function selectedPrintGlassTypeValues() {
  return state.printAllGlass === false ? [...(state.printGlassTypes || [])] : [];
}

/** Keep All Glass mutually exclusive with exact glass-type choices. */
function syncPrintAllGlassChoice(changed) {
  const allInput = els.printOptionsGlassType?.querySelector('input[data-print-all-glass]');
  const detailInputs = selectedPrintGlassInputs();
  if (!allInput || !changed) return;
  if (changed === allInput) {
    if (allInput.checked) detailInputs.forEach((input) => { input.checked = false; });
    else if (!detailInputs.some((input) => input.checked)) allInput.checked = true;
    return;
  }
  if (changed.checked) allInput.checked = false;
  const enabledDetails = detailInputs.filter((input) => !input.disabled);
  if (enabledDetails.length && enabledDetails.every((input) => input.checked)) {
    allInput.checked = true;
    detailInputs.forEach((input) => { input.checked = false; });
    return;
  }
  if (!detailInputs.some((input) => input.checked)) allInput.checked = true;
}

/** Keep one All choice mutually exclusive with its detailed choices. */
function syncPrintAllFilterChoice(container, changed, allSelector, detailSelector) {
  if (!container || !changed) return;
  const allInput = container.querySelector(allSelector);
  const detailInputs = [...container.querySelectorAll(detailSelector)];
  if (!allInput) return;
  if (changed === allInput) {
    if (allInput.checked) detailInputs.forEach((input) => { input.checked = false; });
    else if (!detailInputs.some((input) => input.checked)) allInput.checked = true;
    return;
  }
  if (changed.checked) allInput.checked = false;
  const enabledDetails = detailInputs.filter((input) => !input.disabled);
  if (enabledDetails.length && enabledDetails.every((input) => input.checked)) {
    allInput.checked = true;
    detailInputs.forEach((input) => { input.checked = false; });
    return;
  }
  if (!detailInputs.some((input) => input.checked)) allInput.checked = true;
}

/** Collapse every available detailed route back to Airport, the maintained all-routes choice. */
function syncPrintAllRouteChoice(container, changed) {
  if (!container || !changed) return;
  const routeInputs = [...container.querySelectorAll('input[data-print-route-group]')];
  const airport = routeInputs.find((input) => input.value === "airport");
  if (!airport) return;
  const detailInputs = routeInputs.filter((input) => input !== airport);
  const enabledDetails = detailInputs.filter((input) => !input.disabled);
  if (changed === airport) {
    if (airport.checked) detailInputs.forEach((input) => { input.checked = false; });
    else if (!detailInputs.some((input) => input.checked)) airport.checked = true;
    return;
  }
  if (changed.checked) airport.checked = false;
  if (enabledDetails.length && enabledDetails.every((input) => input.checked)) {
    airport.checked = true;
    detailInputs.forEach((input) => { input.checked = false; });
    return;
  }
  if (!routeInputs.some((input) => input.checked)) airport.checked = true;
}

/** Normalize route state and guarantee one usable initial destination. */
function normalizePrintRouteGroups(values = state.printRouteGroups) {
  const validValues = new Set(PRINT_ROUTE_GROUPS.map(({ value }) => value));
  const selected = [...new Set((values || [])
    .map((value) => String(value || "").trim())
    .filter((value) => validValues.has(value)))];
  if (!selected.length || selected.includes("airport")) return ["airport"];
  return selected;
}

/** Commit route state first, then mirror it into any currently rendered controls. */
function setPrintRouteGroups(values, { syncControls = true } = {}) {
  const selected = normalizePrintRouteGroups(values);
  state.printRouteGroups = [...selected];
  if (syncControls) {
    const wanted = new Set(selected);
    els.printRouteOptions?.querySelectorAll('input[data-print-route-group]').forEach((input) => {
      input.checked = wanted.has(String(input.value || ""));
    });
  }
  return [...selected];
}

/** Commit the visible route controls into stable Print / Export state. */
function commitPrintRouteSelectionFromControls() {
  const routeInputs = [...(els.printRouteOptions?.querySelectorAll('input[data-print-route-group]') || [])];
  if (!routeInputs.length) return selectedPrintRouteGroups();
  return setPrintRouteGroups(routeInputs
    .filter((input) => input.checked)
    .map((input) => input.value));
}

/** Return selected destinations from stable state, never from temporary markup. */
function selectedPrintRouteGroups() {
  return setPrintRouteGroups(state.printRouteGroups, { syncControls: false });
}

/** Return active delivery lists inside the selected date range. */
function printDateRangeLists() {
  const dates = state.lists.map((list) => String(list.deliveryDate || "")).filter(Boolean).sort();
  const fallback = selectedDeliveryDate() || dashboardDateKey() || dates[0] || "";
  let startDate = String(els.printDateFrom?.value || fallback);
  let endDate = String(els.printDateTo?.value || startDate);
  if (startDate && endDate && startDate > endDate) [startDate, endDate] = [endDate, startDate];
  return state.lists.filter((list) => {
    const date = String(list.deliveryDate || "");
    return date && (!startDate || date >= startDate) && (!endDate || date <= endDate);
  });
}

/** Return the exact source lists represented by the Route workspace. */
function selectedPrintListIds() {
  if (state.printContext?.fixedListIds) return [...new Set((state.printContext.listIds || []).map(String))];
  return [...new Set(
    printDateRangeLists()
      .filter((list) => stageCategory(list) === "outbound")
      .map((list) => String(list.id || ""))
      .filter(Boolean),
  )];
}

/** Load missing item detail for selected lists before building exact choices. */
async function ensurePrintListDetails(listIds) {
  if (!state.backend) return;
  const wanted = new Set(listIds);
  const listsToLoad = state.lists.filter((list) => {
    if (!wanted.has(list.id) || list._printItemsLoaded) return false;
    return !Array.isArray(list.items) || !list.items.length;
  });
  if (!listsToLoad.length) return;

  await Promise.all(listsToLoad.map(async (list) => {
    const payload = await fetchJson(`/api/delivery-lists/${encodeURIComponent(list.id)}`);
    const items = cloneItems(payload.items || []);
    Object.assign(list, {
      items,
      itemCount: items.length || list.itemCount || 0,
      totalQty: items.length ? pieceCount(items) : list.totalQty,
      scannedQty: items.length ? items.reduce((sum, item) => sum + itemScannedPieceQty(item), 0) : list.scannedQty,
      _printItemsLoaded: true,
    });
  }));
}

/** Return true while the Print / Export panel is open and ready for user actions. */
function printWorkspaceIsVisible() {
  return Boolean(els.printOptionsPanel && !els.printOptionsPanel.hidden && state.printWorkspaceReady);
}

/** Detect selected catalog summaries whose detailed rows were invalidated by a real list change. */
function printWorkspaceNeedsDetailReload() {
  const selectedIds = new Set(selectedPrintListIds().map(String));
  if (!selectedIds.size) return false;
  return state.lists.some((list) => {
    if (!selectedIds.has(String(list.id || ""))) return false;
    return !list._printItemsLoaded && (!Array.isArray(list.items) || !list.items.length);
  });
}

/**
 * Reassert committed route state and reload rows only when a catalog revision actually changed.
 * This runs on focus/visibility/catalog events instead of polling, so idle recovery adds no
 * continuous work and unchanged loaded lists remain entirely in memory.
 */
async function restorePrintWorkspaceAfterInactivity({ refreshIfHealthy = false } = {}) {
  if (!printWorkspaceIsVisible()) return;
  setPrintRouteGroups(selectedPrintRouteGroups());

  if (!printWorkspaceNeedsDetailReload()) {
    if (refreshIfHealthy) schedulePrintSelectionPreview(0);
    return;
  }
  if (state.printWorkspaceRecoveryPromise) return state.printWorkspaceRecoveryPromise;

  const openId = state.printWorkspaceOpenId;
  const recovery = renderPrintFilterChoices({ preserveSelections: true, captureControlSelections: false })
    .then(() => {
      if (openId !== state.printWorkspaceOpenId || !printWorkspaceIsVisible()) return;
      setPrintRouteGroups(selectedPrintRouteGroups());
      schedulePrintSelectionPreview(0);
    })
    .catch((error) => {
      if (openId === state.printWorkspaceOpenId) showInlineError(error.message, false);
    })
    .finally(() => {
      if (state.printWorkspaceRecoveryPromise === recovery) state.printWorkspaceRecoveryPromise = null;
    });
  state.printWorkspaceRecoveryPromise = recovery;
  return recovery;
}

/** Return selected list records in deterministic date and stage order. */
function printSelectedLists(listIds) {
  const wanted = new Set(listIds || []);
  return state.lists
    .filter((list) => wanted.has(list.id))
    .sort((a, b) => String(a.deliveryDate || "").localeCompare(String(b.deliveryDate || "")) || stageSort(a) - stageSort(b));
}

/** Flatten selected list rows while retaining their delivery-list context. */
function printBaseRows(listIds) {
  const rows = [];
  for (const list of printSelectedLists(listIds)) {
    for (const item of Array.isArray(list.items) ? list.items : []) rows.push({ list, item });
  }
  return rows;
}

/** Return one row's maintained scan-state key. */
function printItemStatusKey(item) {
  const qty = Math.max(Number(item?.qty || 0), 0);
  const scanned = Math.max(Number(item?.scanned || 0), 0);
  if (qty > 0 && scanned >= qty) return "complete";
  if (scanned > 0) return "partial";
  return "not-scanned";
}

/** Return all maintained attention keys present on one row. */
function printItemAttentionKeys(item) {
  const keys = [];
  const signal = `${item?.processState || ""} ${item?.queueState || ""}`;
  if (/\b(?:remake|rm)\b/i.test(signal)) keys.push("remake");
  if (/\b(?:rush|sdi)\b/i.test(signal)) keys.push("rush");
  if (Number(item?.internalRejectCount || 0) > 0) keys.push("reject");
  if (/\b(?:update|updated|new|change|changed|added|add)\b/i.test(signal)) keys.push("updated");
  if (item?.errorType || item?.errorReason) keys.push("error");
  return keys;
}

/** Return the fixed Print / Export destination group for one item. */
function printRouteGroupForItem(item) {
  const category = routeCategory(item);
  return ["indian_trail", "greenville", "cpu", "dtc"].includes(category) ? category : "indian_trail";
}

/** Limit outbound rows to the selected destinations; Airport means every outbound row. */
function printRowsForSelectedRoutes(rows, routeGroups = selectedPrintRouteGroups()) {
  const selected = new Set(routeGroups || []);
  if (!selected.size) return [];
  if (selected.has("airport")) return rows.slice();
  return rows.filter(({ item }) => selected.has(printRouteGroupForItem(item)));
}

/** Render one compact selectable chip used by the Print / Export filter pane. */
function printFilterChipMarkup({ value, label, count, checked = false, disabled = false, type = "standard", data = "", state = "" }) {
  const stateClass = state === "alert" ? "has-alert" : state === "clear" ? "is-clear" : "";
  const availabilityClass = disabled ? "is-unavailable" : "";
  return `
    <label class="print-filter-chip-v197 is-${escapeHtml(type)} ${stateClass} ${availabilityClass}" ${disabled ? 'aria-disabled="true"' : ""}>
      <input type="checkbox" value="${escapeHtml(value)}" ${data} ${checked && !disabled ? "checked" : ""} ${disabled ? "disabled" : ""}>
      <span>${escapeHtml(label)}</span>
      <b>${escapeHtml(count)}</b>
    </label>
  `;
}

const PRINT_GLASS_CATEGORY_DEFINITIONS = Object.freeze([
  Object.freeze({ value: "mirror", label: "Mirror" }),
  Object.freeze({ value: "tempered", label: "Tempered" }),
  Object.freeze({ value: "annealed", label: "Annealed" }),
]);

/** Classify maintained product names into the three compact Print / Export glass groups. */
function printGlassCategoryForLabel(label) {
  const key = printGlassTypeMatchKey(label);
  if (/\bmirror\b/.test(key)) return "mirror";
  if (/\b(?:temper(?:ed)?|toughened|heat[- ]strengthened)\b/.test(key)) return "tempered";
  // Legacy lookup values do not always include the word annealed. Anything that
  // is not explicitly Mirror or Tempered belongs in the Annealed group so every
  // maintained product remains selectable instead of falling into an unlabeled bucket.
  return "annealed";
}

/** Render grouped glass choices with small color-coded category separators. */
function printGlassCategoryMarkup(glassEntries, selectedKeys, selectAllCurrent) {
  const grouped = new Map(PRINT_GLASS_CATEGORY_DEFINITIONS.map(({ value }) => [value, []]));
  for (const entry of glassEntries || []) {
    const [label, count] = entry;
    grouped.get(printGlassCategoryForLabel(label)).push([label, count]);
  }
  return PRINT_GLASS_CATEGORY_DEFINITIONS.map(({ value, label }) => {
    const entries = grouped.get(value) || [];
    if (!entries.length) return "";
    const pieceCount = entries.reduce((sum, entry) => sum + Number(entry[1] || 0), 0);
    const choices = entries.map(([glassLabel, count]) => printFilterChipMarkup({
      value: glassLabel,
      label: glassLabel,
      count,
      checked: !selectAllCurrent && selectedKeys.has(printGlassTypeMatchKey(glassLabel)),
      type: `glass-${value}`,
      data: `data-print-glass-type="1" data-print-glass-value="${escapeHtml(glassLabel)}" data-print-glass-search="${escapeHtml(glassLabel.toLowerCase())}"`,
    })).join("");
    return `<section class="print-glass-category-v220 is-${escapeHtml(value)}" data-print-glass-category>
      <header class="print-glass-category-heading-v220"><span>${escapeHtml(label)}</span><b>${escapeHtml(pieceCount)} pcs</b></header>
      <div class="print-glass-category-options-v220">${choices}</div>
    </section>`;
  }).join("");
}

/** Convert a local Date into the scanner's YYYY-MM-DD date key. */
function printCalendarDateKey(date) {
  const value = date instanceof Date ? date : new Date();
  const year = value.getFullYear();
  const month = String(value.getMonth() + 1).padStart(2, "0");
  const day = String(value.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

/** Parse a scanner date key without UTC date shifting. */
function printCalendarDateFromKey(value) {
  const match = String(value || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
  return match ? new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3])) : null;
}

/** Return the first day of the month represented by a date or date key. */
function printCalendarMonthDate(value) {
  const parsed = value instanceof Date ? value : printCalendarDateFromKey(value);
  const fallback = parsed || new Date();
  return new Date(fallback.getFullYear(), fallback.getMonth(), 1);
}

/** Size the header date selector to its current date or date-range label. */
function syncPrintDateControlWidth() {
  const control = els.printDateQuickSelect?.closest(".print-header-date-control-v203");
  if (!control || !els.printDateQuickSelect) return;
  const text = customSelectSelectedText(els.printDateQuickSelect) || "Custom Range…";
  const isRange = String(els.printDateFrom?.value || "") !== String(els.printDateTo?.value || "");
  // Compact numeric dates keep the header balanced while custom ranges still
  // grow enough to show both endpoints without truncation.
  const minimum = isRange ? 270 : 160;
  const maximum = isRange ? 390 : 230;
  const measured = Math.ceil(text.length * 7.2 + 52);
  control.style.setProperty("--print-date-control-width", `${Math.min(Math.max(measured, minimum), maximum)}px`);
}

/** Return every unique outbound delivery date in chronological order. */
function printQuickDateCatalog() {
  return [...new Set(
    state.lists
      .filter((list) => stageCategory(list) === "outbound")
      .map((list) => String(list.deliveryDate || ""))
      .filter((date) => Boolean(printCalendarDateFromKey(date))),
  )].sort((a, b) => a.localeCompare(b));
}

/** Return the Monday that starts the visual week containing one date. */
function printQuickDateWeekStart(value) {
  const date = value instanceof Date ? new Date(value.getFullYear(), value.getMonth(), value.getDate()) : printCalendarDateFromKey(value);
  if (!date) return null;
  const mondayOffset = (date.getDay() + 6) % 7;
  date.setDate(date.getDate() - mondayOffset);
  return date;
}

/** Return a local calendar date shifted by an exact number of days. */
function printQuickDateShift(value, days) {
  const date = value instanceof Date ? new Date(value.getFullYear(), value.getMonth(), value.getDate()) : printCalendarDateFromKey(value);
  if (!date) return null;
  date.setDate(date.getDate() + Number(days || 0));
  return date;
}

/** Format one compact Monday-Friday business-week range for a date-dropdown group heading. */
function printQuickDateWeekRange(start) {
  const end = printQuickDateShift(start, 4);
  if (!start || !end) return "";
  return `${formatNumericDeliveryDate(start)}–${formatNumericDeliveryDate(end)}`;
}

/** Label date groups relative to the current business week when possible. */
function printQuickDateWeekLabel(startKey) {
  const start = printCalendarDateFromKey(startKey);
  const currentWeek = printQuickDateWeekStart(new Date());
  const previousWeek = printQuickDateShift(currentWeek, -7);
  const nextWeek = printQuickDateShift(currentWeek, 7);
  const key = printCalendarDateKey(start);
  const prefix = key === printCalendarDateKey(currentWeek)
    ? "This Week"
    : key === printCalendarDateKey(previousWeek)
      ? "Last Week"
      : key === printCalendarDateKey(nextWeek)
        ? "Next Week"
        : "Week";
  return `${prefix} · ${printQuickDateWeekRange(start)}`;
}

/** Return the oldest date exposed by the current two-week history window. */
function printQuickDateHistoryCutoffKey() {
  const days = Math.max(Number(state.printDateHistoryWeeks || PRINT_DATE_HISTORY_BATCH_WEEKS), PRINT_DATE_HISTORY_BATCH_WEEKS) * 7 - 1;
  return printCalendarDateKey(printQuickDateShift(new Date(), -days));
}

/** Report whether more historical delivery dates remain outside the current window. */
function printQuickDateHasMoreHistory() {
  const cutoff = printQuickDateHistoryCutoffKey();
  return printQuickDateCatalog().some((date) => date < cutoff);
}

/** Load exactly two more historical weeks without fetching or rerendering list detail. */
function loadMorePrintQuickDateHistory() {
  if (!printQuickDateHasMoreHistory()) return false;
  state.printDateHistoryWeeks = Math.max(
    Number(state.printDateHistoryWeeks || PRINT_DATE_HISTORY_BATCH_WEEKS),
    PRINT_DATE_HISTORY_BATCH_WEEKS,
  ) + PRINT_DATE_HISTORY_BATCH_WEEKS;
  renderPrintQuickDateOptions();
  return true;
}

/** Add the date menu's explicit and scroll-triggered history loader. */
function appendPrintQuickDateHistoryControl(select, optionsHost, query = "") {
  if (select.id !== "printDateQuickSelect" || select.dataset.hasMoreHistory !== "true" || String(query || "").trim()) return;
  const control = document.createElement("button");
  control.type = "button";
  control.className = "custom-select-load-more print-date-load-more-v225";
  control.innerHTML = '<strong>Load 2 older weeks</strong><span>Scroll to the bottom or select this row</span>';
  control.addEventListener("click", () => extendPrintQuickDateMenu(select, optionsHost, query));
  optionsHost.append(control);
}

/** Extend the open date menu while preserving its scroll position and selection. */
function extendPrintQuickDateMenu(select, optionsHost, query = "") {
  const previousHeight = optionsHost.scrollHeight;
  const previousTop = optionsHost.scrollTop;
  if (!loadMorePrintQuickDateHistory()) return false;
  renderCustomSelectOptions(select, optionsHost, query);
  window.requestAnimationFrame(() => {
    const addedHeight = Math.max(optionsHost.scrollHeight - previousHeight, 0);
    optionsHost.scrollTop = Math.max(previousTop, previousTop + Math.min(addedHeight * 0.08, 18));
    positionCustomSelectMenu();
  });
  return true;
}

/** Populate grouped delivery dates, initially showing two past weeks and every future date. */
function renderPrintQuickDateOptions() {
  if (!els.printDateQuickSelect) return;
  const start = String(els.printDateFrom?.value || "");
  const end = String(els.printDateTo?.value || start);
  const selectedValue = start && start === end ? start : "__range__";
  const rangeOption = start && end && start !== end
    ? `<option value="__range__">${escapeHtml(formatNumericDeliveryDate(start))} – ${escapeHtml(formatNumericDeliveryDate(end))}</option>`
    : "";

  const catalog = printQuickDateCatalog();
  const cutoff = printQuickDateHistoryCutoffKey();
  const visibleDates = new Set(catalog.filter((date) => date >= cutoff));
  if (selectedValue !== "__range__" && printCalendarDateFromKey(selectedValue)) {
    const selectedWeekKey = printCalendarDateKey(printQuickDateWeekStart(selectedValue));
    catalog.forEach((date) => {
      const weekStart = printQuickDateWeekStart(date);
      if (weekStart && printCalendarDateKey(weekStart) === selectedWeekKey) visibleDates.add(date);
    });
    visibleDates.add(selectedValue);
  }

  const grouped = new Map();
  [...visibleDates].forEach((date) => {
    const weekStart = printQuickDateWeekStart(date);
    if (!weekStart) return;
    const weekKey = printCalendarDateKey(weekStart);
    if (!grouped.has(weekKey)) grouped.set(weekKey, []);
    grouped.get(weekKey).push(date);
  });

  // Keep the newest available week first: future weeks, then this week,
  // then progressively older history. Dates inside each group follow the same
  // high-to-low order so the menu reads consistently from top to bottom.
  const orderedWeekKeys = [...grouped.keys()].sort((a, b) => b.localeCompare(a));
  const groupedOptions = orderedWeekKeys.map((weekKey) => {
    const options = grouped.get(weekKey)
      .sort((a, b) => b.localeCompare(a))
      .map((date) => `<option value="${escapeHtml(date)}">${escapeHtml(formatNumericDeliveryDate(date))}</option>`)
      .join("");
    return `<optgroup label="${escapeHtml(printQuickDateWeekLabel(weekKey))}">${options}</optgroup>`;
  }).join("");

  els.printDateQuickSelect.innerHTML = `<option value="__custom__">Custom Range…</option>${rangeOption}${groupedOptions}`;
  els.printDateQuickSelect.dataset.hasMoreHistory = printQuickDateHasMoreHistory() ? "true" : "false";
  els.printDateQuickSelect.value = selectedValue === "__range__" && !rangeOption ? "__custom__" : selectedValue;
  syncCustomSelect(els.printDateQuickSelect);
  syncPrintDateControlWidth();
}

/** Open the maintained custom-range calendar. */
function openPrintDateCalendar() {
  const currentStart = String(els.printDateFrom?.value || dashboardDateKey() || printCalendarDateKey(new Date()));
  const currentEnd = String(els.printDateTo?.value || currentStart);
  const editingExistingRange = Boolean(currentStart && currentEnd && currentStart !== currentEnd);
  // A single-date selection is only the calendar's opening month. Custom Range
  // starts with an empty draft so the next two clicks are always Date From and Date To.
  state.printCalendarDraftStart = editingExistingRange ? currentStart : "";
  state.printCalendarDraftEnd = editingExistingRange ? currentEnd : "";
  state.printCalendarMonth = printCalendarDateKey(printCalendarMonthDate(currentStart));
  if (els.printDateCalendar) els.printDateCalendar.hidden = false;
  renderPrintDateCalendar();
}

/** Close the date calendar without applying its draft. */
function closePrintDateCalendar() {
  if (!els.printDateCalendar || els.printDateCalendar.hidden) return;
  els.printDateCalendar.hidden = true;
  renderPrintQuickDateOptions();
}

/** Return one calendar month's six-week button grid. */
function dateRangeCalendarMonthButtons(month, today, availableDates, start, end, dataAttribute = "data-print-calendar-date") {
  const firstCell = new Date(month.getFullYear(), month.getMonth(), 1 - month.getDay());
  return Array.from({ length: 42 }, (_, offset) => {
    const date = new Date(firstCell.getFullYear(), firstCell.getMonth(), firstCell.getDate() + offset);
    const key = printCalendarDateKey(date);
    const classes = ["print-calendar-day-v201"];
    if (date.getMonth() !== month.getMonth()) classes.push("is-other-month");
    if (key === today) classes.push("is-today");
    if (key === start) classes.push("is-range-start", "is-selected");
    if (key === end) classes.push("is-range-end", "is-selected");
    if (start && end && key > start && key < end) classes.push("is-in-range");
    if (availableDates.has(key)) classes.push("has-delivery-list");
    return `<button class="${classes.join(" ")}" type="button" ${dataAttribute}="${escapeHtml(key)}" aria-label="${escapeHtml(date.toLocaleDateString())}"><span>${date.getDate()}</span></button>`;
  }).join("");
}

function printCalendarMonthButtons(month, today, availableDates, start, end) {
  return dateRangeCalendarMonthButtons(month, today, availableDates, start, end, "data-print-calendar-date");
}

/** Render a two-month Date From / Date To range picker with today highlighted. */
function renderPrintDateCalendar() {
  if (!els.printCalendarLeftGrid || !els.printCalendarRightGrid) return;
  const leftMonth = printCalendarMonthDate(state.printCalendarMonth || state.printCalendarDraftStart);
  const rightMonth = new Date(leftMonth.getFullYear(), leftMonth.getMonth() + 1, 1);
  const today = todayKey() || printCalendarDateKey(new Date());
  const availableDates = new Set(
    state.lists
      .filter((list) => stageCategory(list) === "outbound")
      .map((list) => String(list.deliveryDate || ""))
      .filter(Boolean),
  );
  const start = String(state.printCalendarDraftStart || "");
  const end = String(state.printCalendarDraftEnd || "");
  const monthLabel = (month) => month.toLocaleDateString([], { month: "long", year: "numeric" });
  if (els.printCalendarLeftMonthLabel) els.printCalendarLeftMonthLabel.textContent = monthLabel(leftMonth);
  if (els.printCalendarRightMonthLabel) els.printCalendarRightMonthLabel.textContent = monthLabel(rightMonth);
  els.printCalendarLeftGrid.innerHTML = printCalendarMonthButtons(leftMonth, today, availableDates, start, end);
  els.printCalendarRightGrid.innerHTML = printCalendarMonthButtons(rightMonth, today, availableDates, start, end);
  if (els.printCalendarFromValue) els.printCalendarFromValue.textContent = start ? formatDisplayDate(start) : "Select start date";
  if (els.printCalendarToValue) els.printCalendarToValue.textContent = end ? formatDisplayDate(end) : "Select end date";
  els.printDateCalendar?.querySelector('[data-print-range-role="from"]')?.classList.toggle("is-active", !start || Boolean(end));
  els.printDateCalendar?.querySelector('[data-print-range-role="to"]')?.classList.toggle("is-active", Boolean(start) && !end);
  if (els.printCalendarSelectionText) {
    if (!start) els.printCalendarSelectionText.textContent = "Choose the Date From.";
    else if (!end) els.printCalendarSelectionText.textContent = `Date From: ${formatDisplayDate(start)}. Now choose the Date To.`;
    else els.printCalendarSelectionText.textContent = `${formatDisplayDate(start)} – ${formatDisplayDate(end)}`;
  }
  if (els.printCalendarApply) els.printCalendarApply.disabled = !(start && end);
}

/** Select one calendar day into the Date From / Date To range draft. */
function choosePrintCalendarDate(dateKey) {
  const key = String(dateKey || "");
  if (!printCalendarDateFromKey(key)) return;
  if (!state.printCalendarDraftStart || state.printCalendarDraftEnd) {
    state.printCalendarDraftStart = key;
    state.printCalendarDraftEnd = "";
  } else if (key < state.printCalendarDraftStart) {
    state.printCalendarDraftEnd = state.printCalendarDraftStart;
    state.printCalendarDraftStart = key;
  } else {
    state.printCalendarDraftEnd = key;
  }
  renderPrintDateCalendar();
}

/** Clear the calendar draft so a new Date From and Date To can be selected. */
function resetPrintCalendarRange() {
  state.printCalendarDraftStart = "";
  state.printCalendarDraftEnd = "";
  renderPrintDateCalendar();
}

/** Move the visible two-month calendar by one month. */
function movePrintCalendarMonth(offset) {
  const month = printCalendarMonthDate(state.printCalendarMonth || state.printCalendarDraftStart);
  month.setMonth(month.getMonth() + Number(offset || 0));
  state.printCalendarMonth = printCalendarDateKey(month);
  renderPrintDateCalendar();
}

/** Apply the complete Date From / Date To range and rebuild all dependent choices. */
function applyPrintCalendarSelection() {
  const start = String(state.printCalendarDraftStart || "");
  const end = String(state.printCalendarDraftEnd || "");
  if (!start || !end) return;
  if (els.printDateFrom) els.printDateFrom.value = start <= end ? start : end;
  if (els.printDateTo) els.printDateTo.value = start <= end ? end : start;
  renderPrintQuickDateOptions();
  closePrintDateCalendar();
  state.printPreviewPage = 1;
  renderPrintFilterChoices({ preserveSelections: true }).catch((error) => showInlineError(error.message, false));
}

/** Show explicit loading content so filter failures never look like empty sections. */
function setPrintFilterLoadingState() {
  const loading = '<div class="print-filter-empty-v197 is-loading">Loading current delivery-list choices…</div>';
  for (const container of [els.printRouteOptions, els.printStatusOptions, els.printAttentionOptions, els.printOptionsGlassType]) {
    if (container) container.innerHTML = loading;
  }
}

/** Render destination routes and all date/route-dependent filter choices. */
async function renderPrintFilterChoices({ preserveSelections = true, captureControlSelections = preserveSelections } = {}) {
  window.clearTimeout(state.printPreviewTimer);
  state.printPreviewRequestId += 1;
  // Capture live controls only for an established workspace. Initial/default
  // rendering starts from committed state so stale markup from a prior open
  // cannot overwrite Airport before the first preview is ready. Preview
  // Preview filtering must never depend on detached DOM.
  if (captureControlSelections) {
    // Route and Glass Type state are committed only by their own change handlers.
    // Date, route, orientation, and catalog rerenders must preserve the preset's
    // semantic glass-family rule instead of replacing it with today's exact rows.
  }
  const listIds = selectedPrintListIds();
  const renderId = ++state.printEntityRenderId;
  const previousRoutes = new Set(selectedPrintRouteGroups());
  const previousStatuses = new Set(selectedPrintFilterValues(els.printStatusOptions, 'input[data-print-status]'));
  const previousAttention = new Set(selectedPrintFilterValues(els.printAttentionOptions, 'input[data-print-attention]'));
  const previousGlass = new Set(selectedPrintGlassTypeValues());
  const previousGlassKeys = new Set([...previousGlass].map(printGlassTypeMatchKey));
  const previousAllGlass = allPrintGlassTypesSelected();

  setPrintFilterLoadingState();
  hidePrintSearchSuggestions();

  if (!listIds.length) {
    const message = state.printContext?.fixedListIds
      ? "The requested delivery lists are unavailable."
      : "No Airport Outbound delivery list is available in this date selection.";
    for (const container of [els.printRouteOptions, els.printStatusOptions, els.printAttentionOptions, els.printOptionsGlassType]) {
      if (container) container.innerHTML = `<div class="print-filter-empty-v197">${escapeHtml(message)}</div>`;
    }
    renderEmptyPrintSelectionPreview();
    return;
  }

  try {
    await ensurePrintListDetails(listIds);
  } catch (error) {
    if (renderId !== state.printEntityRenderId) return;
    const message = `<div class="print-filter-empty-v197 is-error">Could not load filter choices. ${escapeHtml(error.message)}</div>`;
    for (const container of [els.printRouteOptions, els.printStatusOptions, els.printAttentionOptions, els.printOptionsGlassType]) {
      if (container) container.innerHTML = message;
    }
    renderEmptyPrintSelectionPreview();
    return;
  }
  if (renderId !== state.printEntityRenderId) return;

  const baseRows = printBaseRows(listIds);
  const routeCounts = new Map(PRINT_ROUTE_GROUPS.map(({ value }) => [value, 0]));
  routeCounts.set("airport", baseRows.reduce((sum, { item }) => sum + itemPieceQty(item), 0));
  for (const { item } of baseRows) {
    const group = printRouteGroupForItem(item);
    routeCounts.set(group, (routeCounts.get(group) || 0) + itemPieceQty(item));
  }

  const validRouteValues = new Set(PRINT_ROUTE_GROUPS.map(({ value }) => value));
  let selectedRoutes = preserveSelections
    ? [...previousRoutes].filter((value) => validRouteValues.has(value) && Number(routeCounts.get(value) || 0) > 0)
    : [];
  if (!selectedRoutes.length) {
    const fallbackRoute = PRINT_ROUTE_GROUPS.find(({ value }) => Number(routeCounts.get(value) || 0) > 0)?.value || "airport";
    selectedRoutes = [fallbackRoute];
  }
  setPrintRouteGroups(selectedRoutes, { syncControls: false });

  if (els.printRouteOptions) {
    els.printRouteOptions.innerHTML = PRINT_ROUTE_GROUPS.map(({ value, label }) => {
      const count = routeCounts.get(value) || 0;
      return printFilterChipMarkup({
        value,
        label,
        count,
        checked: selectedRoutes.includes(value),
        disabled: count <= 0,
        type: `route-${value.replaceAll("_", "-")}`,
        data: 'data-print-route-group="1"',
      });
    }).join("");
  }

  const scopedRows = printRowsForSelectedRoutes(baseRows, selectedRoutes);
  const glassCounts = new Map();
  const statusCounts = new Map([["not-scanned", 0], ["partial", 0], ["complete", 0]]);
  const attentionCounts = new Map([["remake", 0], ["rush", 0], ["reject", 0], ["updated", 0], ["error", 0]]);

  for (const { item } of scopedRows) {
    const qty = itemPieceQty(item);
    const glass = glassTypeLabel(item) || "Other Glass";
    glassCounts.set(glass, (glassCounts.get(glass) || 0) + qty);
    const status = printItemStatusKey(item);
    statusCounts.set(status, (statusCounts.get(status) || 0) + qty);
    for (const key of printItemAttentionKeys(item)) attentionCounts.set(key, (attentionCounts.get(key) || 0) + qty);
  }

  const scopedPieceCount = scopedRows.reduce((sum, { item }) => sum + itemPieceQty(item), 0);
  const statusDefinitions = [
    ["not-scanned", "Not Scanned"],
    ["partial", "Partial"],
    ["complete", "Complete"],
  ];
  const availableSelectedStatuses = statusDefinitions
    .map(([value]) => value)
    .filter((value) => previousStatuses.has(value) && Number(statusCounts.get(value) || 0) > 0);
  const statusAllSelected = !preserveSelections || previousStatuses.has("__all__") || !availableSelectedStatuses.length;
  if (els.printStatusOptions) {
    els.printStatusOptions.innerHTML = `${printFilterChipMarkup({
      value: "__all__",
      label: "All Status",
      count: scopedPieceCount,
      checked: statusAllSelected,
      disabled: scopedPieceCount <= 0,
      type: "status-all",
      data: 'data-print-status="1" data-print-status-all="1"',
    })}${statusDefinitions.map(([value, label]) => {
      const count = statusCounts.get(value) || 0;
      return printFilterChipMarkup({
        value,
        label,
        count,
        checked: !statusAllSelected && availableSelectedStatuses.includes(value),
        disabled: count <= 0,
        type: `status-${value}`,
        data: 'data-print-status="1"',
      });
    }).join("")}`;
  }

  const attentionDefinitions = [
    ["remake", "Remakes", true],
    ["rush", "Rushes", true],
    ["reject", "Internal Rejects", true],
    ["updated", "New/Updated", false],
    ["error", "Errors", false],
  ];
  const availableSelectedAttention = attentionDefinitions
    .map(([value, , showHealthState]) => ({ value, showHealthState }))
    .filter(({ value, showHealthState }) => previousAttention.has(value) && (showHealthState || Number(attentionCounts.get(value) || 0) > 0))
    .map(({ value }) => value);
  const attentionAllSelected = !preserveSelections || previousAttention.has("__all__") || !availableSelectedAttention.length;
  if (els.printAttentionOptions) {
    els.printAttentionOptions.innerHTML = `${printFilterChipMarkup({
      value: "__all__",
      label: "All Attention",
      count: scopedPieceCount,
      checked: attentionAllSelected,
      disabled: scopedPieceCount <= 0,
      type: "attention-all",
      data: 'data-print-attention="1" data-print-attention-all="1"',
    })}${attentionDefinitions.map(([value, label, showHealthState]) => {
      const count = attentionCounts.get(value) || 0;
      return printFilterChipMarkup({
        value,
        label,
        count,
        checked: !attentionAllSelected && availableSelectedAttention.includes(value),
        disabled: !showHealthState && count <= 0,
        type: `attention-${value}`,
        data: 'data-print-attention="1"',
        state: showHealthState ? (count > 0 ? "alert" : "clear") : "",
      });
    }).join("")}`;
  }

  const glassEntries = [...glassCounts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
  if (els.printOptionsGlassType) {
    const totalPieces = glassEntries.reduce((sum, entry) => sum + Number(entry[1] || 0), 0);
    const ruleTypeKeys = new Set((state.printGlassRuleTypes || []).map(printGlassTypeMatchKey));
    const ruleActive = hasPrintGlassSelectionRule();
    const matchedGlassLabels = glassEntries
      .map(([label]) => label)
      .filter((label) => ruleActive
        ? printGlassMatchesFamilyRule(label) || ruleTypeKeys.has(printGlassTypeMatchKey(label))
        : previousGlassKeys.has(printGlassTypeMatchKey(label)));
    // A semantic family preset may legitimately match zero products on one date.
    // Keep it restrictive so returning to another date automatically restores the
    // family instead of silently switching the preset to All Glass.
    const selectAllCurrent = !preserveSelections || (!ruleActive && (previousAllGlass || !matchedGlassLabels.length));
    const selectedKeys = new Set(matchedGlassLabels.map(printGlassTypeMatchKey));
    const glassMarkup = printGlassCategoryMarkup(glassEntries, selectedKeys, selectAllCurrent);
    els.printOptionsGlassType.innerHTML = glassEntries.length
      ? `${printFilterChipMarkup({ value: "__all__", label: "All Glass", count: totalPieces, checked: selectAllCurrent, type: "glass-all", data: 'data-print-all-glass="1"' })}${glassMarkup}`
      : '<div class="print-filter-empty-v197">No glass types exist for the selected date and route.</div>';
    state.printAllGlass = selectAllCurrent;
    state.printGlassTypes = selectAllCurrent ? [] : matchedGlassLabels;
  }

  renderPrintSelectedOrders();
  renderPrintSearchSuggestions();
  schedulePrintSelectionPreview(0);
}

/** Keep All Glass selected only when no exact glass types are selected. */
function updatePrintAllGlassState() {
  const allInput = els.printOptionsGlassType?.querySelector('input[data-print-all-glass]');
  const inputs = selectedPrintGlassInputs();
  if (!allInput) return;
  if (allInput.checked) inputs.forEach((input) => { input.checked = false; });
  if (!inputs.some((input) => input.checked)) allInput.checked = true;
  allInput.indeterminate = false;
  commitPrintGlassSelectionFromControls();
}


/** Return exact order numbers selected for the current package. */
function selectedPrintOrderValues() {
  return [...new Set((state.printSelectedOrders || []).map((entry) => String(entry.order || "").replace(/\D/g, "")).filter(Boolean))];
}

/** Return exact line-item selection keys selected for the current package. */
function selectedPrintItemValues() {
  return [...new Set((state.printSelectedItems || []).map((entry) => String(entry.selectionKey || "").trim()).filter(Boolean))];
}

/** Return a stable row key even when an older imported row has no line-item ID. */
function printRowSelectionKey(list, item) {
  const lineItemId = String(item?.id || item?.lineItemId || "").trim();
  if (lineItemId) return lineItemId;
  const order = String(item?.order || "").replace(/\D/g, "");
  const itemNo = String(item?.item || "").replace(/\D/g, "");
  return `${String(list?.id || "").trim()}|${order}|${itemNo}`;
}

/** Return the portable list/order/item key used as a backend fallback. */
function printPortableRowKey(list, item) {
  const order = String(item?.order || "").replace(/\D/g, "");
  const itemNo = String(item?.item || "").replace(/\D/g, "");
  return `${String(list?.id || "").trim()}|${order}|${itemNo}`;
}

/** Build order-level and exact-item catalogs from the selected dates and routes. */
function printSelectionCatalog() {
  const orders = new Map();
  const items = new Map();
  const rows = printRowsForSelectedRoutes(printBaseRows(selectedPrintListIds()));
  for (const { list, item } of rows) {
    const order = String(item.order || "").replace(/\D/g, "");
    const itemNo = String(item.item || "").replace(/\D/g, "");
    if (!order) continue;
    if (!orders.has(order)) {
      orders.set(order, {
        order,
        customers: new Set(),
        jobs: new Set(),
        dates: new Set(),
        pieces: 0,
        rowCount: 0,
      });
    }
    const orderEntry = orders.get(order);
    const customer = String(item.customer || "").trim();
    const job = String(item.job || item.product || "").trim();
    if (customer) orderEntry.customers.add(customer);
    if (job) orderEntry.jobs.add(job);
    if (list?.deliveryDate) orderEntry.dates.add(String(list.deliveryDate));
    orderEntry.pieces += itemPieceQty(item);
    orderEntry.rowCount += 1;

    const selectionKey = printRowSelectionKey(list, item);
    items.set(selectionKey, {
      selectionKey,
      lineItemId: String(item.id || item.lineItemId || "").trim(),
      rowKey: printPortableRowKey(list, item),
      listId: String(list?.id || ""),
      deliveryDate: String(list?.deliveryDate || ""),
      order,
      item: itemNo,
      customer: customer || "Unassigned customer",
      job: job || "No Job Nr.",
      glassType: glassTypeLabel(item),
      pieces: itemPieceQty(item),
      available: true,
    });
  }
  return { orders, items };
}

/** Convert one order into stored selected-order metadata. */
function printSelectedOrderRecord(order, catalog = printSelectionCatalog().orders) {
  const normalized = String(order || "").replace(/\D/g, "");
  const source = catalog.get(normalized);
  const existing = (state.printSelectedOrders || []).find((entry) => String(entry.order || "") === normalized);
  if (!source) return existing ? { ...existing, available: false, pieces: 0 } : { order: normalized, customer: "", job: "", pieces: 0, available: false };
  return {
    order: normalized,
    customer: [...source.customers].join(", ") || "Unassigned customer",
    job: [...source.jobs].slice(0, 3).join(", ") || "No Job Nr.",
    pieces: source.pieces,
    rowCount: source.rowCount,
    available: true,
  };
}

/** Convert one exact line item into stored selected-item metadata. */
function printSelectedItemRecord(selectionKey, catalog = printSelectionCatalog().items) {
  const cleanKey = String(selectionKey || "").trim();
  const source = catalog.get(cleanKey);
  const existing = (state.printSelectedItems || []).find((entry) => String(entry.selectionKey || "") === cleanKey);
  if (!source) return existing ? { ...existing, available: false, pieces: 0 } : { selectionKey: cleanKey, order: "", item: "", customer: "", job: "", pieces: 0, available: false };
  return { ...source };
}

/** Render removable whole-order and exact-item selections. */
function renderPrintSelectedOrders() {
  const catalog = printSelectionCatalog();
  state.printSelectedOrders = selectedPrintOrderValues().map((order) => printSelectedOrderRecord(order, catalog.orders));
  state.printSelectedItems = selectedPrintItemValues().map((key) => printSelectedItemRecord(key, catalog.items));
  const selectionCount = state.printSelectedOrders.length + state.printSelectedItems.length;
  if (els.printSelectedOrdersCount) els.printSelectedOrdersCount.textContent = String(selectionCount);
  if (els.printSelectedOrdersClear) els.printSelectedOrdersClear.disabled = !selectionCount;
  if (els.printOrderFilter) els.printOrderFilter.value = selectedPrintOrderValues().join(",");
  if (!els.printSelectedOrdersList) return;

  const orderCards = state.printSelectedOrders.map((entry) => `
    <article class="print-selected-order-v199 ${entry.available ? "" : "is-unavailable"}">
      <div>
        <strong>Complete Order ${escapeHtml(entry.order)}</strong>
        <span>${escapeHtml(entry.customer || "Unassigned customer")}</span>
        <small>${escapeHtml(entry.job || "No Job Nr.")} · ${escapeHtml(entry.available ? `${entry.pieces} pieces` : "Not in the current date/route selection")}</small>
      </div>
      <button type="button" data-print-remove-order="${escapeHtml(entry.order)}" aria-label="Remove order ${escapeHtml(entry.order)}">×</button>
    </article>
  `);
  const itemCards = state.printSelectedItems.map((entry) => `
    <article class="print-selected-order-v199 print-selected-item-v202 ${entry.available ? "" : "is-unavailable"}">
      <div>
        <strong>Order ${escapeHtml(entry.order || "—")} · Item ${escapeHtml(entry.item || "—")}</strong>
        <span>${escapeHtml(entry.customer || "Unassigned customer")}</span>
        <small>${escapeHtml(entry.job || "No Job Nr.")} · ${escapeHtml(entry.available ? `${entry.pieces} pieces · ${entry.glassType || "Glass"}` : "Not in the current date/route selection")}</small>
      </div>
      <button type="button" data-print-remove-item="${escapeHtml(entry.selectionKey)}" aria-label="Remove selected item">×</button>
    </article>
  `);
  els.printSelectedOrdersList.innerHTML = selectionCount
    ? [...orderCards, ...itemCards].join("")
    : '<div class="print-selected-orders-empty-v199">No specific orders or items selected. Every row matching the other filters is included.</div>';
}

/** Add one complete order and remove redundant exact items from that order. */
function addPrintSelectedOrder(order) {
  const normalized = String(order || "").replace(/\D/g, "");
  if (!normalized || selectedPrintOrderValues().includes(normalized)) return;
  state.printSelectedOrders.push(printSelectedOrderRecord(normalized));
  state.printSelectedItems = (state.printSelectedItems || []).filter((entry) => String(entry.order || "") !== normalized);
  renderPrintSelectedOrders();
  renderPrintSearchSuggestions();
  els.printSearchInput?.focus({ preventScroll: true });
  schedulePrintSelectionPreview(0);
}

/** Add one exact order/item row without expanding to the whole order. */
function addPrintSelectedItem(selectionKey) {
  const cleanKey = String(selectionKey || "").trim();
  const catalog = printSelectionCatalog();
  const entry = catalog.items.get(cleanKey);
  if (!entry || selectedPrintItemValues().includes(cleanKey) || selectedPrintOrderValues().includes(entry.order)) return;
  state.printSelectedItems.push({ ...entry });
  renderPrintSelectedOrders();
  renderPrintSearchSuggestions();
  els.printSearchInput?.focus({ preventScroll: true });
  schedulePrintSelectionPreview(0);
}

/** Remove one exact order from the current selection. */
function removePrintSelectedOrder(order) {
  const normalized = String(order || "").replace(/\D/g, "");
  state.printSelectedOrders = (state.printSelectedOrders || []).filter((entry) => String(entry.order || "") !== normalized);
  renderPrintSelectedOrders();
  renderPrintSearchSuggestions();
  schedulePrintSelectionPreview(0);
}

/** Remove one exact line-item selection. */
function removePrintSelectedItem(selectionKey) {
  const cleanKey = String(selectionKey || "").trim();
  state.printSelectedItems = (state.printSelectedItems || []).filter((entry) => String(entry.selectionKey || "") !== cleanKey);
  renderPrintSelectedOrders();
  renderPrintSearchSuggestions();
  schedulePrintSelectionPreview(0);
}

/** Clear every exact order and item selection without changing other filters. */
function clearPrintSelectedOrders() {
  state.printSelectedOrders = [];
  state.printSelectedItems = [];
  renderPrintSelectedOrders();
  renderPrintSearchSuggestions();
  schedulePrintSelectionPreview(0);
}

/** Hide the smart order/item search panel. */
function hidePrintSearchSuggestions() {
  if (!els.printSearchSuggestions) return;
  els.printSearchSuggestions.hidden = true;
  els.printSearchSuggestions.replaceChildren();
}

/** Render smart order/item suggestions from the selected dates and routes. */
function renderPrintSearchSuggestions() {
  if (!els.printSearchSuggestions || !els.printSearchInput) return;
  const query = String(els.printSearchInput.value || "").trim().toLowerCase();
  if (!query) {
    hidePrintSearchSuggestions();
    return;
  }
  const digits = query.replace(/\D/g, "");
  const selectedOrders = new Set(selectedPrintOrderValues());
  const selectedItems = new Set(selectedPrintItemValues());
  const catalog = printSelectionCatalog();
  const suggestions = [];
  for (const entry of catalog.items.values()) {
    const haystack = `${entry.order} ${entry.item} ${entry.customer} ${entry.job} ${entry.glassType}`.toLowerCase();
    const matches = haystack.includes(query) || Boolean(digits && (`${entry.order}${entry.item}`.includes(digits) || entry.order.includes(digits) || entry.item === digits));
    if (!matches) continue;
    const starts = entry.order.startsWith(digits) || entry.item.startsWith(digits) || entry.customer.toLowerCase().startsWith(query) || entry.job.toLowerCase().startsWith(query);
    suggestions.push({ ...entry, starts });
  }
  suggestions.sort((a, b) => Number(b.starts) - Number(a.starts) || a.order.localeCompare(b.order) || Number(a.item || 0) - Number(b.item || 0));
  const visible = suggestions.slice(0, 18);
  els.printSearchSuggestions.innerHTML = visible.length
    ? visible.map((entry) => {
      const orderSelected = selectedOrders.has(entry.order);
      const itemSelected = selectedItems.has(entry.selectionKey) || orderSelected;
      return `
        <article class="print-search-result-v202">
          <div class="print-search-result-info-v236">
            <div class="print-search-result-title-v236">
              <strong>Order ${escapeHtml(entry.order)}</strong>
              <span>Item ${escapeHtml(entry.item || "—")}</span>
            </div>
            <div class="print-search-result-meta-v236">
              <span><small>Customer</small><b>${escapeHtml(entry.customer)}</b></span>
              <span><small>Job</small><b>${escapeHtml(entry.job)}</b></span>
              <span><small>Glass</small><b>${escapeHtml(entry.glassType || "Glass")}</b></span>
              <span><small>QTY</small><b>${escapeHtml(entry.pieces)}</b></span>
              <span><small>Date</small><b>${escapeHtml(formatDisplayDate(entry.deliveryDate || ""))}</b></span>
            </div>
          </div>
          <div class="print-search-result-actions-v202">
            <button type="button" data-print-add-item="${escapeHtml(entry.selectionKey)}" ${itemSelected ? "disabled" : ""}>${itemSelected ? "Item Added" : "Add Item"}</button>
            <button type="button" data-print-add-order="${escapeHtml(entry.order)}" ${orderSelected ? "disabled" : ""}>${orderSelected ? "Order Added" : "Add Order"}</button>
          </div>
        </article>`;
    }).join("")
    : '<div class="print-search-empty-v198">No additional matching orders or items exist in the selected dates and routes.</div>';
  els.printSearchSuggestions.hidden = false;
}

/** Ensure current list rows are loaded before producing smart order/item suggestions. */
async function refreshPrintSearchSuggestions() {
  const query = String(els.printSearchInput?.value || "").trim();
  if (!query) { hidePrintSearchSuggestions(); return; }
  try {
    await ensurePrintListDetails(selectedPrintListIds());
    renderPrintSearchSuggestions();
  } catch (error) {
    if (els.printSearchSuggestions) {
      els.printSearchSuggestions.innerHTML = `<div class="print-search-empty-v198">Could not search current delivery lists. ${escapeHtml(error.message)}</div>`;
      els.printSearchSuggestions.hidden = false;
    }
  }
}

/** Return true when one row is included by the exact order/item picker. */
function printRowMatchesExactSelection(list, item) {
  const selectedOrders = new Set(selectedPrintOrderValues());
  const selectedItems = new Set(selectedPrintItemValues());
  if (!selectedOrders.size && !selectedItems.size) return true;
  const order = String(item?.order || "").replace(/\D/g, "");
  return selectedOrders.has(order) || selectedItems.has(printRowSelectionKey(list, item));
}

/** Return the exact loaded rows represented by every visible Print / Export filter. */
function printFilteredRows() {
  const selectedRoutes = selectedPrintRouteGroups();
  const allGlass = allPrintGlassTypesSelected();
  const selectedGlass = new Set(selectedPrintGlassTypeValues().map(printGlassTypeMatchKey));
  const selectedStatuses = new Set(selectedPrintStatusValues());
  const selectedAttention = new Set(selectedPrintAttentionValues());
  return printRowsForSelectedRoutes(printBaseRows(selectedPrintListIds()), selectedRoutes).filter(({ list, item }) => {
    if (!allGlass && selectedGlass.size && !selectedGlass.has(printGlassTypeMatchKey(glassTypeLabel(item)))) return false;
    if (!allGlass && !selectedGlass.size) return false;
    if (selectedStatuses.size && !selectedStatuses.has(printItemStatusKey(item))) return false;
    if (selectedAttention.size && !printItemAttentionKeys(item).some((key) => selectedAttention.has(key))) return false;
    if (!printRowMatchesExactSelection(list, item)) return false;
    if (state.printContext?.updatedOnly && !/\b(update|updated|new|change|changed|added|add)\b/i.test(`${item.processState || ""} ${item.queueState || ""}`)) return false;
    return true;
  });
}

/** Build the exact backend filter contract shared by preview, print, and exports. */
function printSelectionFilters(filteredRows = printFilteredRows()) {
  const glassTypes = selectedPrintGlassTypeValues();
  const statuses = selectedPrintStatusValues();
  const attention = selectedPrintAttentionValues();
  const orders = selectedPrintOrderValues();
  const selectedItems = (state.printSelectedItems || []).filter((entry) => entry.order && entry.item);
  const filters = {
    glassTypesExact: allPrintGlassTypesSelected() ? "" : JSON.stringify(glassTypes),
    routeGroupsExact: JSON.stringify(selectedPrintRouteGroups()),
    statusesExact: statuses.length ? JSON.stringify(statuses) : "",
    attentionExact: attention.length ? JSON.stringify(attention) : "",
    ordersExact: orders.length ? JSON.stringify(orders) : "",
    orderItemsExact: selectedItems.length ? JSON.stringify(selectedItems.map((entry) => `${entry.order}|${entry.item}`)) : "",
    mirrorMode: "include",
  };
  if (state.printContext?.updatedOnly) filters.updatedOnly = "true";
  return filters;
}

/** Build the POST payload that locks preview and output to the same exact rows. */
function printBackendSelectionPayload() {
  const rows = printFilteredRows();
  return {
    listIds: selectedPrintListIds(),
    filters: printSelectionFilters(rows),
    lineItemIds: [...new Set(rows.map(({ item }) => String(item?.id || item?.lineItemId || "").trim()).filter(Boolean))],
    rowKeys: [...new Set(rows.map(({ list, item }) => printPortableRowKey(list, item)).filter(Boolean))],
    copies: Math.max(Number(els.printCopies?.value || 1), 1),
    orientation: String(els.printOrientation?.value || "portrait"),
  };
}

/** Return the short stage title used by the maintained printed delivery list. */
function printSheetStageName(list) {
  const category = stageCategory(list);
  return { outbound: "Outbound", staging: "Staging", received: "Indian Trail", pickup: "CPU", greenville: "BFS Greenville", dtc: "DTC" }[category]
    || String(list?.stage || list?.label || "Delivery List").split(" - ")[0].trim();
}

/** Return the full weekday date used beneath the printed destination title. */
function printSheetDateLabel(value) {
  return formatDisplayDate(value);
}

/** Describe the maintained destination selection in the printed title. */
function printSheetRouteLabel(routeGroups = selectedPrintRouteGroups()) {
  const labels = new Map(PRINT_ROUTE_GROUPS.map(({ value, label }) => [value, label]));
  const selected = normalizePrintRouteGroups(routeGroups).map((value) => labels.get(value)).filter(Boolean);
  return (selected.length ? selected : ["Airport"]).join(" | ");
}

/** Build the route-driven uppercase heading used by preview and paper output. */
function printSheetTitleLabel(routeGroups = selectedPrintRouteGroups()) {
  return `${printSheetRouteLabel(routeGroups).toLocaleUpperCase()} DELIVERY LIST`;
}

/** Convert one loaded row into the common preview/print row contract. */
function printPreviewRow(list, item) {
  const statusKey = printItemStatusKey(item);
  return {
    listId: String(list.id || ""),
    lineItemId: String(item.id || item.lineItemId || ""),
    rowKey: printPortableRowKey(list, item),
    order: String(item.order || ""),
    item: String(item.item || ""),
    job: String(item.job || item.product || ""),
    customer: String(item.customer || ""),
    deliveryDate: String(list.deliveryDate || ""),
    pieces: itemPieceQty(item),
    glassType: glassTypeLabel(item),
    dimensions: String(item.dimensions || ""),
    statusKey,
    statusLabel: { "not-scanned": "Not Scanned", partial: "Partial", complete: "Complete" }[statusKey],
    attention: printItemAttentionKeys(item).map((key) => ({ key, label: { remake: "Remakes", rush: "Rushes", reject: "Internal Rejects", updated: "New/Updated", error: "Errors" }[key] || key })),
    route: String(item.route || "Indian Trail"),
  };
}

/** Build sheet groups that follow the maintained normal, Rush, and remake print order. */
function buildLocalPrintSheets(filteredRows) {
  const rowsByList = new Map();
  const filterSummary = printCurrentFilterSummary();
  for (const row of filteredRows) {
    if (!rowsByList.has(row.list.id)) rowsByList.set(row.list.id, []);
    rowsByList.get(row.list.id).push(row);
  }
  const sheets = [];
  for (const list of printSelectedLists(selectedPrintListIds())) {
    const source = rowsByList.get(list.id) || [];
    const normal = [];
    const rush = [];
    const remake = [];
    for (const { item } of source) {
      const keys = printItemAttentionKeys(item);
      if (keys.includes("remake")) remake.push(printPreviewRow(list, item));
      else if (keys.includes("rush")) rush.push(printPreviewRow(list, item));
      else normal.push(printPreviewRow(list, item));
    }
    const stageName = printSheetStageName(list);
    const dateText = formatDisplayDate(list.deliveryDate || "");
    const addSheet = (mode, rows) => {
      if (!rows.length) return;
      const updated = Boolean(state.printContext?.updatedOnly);
      const title = mode === "rush"
        ? `${stageName} Rush Sheet for ${dateText}`
        : mode === "remake"
          ? `${stageName} Remake Sheet for ${dateText}`
          : updated
            ? `${stageName} Updated Delivery List for ${dateText}`
            : `${stageName} Delivery List for ${dateText}`;
      sheets.push({
        listId: String(list.id || ""),
        stageName,
        deliveryDate: String(list.deliveryDate || ""),
        dateLabel: printSheetDateLabel(list.deliveryDate || ""),
        routeLabel: printSheetRouteLabel(),
        titleLabel: printSheetTitleLabel(),
        mode,
        title,
        badge: mode === "rush" ? "RUSH" : mode === "remake" ? "REMAKE" : updated ? "UPDATED" : "",
        filterSummary,
        rows: rows.sort((a, b) => String(a.glassType).localeCompare(String(b.glassType)) || Number(a.order || 0) - Number(b.order || 0) || Number(a.item || 0) - Number(b.item || 0)),
      });
    };
    addSheet("normal", normal);
    addSheet("rush", rush);
    addSheet("remake", remake);
  }
  return sheets;
}

/** Build an immediate preview from the exact loaded rows that the browser will print. */
function buildLocalPrintSelectionPreview() {
  const filteredRows = printFilteredRows();
  const previewRows = filteredRows.map(({ list, item }) => printPreviewRow(list, item));
  const previewSheets = buildLocalPrintSheets(filteredRows);
  const orientation = String(els.printOrientation?.value || "portrait") === "landscape" ? "landscape" : "portrait";
  const pageCount = previewSheets.reduce((sum, sheet) => sum + paginatePrintSheetRows(sheet.rows, orientation).length, 0);
  return {
    generatedAt: new Date().toISOString(),
    totalPieces: previewRows.reduce((sum, row) => sum + Number(row.pieces || 0), 0),
    rowCount: previewRows.length,
    orderCount: new Set(previewRows.map((row) => row.order).filter(Boolean)).size,
    customerCount: new Set(previewRows.map((row) => row.customer).filter(Boolean)).size,
    pageCount: Math.max(pageCount, 1),
    filterSummary: printCurrentFilterSummary(),
    previewRows,
    previewSheets,
    noResults: previewRows.length === 0,
    localPreview: true,
  };
}

/** Format the preview's generated timestamp. */
function printPreviewTimestamp(value) {
  const parsed = new Date(value || Date.now());
  if (Number.isNaN(parsed.getTime())) return "";
  return parsed.toLocaleString([], { month: "short", day: "numeric", year: "numeric", hour: "numeric", minute: "2-digit" });
}

/** Compress one filter group into a readable print-header value. */
function printCompactFilterValue(values, allLabel, labels = {}, countedLabel = "selected") {
  const selected = [...new Set((values || []).map((value) => String(value || "").trim()).filter(Boolean))];
  if (!selected.length) return allLabel;
  const display = selected.map((value) => labels[value] || value);
  if (display.length <= 2) return display.join(", ");
  return `${display.length} ${countedLabel}`;
}

/** Build a route-free list of only the unique filters that narrow the output. */
function printCurrentFilterSummary() {
  const statusLabels = { "not-scanned": "Not Scanned", partial: "Partial", complete: "Complete" };
  const attentionLabels = { remake: "Remakes", rush: "Rushes", reject: "Internal Rejects", updated: "New/Updated", error: "Errors" };
  const parts = [];
  const glassTypes = allPrintGlassTypesSelected() ? [] : selectedPrintGlassTypeValues();
  const statuses = selectedPrintStatusValues();
  const attention = selectedPrintAttentionValues();
  if (glassTypes.length) parts.push(printCompactFilterValue(glassTypes, "", {}, "glass types"));
  if (statuses.length) parts.push(printCompactFilterValue(statuses, "", statusLabels, "statuses"));
  if (attention.length) parts.push(printCompactFilterValue(attention, "", attentionLabels, "attention filters"));

  const exactOrders = selectedPrintOrderValues();
  const exactItems = selectedPrintItemValues();
  const exactSelectionCount = exactOrders.length + exactItems.length;
  if (exactOrders.length === 1 && !exactItems.length) parts.push(`Order ${exactOrders[0]}`);
  else if (exactSelectionCount) parts.push(`${exactSelectionCount} exact selection${exactSelectionCount === 1 ? "" : "s"}`);
  if (state.printContext?.updatedOnly) parts.push("Updated only");

  const seen = new Set();
  const uniqueParts = parts.filter((part) => {
    const key = String(part || "").trim().toLocaleLowerCase();
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
  return `Filters: ${uniqueParts.length ? uniqueParts.join(" | ") : "All items"}`;
}

/** Paginate rows using page-height limits designed for each paper orientation. */
function paginatePrintSheetRows(rows, orientation = "portrait") {
  const landscape = String(orientation || "portrait") === "landscape";
  const pages = [];
  let current = [];
  let count = 0;
  let currentGlass = "";
  // v0.225 keeps the verified portrait limits and the 27-row landscape first
  // page, while reducing landscape continuation pages by one logical line.
  // Glass headings still consume one logical line so the final order row stays
  // above the fixed footer and printer-safe margin.
  const limit = () => landscape
    ? (pages.length ? 28 : 27)
    : (pages.length ? 28 : 26);
  const flush = () => { if (current.length) pages.push(current); current = []; count = 0; currentGlass = ""; };
  for (const row of rows || []) {
    const glass = String(row.glassType || "Unspecified Glass");
    let groupNeeded = glass !== currentGlass;
    if (current.length && count + 1 + (groupNeeded ? 1 : 0) > limit()) { flush(); groupNeeded = true; }
    if (groupNeeded) { current.push({ type: "group", glassType: glass }); count += 1; currentGlass = glass; }
    if (current.length && count >= limit()) { flush(); current.push({ type: "group", glassType: glass }); count += 1; currentGlass = glass; }
    current.push({ type: "row", row });
    count += 1;
  }
  flush();
  return pages.length ? pages : [[]];
}

function printSheetBodyMarkup(pageRows) {
  let visibleRowIndex = 0;
  return (pageRows || []).map((entry) => {
    if (entry.type === "group") return `<tr class="glass-group"><td colspan="8">${escapeHtml(entry.glassType)}</td></tr>`;
    const row = entry.row || {};
    const stripeClass = visibleRowIndex % 2 ? "is-even" : "is-odd";
    visibleRowIndex += 1;
    return `<tr class="print-data-row ${stripeClass}"><td class="print-truncate">${escapeHtml(row.job || row.glassType || "")}</td><td>${escapeHtml(row.order || "")}</td><td>${escapeHtml(row.item || "")}</td><td>${escapeHtml(row.pieces || 0)}</td><td class="print-truncate">${escapeHtml(row.dimensions || "")}</td><td class="print-truncate">${escapeHtml(row.customer || "")}</td><td>${escapeHtml(row.route || "Indian Trail")}</td><td class="check-cell">☐</td></tr>`;
  }).join("");
}

/** Return the exact visual sheet markup shared by the screen preview and the print popup. */
function printSheetPageMarkup(sheet, pageRows, pageNumber, pageTotal, orientation, generatedAt, previewClass = "") {
  const continuation = pageNumber > 1;
  const badge = sheet.badge ? `<span class="sheet-badge">${escapeHtml(sheet.badge)}</span>` : "";
  const rows = Array.isArray(sheet.rows) ? sheet.rows : [];
  const printableRows = rows.length;
  const totalOrders = new Set(rows.map((row) => String(row.order || "").trim()).filter(Boolean)).size;
  const totalQty = rows.reduce((sum, row) => sum + Number(row.pieces || 0), 0);
  const filterSummary = String(sheet.filterSummary || printCurrentFilterSummary());
  const dateLabel = String(sheet.dateLabel || printSheetDateLabel(sheet.deliveryDate || ""));
  const routeLabel = String(sheet.routeLabel || printSheetRouteLabel());
  const titleLabel = String(sheet.titleLabel || `${routeLabel.toLocaleUpperCase()} DELIVERY LIST`);
  const titleLengthClass = titleLabel.length > 42 ? "is-long" : titleLabel.length > 28 ? "is-medium" : "";
  const logoUrl = new URL("static/images/barefoot-company-builders-firstsource-print-logo.png?v=20260811-v0.303", window.location.href).href;
  const pageFilterDetails = `<p class="sheet-filter-summary" title="${escapeHtml(filterSummary)}">${escapeHtml(filterSummary)}</p>`;
  const firstPageSignoff = continuation
    ? ""
    : `<div class="sheet-header-signoff"><div class="copy-box"><span>Checked By: <i class="write-line checked-line"></i></span></div></div>`;
  return `<section class="delivery-print-sheet-v203 ${escapeHtml(sheet.mode || "normal")} is-${escapeHtml(orientation)} ${previewClass}">
    <div class="sheet-page-top">List page ${pageNumber} of ${pageTotal}</div>
    <header class="sheet-header ${continuation ? "sheet-header-compact" : ""}">
      <div class="sheet-brand-title">
        <div class="sheet-brand-mark"><img src="${escapeHtml(logoUrl)}" alt="Barefoot Company and Builders FirstSource logo"></div>
        <div class="sheet-title-block"><div class="sheet-location-row ${titleLengthClass}"><${continuation ? "h2" : "h1"} class="sheet-location-title">${escapeHtml(titleLabel)}</${continuation ? "h2" : "h1"}>${badge}</div><p class="sheet-date-title">${escapeHtml(dateLabel)}</p><p class="sheet-totals">Rows: ${printableRows} | Orders: ${totalOrders} | QTY: ${totalQty}</p>${pageFilterDetails}</div>
      </div>
      ${firstPageSignoff}
    </header>
    <table class="delivery-print-table"><colgroup><col class="job-col"><col class="order-col"><col class="item-col"><col class="qty-col"><col class="dimensions-col"><col class="customer-col"><col class="route-col"><col class="check-col"></colgroup><thead><tr><th>Job Nr.</th><th>Order</th><th>Item</th><th>QTY</th><th>Dimensions</th><th>Customer</th><th>Route</th><th>Check</th></tr></thead><tbody>${printSheetBodyMarkup(pageRows)}</tbody></table>
    <footer class="sheet-footer printed-at">Printed at: ${escapeHtml(printPreviewTimestamp(generatedAt))}</footer>
  </section>`;
}

/** Render every actual print sheet and continuation page in one scrollable preview. */
function renderPrintDocumentPreview(preview = {}) {
  if (!els.printDocumentPaper) return;
  const orientation = String(els.printOrientation?.value || "portrait") === "landscape" ? "landscape" : "portrait";
  const copies = Math.max(Number(els.printCopies?.value || 1), 1);
  const sheets = Array.isArray(preview.previewSheets) && preview.previewSheets.length
    ? preview.previewSheets
    : buildLocalPrintSheets(printFilteredRows());
  const pages = [];
  for (const sheet of sheets) {
    const chunks = paginatePrintSheetRows(sheet.rows || [], orientation);
    chunks.forEach((chunk, index) => pages.push(printSheetPageMarkup(sheet, chunk, index + 1, chunks.length, orientation, preview.generatedAt, "is-preview")));
  }
  if (els.printPreviewPageCount) els.printPreviewPageCount.textContent = `${Math.max(pages.length, 1)} page${pages.length === 1 ? "" : "s"} · ${copies} cop${copies === 1 ? "y" : "ies"}`;
  els.printDocumentPaper.classList.toggle("is-landscape", orientation === "landscape");
  els.printDocumentPaper.classList.toggle("is-portrait", orientation !== "landscape");
  els.printDocumentPaper.innerHTML = pages.length ? pages.join("") : `<section class="delivery-print-sheet-v203 is-${orientation} is-preview"><div class="print-paper-empty-v197"><strong>0</strong><h3>No printable rows</h3><p>Selected filters yield 0 results.</p></div></section>`;
}

/** Return the zoom needed to fit one Letter sheet inside the preview width. */
function printPreviewFitZoom(orientation = els.printOrientation?.value || "portrait") {
  const landscape = String(orientation || "portrait") === "landscape";
  const availableWidth = Math.max(Number(els.printDocumentViewport?.clientWidth || 880) - 48, 320);
  const paperWidth = (landscape ? 11 : 8.5) * 96;
  return Math.min(1, Math.max(0.5, availableWidth / paperWidth));
}

/** Apply the current preview zoom without changing the document data. */
function applyPrintPreviewZoom() {
  state.printPreviewZoom = Math.min(Math.max(Number(state.printPreviewZoom || 1), 0.5), 1.45);
  els.printDocumentPaper?.style.setProperty("--print-preview-zoom", String(state.printPreviewZoom));
  if (els.printPreviewZoomLabel) els.printPreviewZoomLabel.textContent = `${Math.round(state.printPreviewZoom * 100)}%`;
}

/** Render a completed exact package preview. */
function renderPrintSelectionPreview(preview = {}, options = {}) {
  state.printPreviewResult = preview;
  const noResults = Boolean(preview.noResults) || Number(preview.totalPieces || 0) === 0;
  if (els.printPreviewState) {
    els.printPreviewState.textContent = options.pending
      ? `Updating · ${Number(preview.totalPieces || 0)} pieces`
      : noResults
        ? "0 results"
        : `${Number(preview.totalPieces || 0)} pieces`;
    els.printPreviewState.className = `print-preview-state-v197 ${options.pending ? "is-loading" : noResults ? "is-zero" : "is-ready"}`;
  }
  if (els.printPreviewZeroMessage) els.printPreviewZeroMessage.hidden = !noResults;
  if (els.printOptionsSubmit) els.printOptionsSubmit.disabled = noResults;
  renderPrintDocumentPreview(preview);
  applyPrintPreviewZoom();
}

/** Render the required red-zero state without a backend request. */
function renderEmptyPrintSelectionPreview() {
  renderPrintSelectionPreview({
    generatedAt: new Date().toISOString(),
    totalPieces: 0,
    rowCount: 0,
    orderCount: 0,
    customerCount: 0,
    pageCount: 1,
    previewRows: [],
    noResults: true,
  });
}

/** Refresh the preview from the exact loaded rows used by the client print document. */
async function refreshPrintSelectionPreview() {
  const listIds = selectedPrintListIds();
  const selectedRoutes = selectedPrintRouteGroups();
  const allGlass = allPrintGlassTypesSelected();
  const selectedGlass = selectedPrintGlassTypeValues();
  state.printPreviewRequestId += 1;
  if (!listIds.length || !selectedRoutes.length || (!allGlass && !selectedGlass.length)) {
    state.printPreviewResult = null;
    renderEmptyPrintSelectionPreview();
    return;
  }
  renderPrintSelectionPreview(buildLocalPrintSelectionPreview());
  if (els.printPreviewZeroMessage) els.printPreviewZeroMessage.hidden = true;
}

function schedulePrintSelectionPreview(delay = 160) {
  window.clearTimeout(state.printPreviewTimer);
  try {
    const localPreview = buildLocalPrintSelectionPreview();
    renderPrintSelectionPreview(localPreview);
  } catch (_error) {
    state.printPreviewResult = null;
  }
  state.printPreviewTimer = window.setTimeout(() => {
    refreshPrintSelectionPreview().catch((error) => showInlineError(error.message, false));
  }, Math.max(Number(delay || 0), 0));
}

/** Compatibility name retained for existing event wiring. */
function updatePrintSelectionSummary() {
  schedulePrintSelectionPreview();
}

/** Rebuild all choices after a date or route change. */
async function refreshPrintWorkspaceChoices(options = {}) {
  renderPrintQuickDateOptions();
  await renderPrintFilterChoices({ preserveSelections: options.preserveSelections !== false });
}

/** Restore the route-based workspace's default filter state. */
async function resetPrintFilters({ clearActivePreset = true } = {}) {
  const groups = listsByDeliveryDate();
  const requestedDate = state.printContext?.date || selectedDeliveryDate() || dashboardDateKey() || groups[0]?.date || "";
  const requestedRoutes = normalizePrintRouteGroups(state.printContext?.initialRouteGroups || ["airport"]);
  if (els.printSearchInput) els.printSearchInput.value = "";
  state.printSelectedOrders = [];
  state.printSelectedItems = [];
  setPrintRouteGroups(requestedRoutes, { syncControls: false });
  state.printGlassTypes = [];
  state.printGlassFamilies = [];
  state.printGlassRuleTypes = [];
  state.printAllGlass = true;
  if (els.printDateFrom) els.printDateFrom.value = requestedDate;
  if (els.printDateTo) els.printDateTo.value = requestedDate;
  setPrintCopies(1, false);
  setPrintOrientation("portrait", false);
  if (els.printExportType) els.printExportType.value = "pdf";
  if (clearActivePreset) setActivePrintPresetName(PRINT_SYSTEM_DEFAULT_PRESET_NAME);
  renderPrintPresetOptions(clearActivePreset ? PRINT_SYSTEM_DEFAULT_PRESET_NAME : null);
  renderPrintQuickDateOptions(requestedDate);
  state.printPreviewZoom = 0.9;
  updatePrintOutputAction();
  await renderPrintFilterChoices({ preserveSelections: true, captureControlSelections: false });
}

function printPresetUserToken() {
  return String(state.user?.username || state.user?.email || state.user?.id || "local-demo")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9._@-]+/g, "-") || "local-demo";
}

function printPresetStorageKey() {
  return `${PRINT_PRESET_STORAGE_KEY}:${printPresetUserToken()}`;
}

function printActivePresetStorageKey() {
  return `${PRINT_ACTIVE_PRESET_STORAGE_KEY}:${printPresetUserToken()}`;
}

function printDefaultPresetStorageKey() {
  return `${PRINT_DEFAULT_PRESET_STORAGE_KEY}:${printPresetUserToken()}`;
}

/** Protect the built-in Default preset and its legacy display name. */
function isReservedPrintPresetName(name) {
  const clean = String(name || "").trim().toLowerCase();
  return clean === PRINT_SYSTEM_DEFAULT_PRESET_NAME.toLowerCase()
    || clean === PRINT_LEGACY_SYSTEM_DEFAULT_PRESET_NAME.toLowerCase();
}

function readPrintPresets() {
  try {
    const userKey = printPresetStorageKey();
    let raw = localStorage.getItem(userKey);
    if (!raw) {
      raw = localStorage.getItem(PRINT_PRESET_LEGACY_STORAGE_KEY);
      if (raw) localStorage.setItem(userKey, raw);
    }
    const parsed = JSON.parse(raw || "{}");
    if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return {};
    // Preserve an older user-created preset that happened to use the newly
    // reserved display name instead of silently discarding its settings.
    if (parsed[PRINT_SYSTEM_DEFAULT_PRESET_NAME]) {
      const migratedName = parsed["Default (Saved)"] ? "Default (Saved 2)" : "Default (Saved)";
      parsed[migratedName] = parsed[PRINT_SYSTEM_DEFAULT_PRESET_NAME];
    }
    delete parsed[PRINT_SYSTEM_DEFAULT_PRESET_NAME];
    delete parsed[PRINT_LEGACY_SYSTEM_DEFAULT_PRESET_NAME];
    return parsed;
  } catch (_error) {
    return {};
  }
}

function writePrintPresets(presets) {
  const userPresets = { ...(presets || {}) };
  delete userPresets[PRINT_SYSTEM_DEFAULT_PRESET_NAME];
  delete userPresets[PRINT_LEGACY_SYSTEM_DEFAULT_PRESET_NAME];
  localStorage.setItem(printPresetStorageKey(), JSON.stringify(userPresets));
}

/** Return the immutable system preset together with the signed-in user's presets. */
function availablePrintPresets() {
  return {
    ...readPrintPresets(),
    [PRINT_SYSTEM_DEFAULT_PRESET_NAME]: { ...PRINT_SYSTEM_DEFAULT_PRESET },
  };
}

function activePrintPresetName() {
  const savedName = String(localStorage.getItem(printActivePresetStorageKey()) || "");
  if (savedName === PRINT_LEGACY_SYSTEM_DEFAULT_PRESET_NAME) return PRINT_SYSTEM_DEFAULT_PRESET_NAME;
  return savedName && availablePrintPresets()[savedName]
    ? savedName
    : PRINT_SYSTEM_DEFAULT_PRESET_NAME;
}

function activePrintPreset() {
  return availablePrintPresets()[activePrintPresetName()] || { ...PRINT_SYSTEM_DEFAULT_PRESET };
}

function setActivePrintPresetName(name) {
  const clean = String(name || "");
  if (!clean || isReservedPrintPresetName(clean)) {
    localStorage.removeItem(printActivePresetStorageKey());
    return;
  }
  if (readPrintPresets()[clean]) localStorage.setItem(printActivePresetStorageKey(), clean);
  else localStorage.removeItem(printActivePresetStorageKey());
}

/** Return the user's explicit default without inheriting older active-selection state. */
function defaultPrintPresetName() {
  const savedName = String(localStorage.getItem(printDefaultPresetStorageKey()) || "");
  if (savedName === PRINT_LEGACY_SYSTEM_DEFAULT_PRESET_NAME) return PRINT_SYSTEM_DEFAULT_PRESET_NAME;
  return savedName && readPrintPresets()[savedName] ? savedName : PRINT_SYSTEM_DEFAULT_PRESET_NAME;
}

function setDefaultPrintPresetName(name) {
  const clean = String(name || "");
  if (!clean || isReservedPrintPresetName(clean)) {
    localStorage.removeItem(printDefaultPresetStorageKey());
    return;
  }
  if (readPrintPresets()[clean]) localStorage.setItem(printDefaultPresetStorageKey(), clean);
  else localStorage.removeItem(printDefaultPresetStorageKey());
}

/** Refresh the preset selector with the system default first, followed by user presets. */
function renderPrintPresetOptions(selectedName = null) {
  if (!els.printPresetSelect) return;
  const userPresets = readPrintPresets();
  const requested = selectedName === null ? activePrintPresetName() : String(selectedName || PRINT_SYSTEM_DEFAULT_PRESET_NAME);
  const userOptions = Object.keys(userPresets)
    .filter((name) => name !== PRINT_SYSTEM_DEFAULT_PRESET_NAME)
    .sort((a, b) => a.localeCompare(b))
    .map((name) => `<option value="${escapeHtml(name)}" data-custom-delete-action="print-preset">${escapeHtml(name)}</option>`)
    .join("");
  els.printPresetSelect.innerHTML = `<option value="${escapeHtml(PRINT_SYSTEM_DEFAULT_PRESET_NAME)}">Default</option>${userOptions}`;
  els.printPresetSelect.value = availablePrintPresets()[requested] ? requested : PRINT_SYSTEM_DEFAULT_PRESET_NAME;
  syncCustomSelect(els.printPresetSelect);
}

/** Capture the maintained filter state for a local preset. */
function currentPrintPreset() {
  const allGlass = allPrintGlassTypesSelected();
  const hasFamilyRule = Boolean((state.printGlassFamilies || []).length);
  const ruleTypes = (state.printGlassRuleTypes || []).length
    ? [...state.printGlassRuleTypes]
    : hasFamilyRule
      ? []
      : selectedPrintGlassTypeValues();
  return {
    routeGroups: selectedPrintRouteGroups(),
    statuses: selectedPrintStatusValues(),
    attention: selectedPrintAttentionValues(),
    glassTypes: allGlass ? [] : [...new Set(ruleTypes)],
    glassFamilies: allGlass ? [] : [...new Set(state.printGlassFamilies || [])],
    outputType: String(els.printExportType?.value || "pdf"),
    copies: Math.max(Number(els.printCopies?.value || 1), 1),
    orientation: String(els.printOrientation?.value || "portrait"),
  };
}

/** Retain semantic choice hooks for the restrained v0.234 route and glass accents. */
function printPresetChoiceVisualClass(name, value, label = value) {
  const cleanName = String(name || "").trim().toLowerCase();
  const cleanValue = String(value || "").trim().toLowerCase().replaceAll("_", "-");
  if (cleanName === "routes") return `is-route-${cleanValue}`;
  if (cleanName === "statuses") return `is-status-${cleanValue}`;
  if (cleanName === "attention") return `is-attention-${cleanValue}`;
  if (cleanName === "glass") return `is-glass-${printGlassCategoryForLabel(label)}`;
  return "";
}

const PRINT_PRESET_GLASS_CATEGORY_DEFINITIONS = Object.freeze([
  Object.freeze({ value: "annealed", label: "Annealed" }),
  Object.freeze({ value: "tempered", label: "Tempered" }),
  Object.freeze({ value: "mirror", label: "Mirror" }),
]);

/** Group exact products and durable glass-family sets in Create Preset. */
function printPresetGlassChoiceMarkup(options, selectedValues, selectedFamilies = []) {
  const selected = new Set(selectedValues || []);
  const families = new Set((selectedFamilies || []).map((value) => String(value || "").trim().toLowerCase()));
  const grouped = new Map(PRINT_PRESET_GLASS_CATEGORY_DEFINITIONS.map(({ value }) => [value, []]));
  for (const option of options || []) {
    const category = printGlassCategoryForLabel(option.label || option.value);
    grouped.get(category).push(option);
  }
  return PRINT_PRESET_GLASS_CATEGORY_DEFINITIONS.map(({ value, label }) => {
    const entries = (grouped.get(value) || [])
      .sort((a, b) => String(a.label || a.value).localeCompare(String(b.label || b.value)));
    const familySelected = families.has(value);
    const choices = entries.length
      ? entries.map(({ value: optionValue, label: optionLabel }) => `
        <label class="print-preset-choice-v227 ${escapeHtml(printPresetChoiceVisualClass("glass", optionValue, optionLabel))}" data-preset-search="${escapeHtml(`${optionValue} ${optionLabel}`.toLowerCase())}">
          <input type="checkbox" data-preset-value="glass" value="${escapeHtml(optionValue)}" ${selected.has(optionValue) && !familySelected ? "checked" : ""} ${familySelected ? "disabled" : ""}>
          <span>${escapeHtml(optionLabel)}</span>
          <i class="print-preset-glass-check-v241" aria-hidden="true">✓</i>
        </label>`).join("")
      : `<div class="print-preset-glass-family-empty-v237">No known ${escapeHtml(label.toLowerCase())} products yet.</div>`;
    return `<section class="print-preset-glass-category-v232 is-${escapeHtml(value)}" data-preset-glass-category="${escapeHtml(value)}">
      <header>
        <label class="print-preset-glass-family-v237">
          <input type="checkbox" data-preset-glass-family="${escapeHtml(value)}" ${familySelected ? "checked" : ""}>
          <span>${escapeHtml(label)} set</span>
        </label>
        <span>${entries.length} ${entries.length === 1 ? "type" : "types"}</span>
      </header>
      <div class="print-preset-glass-category-options-v232">${choices}</div>
    </section>`;
  }).join("");
}

function printPresetBuilderGroup(title, name, options, selectedValues, allLabel = "", selectedFamilies = []) {
  const selected = new Set(selectedValues || []);
  const selectedFamilyCount = name === "glass" ? (selectedFamilies || []).length : 0;
  const allSelected = selected.size === 0 && selectedFamilyCount === 0;
  const selectionSummary = allSelected && allLabel
    ? allLabel
    : [selectedFamilyCount ? `${selectedFamilyCount} ${selectedFamilyCount === 1 ? "set" : "sets"}` : "", selected.size ? `${selected.size} ${selected.size === 1 ? "type" : "types"}` : ""]
      .filter(Boolean)
      .join(" + ") || "None selected";
  const allChoiceClass = name === "statuses" ? "is-status-all" : name === "attention" ? "is-attention-all" : name === "glass" ? "is-glass-all" : "";
  const allChoice = allLabel
    ? `<label class="print-preset-choice-v227 is-all ${allChoiceClass}"><input type="checkbox" data-preset-all="${escapeHtml(name)}" ${allSelected ? "checked" : ""}><span>${escapeHtml(allLabel)}</span></label>`
    : "";
  const glassSearch = name === "glass"
    ? `<label class="print-preset-glass-search-v227"><span class="visually-hidden">Search preset glass types</span><input type="search" data-preset-glass-search autocomplete="off" placeholder="Search glass types"></label>`
    : "";
  const choices = name === "glass"
    ? printPresetGlassChoiceMarkup(options, selectedValues, selectedFamilies)
    : options.map(({ value, label }) => `<label class="print-preset-choice-v227 ${escapeHtml(printPresetChoiceVisualClass(name, value, label))}"><input type="checkbox" data-preset-value="${escapeHtml(name)}" value="${escapeHtml(value)}" ${selected.has(value) ? "checked" : ""}><span>${escapeHtml(label)}</span></label>`).join("");
  return `
    <section class="print-preset-filter-row-v227 is-${escapeHtml(name)}" data-preset-group="${escapeHtml(name)}">
      <header><strong>${escapeHtml(title)}</strong></header>
      <div class="print-preset-filter-control-v227">
        ${glassSearch}
        <div class="print-preset-choice-grid-v227 ${name === "glass" ? "is-grouped-glass-v232" : ""}">
          ${allChoice}
          ${choices}
          ${name === "glass" ? '<div class="print-preset-glass-empty-v206" data-preset-glass-empty hidden>No glass types match this search.</div>' : ""}
        </div>
      </div>
      <b data-preset-group-summary>${escapeHtml(selectionSummary)}</b>
    </section>`;
}

/** Adopt the shared Lookup Manager payload through one normalized assignment path. */
function adoptManualEditLookups(payload = {}) {
  state.manualEditLookups = {
    products: Array.isArray(payload.products) ? payload.products : [],
    routes: Array.isArray(payload.routes) ? payload.routes : [],
    processes: Array.isArray(payload.processes) ? payload.processes : [],
    glassCosts: Array.isArray(payload.glassCosts) ? payload.glassCosts : [],
  };
  state.manualEditLookupsLoaded = true;
  return state.manualEditLookups;
}

/** Load only the small Lookup Manager library needed by Create Preset. */
async function ensurePrintProductLookupLibrary() {
  const currentProducts = Array.isArray(state.manualEditLookups?.products) ? state.manualEditLookups.products : [];
  if (state.manualEditLookupsLoaded || currentProducts.length || !state.backend) return currentProducts;
  if (!state.manualEditLookupsPromise) {
    state.manualEditLookupsPromise = fetchJson("/api/admin/manual-edit-lookups")
      .then((payload) => adoptManualEditLookups(payload).products)
      .finally(() => { state.manualEditLookupsPromise = null; });
  }
  return state.manualEditLookupsPromise;
}

/** Collect every known product value and prefer Lookup Manager display names. */
function collectKnownPrintGlassTypes() {
  const options = new Map();
  const addOption = (value, label = value, preferLabel = false) => {
    const cleanValue = String(value || "").trim();
    const cleanLabel = String(label || cleanValue).trim() || cleanValue;
    if (!cleanValue) return;
    const current = options.get(cleanValue);
    if (!current || preferLabel || current.label === current.value) {
      options.set(cleanValue, { value: cleanValue, label: cleanLabel });
    }
  };

  // Keep current and already-loaded delivery-list values available even when a
  // product has not yet been added to the maintained Lookup Manager library.
  selectedPrintGlassInputs().forEach((input) => addOption(input.value));
  for (const list of state.lists) {
    for (const item of Array.isArray(list.items) ? list.items : []) addOption(glassTypeLabel(item));
  }
  for (const preset of Object.values(readPrintPresets())) {
    for (const value of preset?.glassTypes || []) addOption(value);
  }
  for (const value of currentPrintPreset().glassTypes || []) addOption(value);

  // The Lookup Manager product-name library is authoritative for the complete
  // known list and for the polished label shown beside each exact stored value.
  for (const product of state.manualEditLookups?.products || []) {
    addOption(product?.value, product?.label || product?.value, true);
  }

  state.printKnownGlassTypes = [...options.values()]
    .sort((a, b) => a.label.localeCompare(b.label) || a.value.localeCompare(b.value));
  return state.printKnownGlassTypes;
}

/** Build an editable preset using the filters currently available in the workspace. */
function renderPrintPresetSaveSummary(knownGlassOptions = state.printKnownGlassTypes, preset = currentPrintPreset()) {
  if (!els.printPresetSummary || !els.printPresetOutputSettings) return;
  const routeOptions = PRINT_ROUTE_GROUPS.map(({ value, label }) => ({ value, label }));
  const statusOptions = [
    { value: "not-scanned", label: "Not Scanned" },
    { value: "partial", label: "Partial" },
    { value: "complete", label: "Complete" },
  ];
  const attentionOptions = [
    { value: "remake", label: "Remakes" },
    { value: "rush", label: "Rushes" },
    { value: "reject", label: "Internal Rejects" },
    { value: "updated", label: "New/Updated" },
    { value: "error", label: "Errors" },
  ];
  const knownGlass = new Map((knownGlassOptions || []).map((option) => [String(option.value || ""), option]));
  for (const value of preset.glassTypes || []) {
    if (!knownGlass.has(value)) knownGlass.set(value, { value, label: value, count: 0 });
  }
  const glassOptions = [...knownGlass.values()].sort((a, b) => String(a.label || a.value).localeCompare(String(b.label || b.value)));
  els.printPresetSummary.innerHTML = `
    ${printPresetBuilderGroup("Status", "statuses", statusOptions, preset.statuses, "All Status")}
    ${printPresetBuilderGroup("Attention", "attention", attentionOptions, preset.attention, "All Attention")}
    ${printPresetBuilderGroup("Routes", "routes", routeOptions, preset.routeGroups)}
    ${printPresetBuilderGroup("Glass Types", "glass", glassOptions, preset.glassTypes, "All Glass", preset.glassFamilies)}`;
  els.printPresetOutputSettings.innerHTML = `
    <label class="print-preset-option-field-v227"><span>Copies</span><div class="print-preset-copy-stepper-v227"><button type="button" data-preset-copy-change="-1" aria-label="Decrease copies">−</button><input data-preset-copies type="text" inputmode="numeric" pattern="[0-9]*" maxlength="2" aria-label="Number of copies" value="${Math.max(1, Math.min(Number(preset.copies || 1), 10))}"><button type="button" data-preset-copy-change="1" aria-label="Increase copies">+</button></div></label>
    <div class="print-preset-option-field-v227 print-preset-orientation-v227"><span>Orientation</span><input data-preset-orientation type="hidden" value="${preset.orientation === "landscape" ? "landscape" : "portrait"}"><div><button type="button" class="${preset.orientation === "landscape" ? "" : "is-active"}" data-preset-orientation-choice="portrait">Portrait</button><button type="button" class="${preset.orientation === "landscape" ? "is-active" : ""}" data-preset-orientation-choice="landscape">Landscape</button></div></div>
    <label class="print-preset-option-field-v227"><span>File Format</span><select data-preset-output-type><option value="pdf" ${preset.outputType === "pdf" ? "selected" : ""}>PDF</option><option value="xlsx" ${preset.outputType === "xlsx" ? "selected" : ""}>Excel Workbook (.xlsx)</option><option value="csv" ${preset.outputType === "csv" ? "selected" : ""}>Comma-Separated Values (.csv)</option></select></label>`;
  enhanceCustomSelects(els.printPresetOutputSettings);
}

function printPresetFromBuilder() {
  const values = (name) => [...(els.printPresetSummary?.querySelectorAll(`input[data-preset-value="${name}"]:checked`) || [])].map((input) => input.value);
  const allChecked = (name) => Boolean(els.printPresetSummary?.querySelector(`input[data-preset-all="${name}"]`)?.checked);
  const glassFamilies = [...(els.printPresetSummary?.querySelectorAll('input[data-preset-glass-family]:checked') || [])]
    .map((input) => String(input.dataset.presetGlassFamily || ""))
    .filter(Boolean);
  const allGlass = allChecked("glass");
  return {
    routeGroups: values("routes").length ? values("routes") : ["airport"],
    statuses: allChecked("statuses") ? [] : values("statuses"),
    attention: allChecked("attention") ? [] : values("attention"),
    glassTypes: allGlass ? [] : values("glass"),
    glassFamilies: allGlass ? [] : glassFamilies,
    outputType: String(els.printPresetOutputSettings?.querySelector("[data-preset-output-type]")?.value || "pdf"),
    copies: Math.max(Number(els.printPresetOutputSettings?.querySelector("[data-preset-copies]")?.value || 1), 1),
    orientation: String(els.printPresetOutputSettings?.querySelector("[data-preset-orientation]")?.value || "portrait"),
  };
}

function savePrintPreset() {
  if (els.printPresetNameInput) els.printPresetNameInput.value = "";
  if (els.printPresetDefaultToggle) els.printPresetDefaultToggle.checked = false;
  if (els.printPresetConfirmBtn) {
    els.printPresetConfirmBtn.disabled = false;
    els.printPresetConfirmBtn.textContent = "Save & Apply";
  }
  if (els.printPresetSaveOnlyBtn) {
    els.printPresetSaveOnlyBtn.disabled = false;
    els.printPresetSaveOnlyBtn.textContent = "Save Preset";
  }

  // Open immediately from memory. If the small product lookup has not been
  // prefetched yet, enrich only the glass section as soon as that request completes.
  const lookupReady = state.manualEditLookupsLoaded || Boolean(state.manualEditLookups?.products?.length) || !state.backend;
  renderPrintPresetSaveSummary(collectKnownPrintGlassTypes());
  if (els.printPresetStatus) {
    els.printPresetStatus.textContent = lookupReady ? "" : "Loading glass types…";
  }
  if (els.printPresetModalBackdrop) els.printPresetModalBackdrop.hidden = false;
  if (els.printPresetModal) {
    els.printPresetModal.hidden = false;
    const workspace = els.printPresetModal.querySelector(".print-preset-workspace-v227");
    if (workspace) workspace.scrollTop = 0;
  }
  updateModalScrollLock();
  window.setTimeout(() => els.printPresetNameInput?.focus({ preventScroll: true }), 0);

  if (!lookupReady) {
    ensurePrintProductLookupLibrary()
      .then(() => {
        if (els.printPresetModal?.hidden) return;
        const pendingPreset = printPresetFromBuilder();
        renderPrintPresetSaveSummary(collectKnownPrintGlassTypes(), pendingPreset);
        if (els.printPresetStatus) els.printPresetStatus.textContent = "";
      })
      .catch((error) => {
        if (els.printPresetStatus && !els.printPresetModal?.hidden) {
          els.printPresetStatus.textContent = `Glass types could not be refreshed. ${error.message}`;
        }
      });
  }
}

/** Close the dedicated preset builder. */
function closePrintPresetModal() {
  if (els.printPresetModalBackdrop) els.printPresetModalBackdrop.hidden = true;
  if (els.printPresetModal) els.printPresetModal.hidden = true;
  updateModalScrollLock();
}

/** Update overwrite guidance while the preset name is entered. */
function updatePrintPresetNameStatus() {
  const name = String(els.printPresetNameInput?.value || "").trim();
  const reserved = isReservedPrintPresetName(name);
  const exists = Boolean(name && readPrintPresets()[name]);
  if (els.printPresetStatus) {
    els.printPresetStatus.textContent = reserved
      ? "Default is reserved and cannot be replaced. Choose a different name."
      : exists
        ? "A preset with this name already exists and will be replaced."
        : "";
  }
  if (els.printPresetConfirmBtn) {
    els.printPresetConfirmBtn.disabled = reserved;
    els.printPresetConfirmBtn.textContent = exists ? "Replace & Apply" : "Save & Apply";
  }
  if (els.printPresetSaveOnlyBtn) {
    els.printPresetSaveOnlyBtn.disabled = reserved;
    els.printPresetSaveOnlyBtn.textContent = exists ? "Replace Preset" : "Save Preset";
  }
}

/** Refresh one preset section's selection summary after a choice changes. */
function updatePrintPresetBuilderGroupSummary(groupName) {
  const section = els.printPresetSummary?.querySelector(`[data-preset-group="${groupName}"]`);
  const summary = section?.querySelector("[data-preset-group-summary]");
  if (!section || !summary) return;
  const allInput = section.querySelector(`input[data-preset-all="${groupName}"]`);
  const selectedCount = section.querySelectorAll(`input[data-preset-value="${groupName}"]:checked`).length;
  const familyCount = groupName === "glass"
    ? section.querySelectorAll('input[data-preset-glass-family]:checked').length
    : 0;
  const allLabel = allInput?.closest("label")?.querySelector("span")?.textContent?.trim() || "All";
  const parts = [];
  if (familyCount) parts.push(`${familyCount} ${familyCount === 1 ? "set" : "sets"}`);
  if (selectedCount) parts.push(`${selectedCount} ${selectedCount === 1 ? "type" : "types"}`);
  summary.textContent = allInput?.checked ? allLabel : (parts.join(" + ") || "None selected");
}

/** Keep All selections exclusive inside the preset builder. */
function handlePrintPresetBuilderChange(event) {
  const changed = event.target.closest("input");
  if (!changed || !els.printPresetSummary?.contains(changed)) return;
  const allName = changed.dataset.presetAll;
  const valueName = changed.dataset.presetValue;
  const familyName = changed.dataset.presetGlassFamily;
  const groupName = allName || valueName || (familyName ? "glass" : "");
  if (!groupName) return;
  const allInput = els.printPresetSummary.querySelector(`input[data-preset-all="${groupName}"]`);
  const detailInputs = [...els.printPresetSummary.querySelectorAll(`input[data-preset-value="${groupName}"]`)];

  if (groupName === "routes") {
    const airport = detailInputs.find((input) => input.value === "airport");
    const routeDetails = detailInputs.filter((input) => input !== airport);
    if (changed === airport) {
      if (airport.checked) routeDetails.forEach((input) => { input.checked = false; });
      else if (!routeDetails.some((input) => input.checked)) airport.checked = true;
    } else {
      if (changed.checked && airport) airport.checked = false;
      if (routeDetails.length && routeDetails.every((input) => input.checked)) {
        if (airport) airport.checked = true;
        routeDetails.forEach((input) => { input.checked = false; });
      } else if (!detailInputs.some((input) => input.checked) && airport) {
        airport.checked = true;
      }
    }
    updatePrintPresetBuilderGroupSummary(groupName);
    return;
  }

  if (groupName === "glass") {
    const familyInputs = [...els.printPresetSummary.querySelectorAll('input[data-preset-glass-family]')];
    const syncFamilyDetails = () => {
      for (const familyInput of familyInputs) {
        const category = familyInput.closest('[data-preset-glass-category]');
        category?.querySelectorAll('input[data-preset-value="glass"]').forEach((input) => {
          if (familyInput.checked) input.checked = false;
          input.disabled = familyInput.checked;
        });
      }
    };

    if (changed === allInput) {
      if (allInput.checked) {
        familyInputs.forEach((input) => { input.checked = false; });
        detailInputs.forEach((input) => { input.checked = false; input.disabled = false; });
      } else if (!familyInputs.some((input) => input.checked) && !detailInputs.some((input) => input.checked)) {
        allInput.checked = true;
      }
    } else {
      if (changed.checked && allInput) allInput.checked = false;
      syncFamilyDetails();
      const categorySections = [...els.printPresetSummary.querySelectorAll('[data-preset-glass-category]')];
      const everyCategoryCovered = categorySections.length > 0 && categorySections.every((category) => {
        const familyInput = category.querySelector('input[data-preset-glass-family]');
        const categoryDetails = [...category.querySelectorAll('input[data-preset-value="glass"]')];
        return Boolean(familyInput?.checked) || (categoryDetails.length > 0 && categoryDetails.every((input) => input.checked));
      });
      if (everyCategoryCovered) {
        if (allInput) allInput.checked = true;
        familyInputs.forEach((input) => { input.checked = false; });
        detailInputs.forEach((input) => { input.checked = false; input.disabled = false; });
      } else if (allInput && !familyInputs.some((input) => input.checked) && !detailInputs.some((input) => input.checked)) {
        allInput.checked = true;
      }
    }
    syncFamilyDetails();
    updatePrintPresetBuilderGroupSummary(groupName);
    return;
  }

  if (changed === allInput) {
    if (allInput.checked) detailInputs.forEach((input) => { input.checked = false; });
    else if (!detailInputs.some((input) => input.checked)) allInput.checked = true;
  } else {
    if (changed.checked && allInput) allInput.checked = false;
    if (detailInputs.length && detailInputs.every((input) => input.checked)) {
      if (allInput) allInput.checked = true;
      detailInputs.forEach((input) => { input.checked = false; });
    } else if (allInput && !detailInputs.some((input) => input.checked)) {
      allInput.checked = true;
    }
  }
  updatePrintPresetBuilderGroupSummary(groupName);
}

/** Save the preset, optionally applying it immediately. */
async function confirmPrintPresetSave({ apply = true } = {}) {
  const cleanName = String(els.printPresetNameInput?.value || "").trim().slice(0, 50);
  if (!cleanName) {
    if (els.printPresetStatus) els.printPresetStatus.textContent = "Enter a preset name before saving the preset.";
    els.printPresetNameInput?.focus();
    return;
  }
  if (isReservedPrintPresetName(cleanName)) {
    if (els.printPresetStatus) els.printPresetStatus.textContent = "Default is reserved and cannot be replaced. Choose a different name.";
    els.printPresetNameInput?.focus();
    return;
  }
  const presets = readPrintPresets();
  presets[cleanName] = printPresetFromBuilder();
  writePrintPresets(presets);
  const setAsDefault = Boolean(els.printPresetDefaultToggle?.checked);
  if (setAsDefault) setDefaultPrintPresetName(cleanName);
  renderPrintPresetOptions(cleanName);
  closePrintPresetModal();
  if (apply) {
    await applyPrintPreset(cleanName, { persist: setAsDefault });
    showFloatingNotice(`Saved and applied print preset: ${cleanName}`, "success");
  } else {
    showFloatingNotice(`Saved print preset: ${cleanName}`, "success");
  }
}
/** Delete one user preset through the shared confirmation and success dialogs. */
async function deletePrintPreset(name) {
  const cleanName = String(name || "").trim();
  if (!cleanName || isReservedPrintPresetName(cleanName)) return;
  const presets = readPrintPresets();
  if (!presets[cleanName]) return;

  const confirmed = await confirmWebAppAction({
    title: "Delete print preset?",
    message: `Delete <strong>${escapeHtml(cleanName)}</strong>?`,
    details: "This removes the saved preset from this browser profile. The built-in Default preset remains available.",
    confirmLabel: "Delete Preset",
    cancelLabel: "Keep Preset",
    danger: true,
  });
  if (!confirmed) return;

  const wasActive = activePrintPresetName() === cleanName;
  const wasDefault = defaultPrintPresetName() === cleanName;
  delete presets[cleanName];
  writePrintPresets(presets);
  if (wasDefault) setDefaultPrintPresetName(PRINT_SYSTEM_DEFAULT_PRESET_NAME);

  if (wasActive) {
    setActivePrintPresetName(PRINT_SYSTEM_DEFAULT_PRESET_NAME);
    await applyPrintPreset(PRINT_SYSTEM_DEFAULT_PRESET_NAME);
  } else {
    renderPrintPresetOptions(activePrintPresetName());
  }

  playAppSound("save");
  showActionFeedback({
    kind: "success",
    eyebrow: "Preset updated",
    title: "Preset deleted",
    message: `${cleanName} was removed successfully.`,
    details: [
      ...(wasActive ? [{ label: "Active preset", value: "Default was applied" }] : []),
      ...(wasDefault ? [{ label: "Personal default", value: "Reset to Default" }] : []),
    ],
    secondaryLabel: "Done",
  });
}

/** Apply one saved preset after rebuilding the date-dependent choices. */
async function applyPrintPreset(name, { persist = true } = {}) {
  const preset = availablePrintPresets()[name];
  if (!preset) return;
  if (persist) setActivePrintPresetName(name);
  if (els.printSearchInput) els.printSearchInput.value = "";
  state.printSelectedOrders = [];
  state.printSelectedItems = [];
  // Apply route and semantic Glass Type rules before any date-dependent choices
  // render. Family sets expand against the current date, then automatically
  // expand again after every later date or route change.
  setPrintRouteGroups(preset.routeGroups?.length ? preset.routeGroups : ["airport"], { syncControls: false });
  state.printGlassFamilies = [...new Set((preset.glassFamilies || []).map((value) => String(value || "").trim().toLowerCase()).filter(Boolean))];
  state.printGlassRuleTypes = [...new Set((preset.glassTypes || []).map((value) => String(value || "").trim()).filter(Boolean))];
  state.printAllGlass = !state.printGlassFamilies.length && !state.printGlassRuleTypes.length;
  state.printGlassTypes = [];
  await renderPrintFilterChoices({ preserveSelections: true, captureControlSelections: false });
  const applyAllAwareValues = (container, allSelector, detailSelector, values) => {
    const wanted = new Set(values || []);
    const allInput = container?.querySelector(allSelector);
    const details = [...(container?.querySelectorAll(detailSelector) || [])];
    const allSelected = wanted.size === 0;
    if (allInput) allInput.checked = allSelected;
    details.forEach((input) => { input.checked = !allSelected && wanted.has(input.value); });
  };
  applyAllAwareValues(els.printStatusOptions, 'input[data-print-status-all]', 'input[data-print-status]:not([data-print-status-all])', preset.statuses);
  applyAllAwareValues(els.printAttentionOptions, 'input[data-print-attention-all]', 'input[data-print-attention]:not([data-print-attention-all])', preset.attention);
  if (els.printExportType) els.printExportType.value = ["pdf", "xlsx", "csv"].includes(String(preset.outputType || "")) ? String(preset.outputType) : "pdf";
  setPrintCopies(preset.copies || 1, false);
  setPrintOrientation(preset.orientation || "portrait", false);
  renderPrintSelectedOrders();
  renderPrintSearchSuggestions();
  updatePrintOutputAction();
  renderPrintPresetOptions(name);
  schedulePrintSelectionPreview(0);
}

function openPrintOptions(context = {}) {
  const openId = ++state.printWorkspaceOpenId;
  const requestedRoutes = normalizePrintRouteGroups(context.initialRouteGroups || ["airport"]);
  state.printContext = { ...context, initialRouteGroups: requestedRoutes };
  state.printPreviewResult = null;
  state.printPreviewRequestId += 1;
  state.printWorkspaceReady = false;
  state.printDateHistoryWeeks = PRINT_DATE_HISTORY_BATCH_WEEKS;
  window.clearTimeout(state.printPreviewTimer);
  if (!listsByDeliveryDate().length) {
    showInlineError("No delivery lists are available to print.", false);
    return;
  }

  // Commit the requested management-route filter before exposing the panel.
  // Header actions use Airport Road (all routes); route-row actions open with
  // their exact Indian Trail, Greenville, CPU, or DTC filter already selected.
  setPrintRouteGroups(requestedRoutes, { syncControls: false });
  state.printGlassTypes = [];
  state.printGlassFamilies = [];
  state.printGlassRuleTypes = [];
  state.printAllGlass = true;
  setPrintFilterLoadingState();
  renderEmptyPrintSelectionPreview();

  if (els.printOptionsBackdrop) els.printOptionsBackdrop.hidden = false;
  if (els.printOptionsPanel) els.printOptionsPanel.hidden = false;
  updateModalScrollLock();

  const initialPreset = defaultPrintPresetName();
  renderPrintPresetOptions(initialPreset);
  ensurePrintProductLookupLibrary().catch(() => {});

  // One initialization transaction replaces the old reset-then-reapply cycle.
  // Keeping its promise lets an immediate Print click wait for current list rows
  // instead of using stale or not-yet-loaded data from a previous GUI session.
  const initialization = resetPrintFilters({ clearActivePreset: false })
    .then(async () => {
      if (openId !== state.printWorkspaceOpenId || els.printOptionsPanel?.hidden) return;
      if (!context.initialRouteGroups && initialPreset !== PRINT_SYSTEM_DEFAULT_PRESET_NAME && availablePrintPresets()[initialPreset]) {
        await applyPrintPreset(initialPreset, { persist: false });
      } else {
        setPrintRouteGroups(requestedRoutes);
        schedulePrintSelectionPreview(0);
      }
      state.printWorkspaceReady = true;
    })
    .catch((error) => {
      if (openId === state.printWorkspaceOpenId) showInlineError(error.message, false);
    })
    .finally(() => {
      if (state.printWorkspacePromise === initialization) state.printWorkspacePromise = null;
    });
  state.printWorkspacePromise = initialization;
}

/** Close the Print / Export control center. */
function closePrintOptions() {
  state.printWorkspaceOpenId += 1;
  state.printWorkspaceReady = false;
  closePrintPresetModal();
  closePrintDateCalendar();
  hidePrintSearchSuggestions();
  if (els.printOptionsBackdrop) els.printOptionsBackdrop.hidden = true;
  if (els.printOptionsPanel) els.printOptionsPanel.hidden = true;
  updateModalScrollLock();
}

// A background catalog refresh can invalidate changed lists while the modal is open.
// Recover only when selected detail is actually missing; unchanged catalog heartbeats do no work.
document.addEventListener("dls:delivery-list-catalog-synced", () => {
  if (printWorkspaceNeedsDetailReload()) void restorePrintWorkspaceAfterInactivity();
});

/** Clamp and render the copies increment box. */
function setPrintCopies(value, refresh = true) {
  const copies = Math.max(1, Math.min(Number(value || 1), 10));
  if (els.printCopies) els.printCopies.value = String(copies);
  if (refresh) schedulePrintSelectionPreview(0);
  return copies;
}

/** Keep the two orientation buttons exclusive and synchronize the hidden value. */
function setPrintOrientation(value, refresh = true) {
  const orientation = String(value || "portrait") === "landscape" ? "landscape" : "portrait";
  const previousOrientation = String(els.printOrientation?.value || "portrait") === "landscape" ? "landscape" : "portrait";
  if (els.printOrientation) els.printOrientation.value = orientation;
  // Reassert the committed route whenever output geometry changes. Landscape
  // switching must never read or replace route state from visual checkbox markup.
  setPrintRouteGroups(selectedPrintRouteGroups());
  document.querySelectorAll('[data-print-orientation]').forEach((button) => {
    const selected = button.dataset.printOrientation === orientation;
    button.classList.toggle("is-active", selected);
    button.setAttribute("aria-pressed", selected ? "true" : "false");
  });
  if (orientation === "landscape" && previousOrientation !== "landscape") {
    state.printPreviewZoom = printPreviewFitZoom("landscape");
  } else if (orientation === "portrait" && previousOrientation === "landscape") {
    state.printPreviewZoom = 0.9;
  }
  applyPrintPreviewZoom();
  if (refresh) schedulePrintSelectionPreview(0);
  return orientation;
}

/** Return the global and Print-specific stylesheets used by popup printing. */
function localPrintPackageStylesheetUrls() {
  return [
    new URL("static/css/styles.css?v=20260811-v0.303", window.location.href).href,
    new URL("static/css/print.css?v=20260811-v0.303", window.location.href).href,
  ];
}

/** Return only printer-page overrides; reusable and Print-specific styling comes from linked stylesheets. */
function localPrintPackageStyles(orientation) {
  const landscape = orientation === "landscape";
  const printableHeight = landscape ? "7.7in" : "10.2in";
  const pageSize = landscape ? "letter landscape" : "letter portrait";
  return `
    *{box-sizing:border-box}
    html,body{margin:0;min-height:100%;background:#e5ebf2}
    body{color:#07122f;font-family:"Segoe UI",Arial,sans-serif}
    @page{size:${pageSize};margin:.4in}
    @media print{
      *{-webkit-print-color-adjust:exact;print-color-adjust:exact}
      html,body{background:#fff}
      .delivery-print-sheet-v203{width:100%!important;min-width:100%!important;max-width:100%!important;height:${printableHeight}!important;min-height:${printableHeight}!important;margin:0!important;padding:0!important;border:0!important;border-radius:0!important;overflow:hidden!important;box-shadow:none!important;page-break-after:always;break-after:page}
      .delivery-print-sheet-v203:last-child{page-break-after:auto;break-after:auto}
      .delivery-print-sheet-v203.rush::before{inset:.09in}
      .delivery-print-sheet-v203.remake{padding:.1in!important}
      .delivery-print-sheet-v203.remake::after{inset:.02in}
      .delivery-print-sheet-v203 .sheet-footer{left:0;bottom:0}
      .delivery-print-sheet-v203.remake .sheet-footer{left:.1in;bottom:.04in}
    }`;
}

/** Build and synchronously open the exact local delivery-list print document. */
function launchLocalPrintPackage(preview) {
  const orientation = setPrintOrientation(els.printOrientation?.value || "portrait", false);
  const copies = setPrintCopies(els.printCopies?.value || 1, false);
  const printWindow = window.open("", "deliveryListPdfExportWindow", "popup=yes,width=1180,height=860,resizable=yes,scrollbars=yes");
  if (!printWindow) {
    showInlineError("Allow popups to open the print preview.", false);
    return null;
  }
  const sheets = Array.isArray(preview.previewSheets) ? preview.previewSheets : [];
  const basePages = [];
  for (const sheet of sheets) {
    const chunks = paginatePrintSheetRows(sheet.rows || [], orientation);
    chunks.forEach((chunk, index) => basePages.push(printSheetPageMarkup(sheet, chunk, index + 1, chunks.length, orientation, preview.generatedAt)));
  }
  const pages = Array.from({ length: copies }, () => basePages).flat();
  const stylesheetLinks = localPrintPackageStylesheetUrls()
    .map((stylesheetUrl) => `<link rel="stylesheet" href="${escapeHtml(stylesheetUrl)}">`)
    .join("");
  const html = `<!doctype html><html><head><meta charset="utf-8"><title>Delivery List Print Package</title>${stylesheetLinks}<style>${localPrintPackageStyles(orientation)}</style></head><body>${pages.join("")}<script>
    window.addEventListener("load", async () => {
      const imageLoads = Array.from(document.images).map((image) => image.complete
        ? (image.decode ? image.decode().catch(() => {}) : Promise.resolve())
        : new Promise((resolve) => { image.addEventListener("load", resolve, { once: true }); image.addEventListener("error", resolve, { once: true }); }));
      if (document.fonts && document.fonts.ready) await document.fonts.ready.catch(() => {});
      await Promise.all(imageLoads);
      setTimeout(() => window.print(), 100);
    });
    window.addEventListener("afterprint", () => window.close());
  <\/script></body></html>`;
  state.restoreFullscreenAfterPrint = Boolean(document.fullscreenElement);
  watchManagedPrintWindow(printWindow);
  printWindow.document.open();
  printWindow.document.write(html);
  printWindow.document.close();
  printWindow.focus();
  return printWindow;
}


/* ========================================================================== */
/* v0.243 formatted XLSX and raw CSV exports                                  */
/* ========================================================================== */
/*
 * XLSX intentionally uses a small built-in OOXML writer instead of a remote
 * library. The scanner can therefore export the exact loaded print selection
 * on an offline plant network. ZIP entries use the standard stored method;
 * Excel handles the resulting workbook without a server round trip.
 */
const PRINT_XLSX_CONTENT_TYPE = "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
const PRINT_XLSX_LOGO_PATH = "static/images/barefoot-company-builders-firstsource-print-logo.png?v=20260810-v0.268";

function printExportFileStem(preview = {}) {
  const route = printSheetRouteLabel().replace(/\s*\|\s*/g, "-");
  const dates = [...new Set((preview.previewRows || []).map((row) => String(row.deliveryDate || "").trim()).filter(Boolean))];
  const dateLabel = dates.length === 1 ? dates[0] : dates.length > 1 ? `${dates[0]}-through-${dates[dates.length - 1]}` : "selected-dates";
  return `${route}-${dateLabel}-delivery-list`
    .replace(/[^a-z0-9._-]+/gi, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "") || "delivery-list";
}

function downloadGeneratedFile(blob, fileName) {
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = fileName;
  link.style.display = "none";
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 1500);
}

function csvCell(value) {
  const text = String(value ?? "");
  return /[",\r\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

/** Export one intentionally plain, analysis-friendly row per selected item. */
function exportRawPrintCsv(preview = {}) {
  const headers = [
    "List ID", "Line Item ID", "Order", "Item", "Job", "Customer",
    "Delivery Date", "QTY", "Glass Type", "Dimensions", "Status", "Attention", "Route",
  ];
  const rows = (preview.previewRows || []).map((row) => [
    row.listId,
    row.lineItemId,
    row.order,
    row.item,
    row.job,
    row.customer,
    row.deliveryDate,
    Number(row.pieces || 0),
    row.glassType,
    row.dimensions,
    row.statusLabel,
    (row.attention || []).map((entry) => entry.label || entry.key).filter(Boolean).join(" | "),
    row.route,
  ]);
  const csv = `\uFEFF${[headers, ...rows].map((row) => row.map(csvCell).join(",")).join("\r\n")}`;
  downloadGeneratedFile(new Blob([csv], { type: "text/csv;charset=utf-8" }), `${printExportFileStem(preview)}.csv`);
}

function xlsxXmlEscape(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

function xlsxColumnName(index) {
  let value = Math.max(1, Number(index || 1));
  let name = "";
  while (value) {
    value -= 1;
    name = String.fromCharCode(65 + (value % 26)) + name;
    value = Math.floor(value / 26);
  }
  return name;
}

function xlsxInlineCell(reference, value, style = 0) {
  return `<c r="${reference}" s="${style}" t="inlineStr"><is><t xml:space="preserve">${xlsxXmlEscape(value)}</t></is></c>`;
}

function xlsxNumberCell(reference, value, style = 0) {
  const number = Number(value || 0);
  return `<c r="${reference}" s="${style}"><v>${Number.isFinite(number) ? number : 0}</v></c>`;
}

function xlsxRowXml(rowNumber, cells, { height = null } = {}) {
  const size = height ? ` ht="${height}" customHeight="1"` : "";
  return `<row r="${rowNumber}"${size}>${cells.join("")}</row>`;
}

function xlsxSafeSheetName(value, usedNames) {
  const base = String(value || "Delivery List")
    .replace(/[\\/*?:\[\]]/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 31) || "Delivery List";
  let candidate = base;
  let suffix = 2;
  while (usedNames.has(candidate.toLowerCase())) {
    const tail = ` ${suffix}`;
    candidate = `${base.slice(0, Math.max(1, 31 - tail.length))}${tail}`;
    suffix += 1;
  }
  usedNames.add(candidate.toLowerCase());
  return candidate;
}

function xlsxSheetDocument(sheet, orientation, generatedAt, sheetIndex, sheetName) {
  const rows = Array.isArray(sheet.rows) ? sheet.rows : [];
  const totalOrders = new Set(rows.map((row) => String(row.order || "").trim()).filter(Boolean)).size;
  const totalQty = rows.reduce((sum, row) => sum + Number(row.pieces || 0), 0);
  const badge = sheet.badge ? `  [${sheet.badge}]` : "";
  const title = `${String(sheet.titleLabel || printSheetTitleLabel())}${badge}`;
  const dateLabel = String(sheet.dateLabel || printSheetDateLabel(sheet.deliveryDate || ""));
  const filterSummary = String(sheet.filterSummary || printCurrentFilterSummary());
  const rowXml = [];
  const merges = ["C1:H1", "C2:H2", "C3:H3", "C4:H4", "F5:H5"];

  rowXml.push(xlsxRowXml(1, [xlsxInlineCell("C1", title, 1)], { height: 26 }));
  rowXml.push(xlsxRowXml(2, [xlsxInlineCell("C2", dateLabel, 2)], { height: 20 }));
  rowXml.push(xlsxRowXml(3, [xlsxInlineCell("C3", `Rows: ${rows.length} | Orders: ${totalOrders} | QTY: ${totalQty}`, 3)], { height: 18 }));
  rowXml.push(xlsxRowXml(4, [xlsxInlineCell("C4", filterSummary, 4)], { height: 20 }));
  rowXml.push(xlsxRowXml(5, [xlsxInlineCell("F5", "Checked By: ____________________", 13)], { height: 20 }));

  const headers = ["Job Nr.", "Order", "Item", "QTY", "Dimensions", "Customer", "Route", "Check"];
  rowXml.push(xlsxRowXml(6, headers.map((label, index) => xlsxInlineCell(`${xlsxColumnName(index + 1)}6`, label, 5)), { height: 22 }));

  let excelRow = 7;
  let visibleRowIndex = 0;
  let currentGlass = "";
  for (const row of rows) {
    const glass = String(row.glassType || "Unspecified Glass");
    if (glass !== currentGlass) {
      rowXml.push(xlsxRowXml(excelRow, [xlsxInlineCell(`A${excelRow}`, glass, 6)], { height: 19 }));
      merges.push(`A${excelRow}:H${excelRow}`);
      excelRow += 1;
      currentGlass = glass;
    }
    const alternate = visibleRowIndex % 2 === 1;
    const textStyle = alternate ? 8 : 7;
    const centeredStyle = alternate ? 10 : 9;
    const checkStyle = alternate ? 12 : 11;
    const values = [
      row.job || row.glassType || "",
      row.order || "",
      row.item || "",
      Number(row.pieces || 0),
      row.dimensions || "",
      row.customer || "",
      row.route || "Indian Trail",
      "☐",
    ];
    const cells = values.map((value, index) => {
      const reference = `${xlsxColumnName(index + 1)}${excelRow}`;
      if (index === 3) return xlsxNumberCell(reference, value, centeredStyle);
      if (index === 7) return xlsxInlineCell(reference, value, checkStyle);
      return xlsxInlineCell(reference, value, textStyle);
    });
    rowXml.push(xlsxRowXml(excelRow, cells, { height: 18 }));
    excelRow += 1;
    visibleRowIndex += 1;
  }

  const footerRow = excelRow + 1;
  rowXml.push(xlsxRowXml(footerRow, [xlsxInlineCell(`A${footerRow}`, `Printed at: ${printPreviewTimestamp(generatedAt)}`, 14)], { height: 18 }));
  merges.push(`A${footerRow}:H${footerRow}`);

  const printArea = `'${sheetName.replace(/'/g, "''")}'!$A$1:$H$${footerRow}`;
  const printTitles = `'${sheetName.replace(/'/g, "''")}'!$6:$6`;
  const worksheet = `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
  <sheetPr><pageSetUpPr fitToPage="1"/></sheetPr>
  <dimension ref="A1:H${footerRow}"/>
  <sheetViews><sheetView workbookViewId="0" showGridLines="0"><pane ySplit="6" topLeftCell="A7" activePane="bottomLeft" state="frozen"/></sheetView></sheetViews>
  <sheetFormatPr defaultRowHeight="18"/>
  <cols>
    <col min="1" max="1" width="24" customWidth="1"/><col min="2" max="2" width="14" customWidth="1"/>
    <col min="3" max="3" width="10" customWidth="1"/><col min="4" max="4" width="8" customWidth="1"/>
    <col min="5" max="5" width="17" customWidth="1"/><col min="6" max="6" width="25" customWidth="1"/>
    <col min="7" max="7" width="15" customWidth="1"/><col min="8" max="8" width="9" customWidth="1"/>
  </cols>
  <sheetData>${rowXml.join("")}</sheetData>
  <mergeCells count="${merges.length}">${merges.map((ref) => `<mergeCell ref="${ref}"/>`).join("")}</mergeCells>
  <pageMargins left="0.25" right="0.25" top="0.35" bottom="0.35" header="0.15" footer="0.15"/>
  <pageSetup paperSize="1" orientation="${orientation}" fitToWidth="1" fitToHeight="0" horizontalDpi="300" verticalDpi="300"/>
  <drawing r:id="rId1"/>
</worksheet>`;
  return { worksheet, footerRow, printArea, printTitles, sheetIndex };
}

