let xlsxCrcTable = null;
function xlsxCrc32(bytes) {
  if (!xlsxCrcTable) {
    xlsxCrcTable = new Uint32Array(256);
    for (let index = 0; index < 256; index += 1) {
      let value = index;
      for (let bit = 0; bit < 8; bit += 1) value = (value & 1) ? (0xEDB88320 ^ (value >>> 1)) : (value >>> 1);
      xlsxCrcTable[index] = value >>> 0;
    }
  }
  let crc = 0xFFFFFFFF;
  for (const byte of bytes) crc = xlsxCrcTable[(crc ^ byte) & 0xFF] ^ (crc >>> 8);
  return (crc ^ 0xFFFFFFFF) >>> 0;
}

function xlsxZipDateParts(date = new Date()) {
  const year = Math.max(1980, date.getFullYear());
  const dosTime = (date.getHours() << 11) | (date.getMinutes() << 5) | Math.floor(date.getSeconds() / 2);
  const dosDate = ((year - 1980) << 9) | ((date.getMonth() + 1) << 5) | date.getDate();
  return { dosTime, dosDate };
}

function xlsxConcatBytes(parts) {
  const length = parts.reduce((sum, part) => sum + part.length, 0);
  const output = new Uint8Array(length);
  let offset = 0;
  for (const part of parts) {
    output.set(part, offset);
    offset += part.length;
  }
  return output;
}

function xlsxStoredZip(entries) {
  const encoder = new TextEncoder();
  const localParts = [];
  const centralParts = [];
  const { dosTime, dosDate } = xlsxZipDateParts();
  let localOffset = 0;

  for (const entry of entries) {
    const nameBytes = encoder.encode(entry.name);
    const dataBytes = entry.data instanceof Uint8Array ? entry.data : encoder.encode(String(entry.data));
    const crc = xlsxCrc32(dataBytes);
    const localHeader = new Uint8Array(30);
    const localView = new DataView(localHeader.buffer);
    localView.setUint32(0, 0x04034B50, true);
    localView.setUint16(4, 20, true);
    localView.setUint16(6, 0x0800, true);
    localView.setUint16(8, 0, true);
    localView.setUint16(10, dosTime, true);
    localView.setUint16(12, dosDate, true);
    localView.setUint32(14, crc, true);
    localView.setUint32(18, dataBytes.length, true);
    localView.setUint32(22, dataBytes.length, true);
    localView.setUint16(26, nameBytes.length, true);
    localView.setUint16(28, 0, true);
    localParts.push(localHeader, nameBytes, dataBytes);

    const centralHeader = new Uint8Array(46);
    const centralView = new DataView(centralHeader.buffer);
    centralView.setUint32(0, 0x02014B50, true);
    centralView.setUint16(4, 20, true);
    centralView.setUint16(6, 20, true);
    centralView.setUint16(8, 0x0800, true);
    centralView.setUint16(10, 0, true);
    centralView.setUint16(12, dosTime, true);
    centralView.setUint16(14, dosDate, true);
    centralView.setUint32(16, crc, true);
    centralView.setUint32(20, dataBytes.length, true);
    centralView.setUint32(24, dataBytes.length, true);
    centralView.setUint16(28, nameBytes.length, true);
    centralView.setUint16(30, 0, true);
    centralView.setUint16(32, 0, true);
    centralView.setUint16(34, 0, true);
    centralView.setUint16(36, 0, true);
    centralView.setUint32(38, 0, true);
    centralView.setUint32(42, localOffset, true);
    centralParts.push(centralHeader, nameBytes);
    localOffset += localHeader.length + nameBytes.length + dataBytes.length;
  }

  const centralDirectory = xlsxConcatBytes(centralParts);
  const end = new Uint8Array(22);
  const endView = new DataView(end.buffer);
  endView.setUint32(0, 0x06054B50, true);
  endView.setUint16(4, 0, true);
  endView.setUint16(6, 0, true);
  endView.setUint16(8, entries.length, true);
  endView.setUint16(10, entries.length, true);
  endView.setUint32(12, centralDirectory.length, true);
  endView.setUint32(16, localOffset, true);
  endView.setUint16(20, 0, true);
  return xlsxConcatBytes([...localParts, centralDirectory, end]);
}

/** Build one logo-bearing, print-configured worksheet for each printable sheet. */
function buildFormattedPrintWorkbookBytes(preview, logoBytes, orientation = "portrait") {
  const sheets = Array.isArray(preview.previewSheets) && preview.previewSheets.length
    ? preview.previewSheets
    : buildLocalPrintSheets(printFilteredRows());
  const usedNames = new Set();
  const sheetRecords = sheets.map((sheet, index) => {
    const datePart = String(sheet.deliveryDate || "Date").replace(/^\d{4}-/, "");
    const modePart = sheet.mode === "rush" ? "Rush" : sheet.mode === "remake" ? "Remake" : "Delivery";
    const name = xlsxSafeSheetName(`${datePart} ${modePart}`, usedNames);
    return { sheet, index: index + 1, name };
  });
  const generatedAt = preview.generatedAt || new Date().toISOString();
  const worksheetRecords = sheetRecords.map(({ sheet, index, name }) => xlsxSheetDocument(sheet, orientation, generatedAt, index, name));
  const encoder = new TextEncoder();
  const entries = [];
  const worksheetOverrides = sheetRecords.map(({ index }) => `<Override PartName="/xl/worksheets/sheet${index}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>`).join("");
  const drawingOverrides = sheetRecords.map(({ index }) => `<Override PartName="/xl/drawings/drawing${index}.xml" ContentType="application/vnd.openxmlformats-officedocument.drawing+xml"/>`).join("");

  entries.push({ name: "[Content_Types].xml", data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">
  <Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>
  <Default Extension="xml" ContentType="application/xml"/>
  <Default Extension="png" ContentType="image/png"/>
  <Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>
  <Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>
  <Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/>
  <Override PartName="/docProps/app.xml" ContentType="application/vnd.openxmlformats-officedocument.extended-properties+xml"/>
  ${worksheetOverrides}${drawingOverrides}
</Types>` });
  entries.push({ name: "_rels/.rels", data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  <Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>
  <Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/>
  <Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/extended-properties" Target="docProps/app.xml"/>
</Relationships>` });
  entries.push({ name: "docProps/core.xml", data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" xmlns:dcmitype="http://purl.org/dc/dcmitype/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">
  <dc:title>Formatted Delivery List</dc:title><dc:creator>Delivery List Scanner</dc:creator><cp:lastModifiedBy>Delivery List Scanner</cp:lastModifiedBy>
  <dcterms:created xsi:type="dcterms:W3CDTF">${xlsxXmlEscape(generatedAt)}</dcterms:created><dcterms:modified xsi:type="dcterms:W3CDTF">${xlsxXmlEscape(generatedAt)}</dcterms:modified>
</cp:coreProperties>` });
  entries.push({ name: "docProps/app.xml", data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties" xmlns:vt="http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes">
  <Application>Delivery List Scanner</Application><AppVersion>0.268</AppVersion><Company>Builders FirstSource</Company>
  <TitlesOfParts><vt:vector size="${sheetRecords.length}" baseType="lpstr">${sheetRecords.map(({ name }) => `<vt:lpstr>${xlsxXmlEscape(name)}</vt:lpstr>`).join("")}</vt:vector></TitlesOfParts>
</Properties>` });

  const workbookSheets = sheetRecords.map(({ index, name }) => `<sheet name="${xlsxXmlEscape(name)}" sheetId="${index}" r:id="rId${index}"/>`).join("");
  const definedNames = worksheetRecords.map((record, index) => `<definedName name="_xlnm.Print_Area" localSheetId="${index}">${record.printArea}</definedName><definedName name="_xlnm.Print_Titles" localSheetId="${index}">${record.printTitles}</definedName>`).join("");
  entries.push({ name: "xl/workbook.xml", data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">
  <bookViews><workbookView xWindow="0" yWindow="0" windowWidth="24000" windowHeight="14000"/></bookViews>
  <sheets>${workbookSheets}</sheets><definedNames>${definedNames}</definedNames><calcPr calcId="191029" fullCalcOnLoad="1"/>
</workbook>` });
  entries.push({ name: "xl/_rels/workbook.xml.rels", data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">
  ${sheetRecords.map(({ index }) => `<Relationship Id="rId${index}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet${index}.xml"/>`).join("")}
  <Relationship Id="rId${sheetRecords.length + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>
</Relationships>` });
  entries.push({ name: "xl/styles.xml", data: xlsxStylesDocument() });
  entries.push({ name: "xl/media/logo.png", data: logoBytes instanceof Uint8Array ? logoBytes : new Uint8Array(logoBytes || []) });

  for (const record of worksheetRecords) {
    const index = record.sheetIndex;
    entries.push({ name: `xl/worksheets/sheet${index}.xml`, data: record.worksheet });
    entries.push({ name: `xl/worksheets/_rels/sheet${index}.xml.rels`, data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/drawing" Target="../drawings/drawing${index}.xml"/></Relationships>` });
    entries.push({ name: `xl/drawings/drawing${index}.xml`, data: xlsxDrawingDocument(index) });
    entries.push({ name: `xl/drawings/_rels/drawing${index}.xml.rels`, data: `<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="../media/logo.png"/></Relationships>` });
  }
  return xlsxStoredZip(entries.map((entry) => ({ ...entry, data: entry.data instanceof Uint8Array ? entry.data : encoder.encode(String(entry.data)) })));
}

async function exportFormattedPrintXlsx(preview = {}) {
  const logoUrl = new URL(PRINT_XLSX_LOGO_PATH, window.location.href).href;
  const logoResponse = await fetch(logoUrl, { cache: "force-cache" });
  if (!logoResponse.ok) throw new Error("The delivery-list logo could not be loaded for the Excel workbook.");
  const logoBytes = new Uint8Array(await logoResponse.arrayBuffer());
  const orientation = String(els.printOrientation?.value || "portrait") === "landscape" ? "landscape" : "portrait";
  const workbookBytes = buildFormattedPrintWorkbookBytes(preview, logoBytes, orientation);
  downloadGeneratedFile(new Blob([workbookBytes], { type: PRINT_XLSX_CONTENT_TYPE }), `${printExportFileStem(preview)}.xlsx`);
}

/** Keep the single output button aligned with the selected file type. */
function updatePrintOutputAction() {
  const format = String(els.printExportType?.value || "pdf").toLowerCase();
  const printing = format === "pdf";
  if (els.printOutputActionLabel) els.printOutputActionLabel.textContent = printing ? "Print List" : "Export List";
  if (els.printOutputActionIcon) els.printOutputActionIcon.className = printing ? "print-printer-icon-v197" : "print-export-doc-icon-v197";
  els.printOptionsSubmit?.classList.toggle("is-print", printing);
  els.printOptionsSubmit?.classList.toggle("is-export", !printing);
  if (els.printCopies) els.printCopies.disabled = !printing;
  if (els.printCopiesDecrease) els.printCopiesDecrease.disabled = !printing;
  if (els.printCopiesIncrease) els.printCopiesIncrease.disabled = !printing;
  document.querySelectorAll('[data-print-orientation]').forEach((button) => { button.disabled = !printing; });
  syncCustomSelect(els.printExportType);
}

async function submitPrintOptions(mode = "pdf") {
  // A quick click immediately after opening must wait for the same initialization
  // that loads list rows and commits Airport. This removes the intermittent need
  // to toggle the visible route chip before preview or print will work.
  if (state.printWorkspacePromise) await state.printWorkspacePromise;
  if (!state.printWorkspaceReady) {
    showInlineError("Print / Export is still loading the selected delivery list. Try again when the preview is ready.", false);
    return;
  }
  setPrintRouteGroups(selectedPrintRouteGroups());
  const listIds = selectedPrintListIds();
  if (!listIds.length) { showInlineError("No Airport Outbound delivery list is available for the selected date range.", false); return; }
  if (!selectedPrintRouteGroups().length) { showInlineError("Select at least one route to print or export.", false); return; }
  if (!allPrintGlassTypesSelected() && !selectedPrintGlassTypeValues().length) { showInlineError("Select All Glass or at least one exact glass type.", false); return; }
  const localPreview = buildLocalPrintSelectionPreview();
  if (localPreview.noResults) { showInlineError("Selected filters yield 0 results. Adjust the Print / Export filters before continuing.", false); return; }
  const selectedMode = ["pdf", "xlsx", "csv"].includes(String(mode || "").toLowerCase()) ? String(mode).toLowerCase() : "pdf";
  if (selectedMode === "pdf") {
    launchLocalPrintPackage(localPreview);
    return;
  }
  const originalLabel = els.printOutputActionLabel?.textContent || "Export List";
  if (els.printOptionsSubmit) els.printOptionsSubmit.disabled = true;
  if (els.printOutputActionLabel) els.printOutputActionLabel.textContent = selectedMode === "xlsx" ? "Building Workbook…" : "Preparing CSV…";
  try {
    if (selectedMode === "xlsx") await exportFormattedPrintXlsx(localPreview);
    else exportRawPrintCsv(localPreview);
  } catch (error) {
    showInlineError(error.message || "Could not prepare the selected delivery-list export.", false);
  } finally {
    if (els.printOptionsSubmit) els.printOptionsSubmit.disabled = Boolean(state.printPreviewResult?.noResults);
    if (els.printOutputActionLabel) els.printOutputActionLabel.textContent = originalLabel;
    updatePrintOutputAction();
  }
}

async function importTempDeliveryFolder() {
  const sourceFolder = els.tempFolderInput?.value.trim() || "";
  const { dateFrom, dateTo } = currentImportDateWindow();

  showImportStatusLoading("Importing Temp folder...", `Checking delivery dates from ${formatDisplayDate(dateFrom)} through the newest future list.`);
  playAppSound("import_start", { force: true });
  await waitForNextPaint();

  const result = await fetchJson("/api/import/folder", {
    method: "POST",
    body: JSON.stringify({ ...requestContext(), sourceFolder, dateFrom, dateTo }),
  });
  state.lists = result.lists || state.lists;
  if (result.activeListId) await activateList(result.activeListId, false);
  renderHome();
  await refreshAdminPage();
  const imported = result.importedFiles?.length || 0;
  const updated = result.updatedFiles?.length || 0;
  const skipped = result.skippedFiles?.length || 0;
  const ignored = result.ignoredFiles?.length || 0;
  const failed = result.failedFiles?.length || 0;
  const checked = result.checkedFiles ?? result.scannedFiles ?? imported + updated + skipped + failed;
  const total = result.totalFolderFiles ?? checked + ignored;
  if (els.importPreviewBox) {
    els.importPreviewBox.hidden = false;
    els.importPreviewBox.classList.remove("loading");
    els.importPreviewBox.classList.add("import-status-compact");
    els.importPreviewBox.classList.toggle("success", !failed);
    els.importPreviewBox.classList.toggle("review", Boolean(failed));

    const noUpdates = !imported && !updated && skipped && !failed;
    const windowText = `Checked ${checked} file${checked === 1 ? "" : "s"} in the active import window. ${ignored ? `Skipped ${ignored} older file${ignored === 1 ? "" : "s"} outside the date window. ` : ""}${total ? `Folder total: ${total}.` : ""}`;

    els.importPreviewBox.innerHTML = failed
      ? `
        <strong>Import completed with issues.</strong>
        <span>${imported} new, ${updated} updated, ${skipped} unchanged, ${failed} failed.</span>
        <small>${escapeHtml(windowText)}</small>
        ${result.failedFiles?.length ? `<small>${escapeHtml(result.failedFiles.map((file) => `${file.fileName}: ${(file.errors || []).join("; ")}`).join(" | "))}</small>` : ""}
      `
      : noUpdates
        ? `
          <strong>No updates found.</strong>
          <span>${skipped} delivery list file${skipped === 1 ? "" : "s"} checked. Existing New/Updated markers were refreshed where applicable.</span>
          <small>${escapeHtml(windowText)}</small>
        `
        : `
          <strong>Import complete.</strong>
          <span>${imported} new, ${updated} updated, ${skipped} unchanged.</span>
          <small>${escapeHtml(windowText)}</small>
        `;
  }
  playAppSound(failed ? "scan_warning" : "import_complete", { force: true });
}

/**
 * Purpose: Load the refresh admin page workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Requests current data, updates shared state, and invokes the existing renderer for affected controls.
 */
async function refreshAdminPage() {
  if (!state.backend) return;
  const requests = [];
  requests.push(hasPermission("view_admin") ? fetchJson("/api/admin/summary") : Promise.resolve(null));
  requests.push(hasPermission("manage_users") ? fetchJson("/api/admin/users") : Promise.resolve(null));
  requests.push(hasPermission("view_active_sessions") ? fetchJson("/api/admin/sessions") : Promise.resolve(null));
  requests.push(hasPermission("manage_customer_route_rules") ? fetchJson("/api/admin/customer-route-rules") : Promise.resolve(null));
  requests.push(hasPermission("manage_customer_route_rules") ? fetchJson("/api/admin/customer-emails") : Promise.resolve(null));
  requests.push(hasPermission("manage_bay_layout") ? fetchJson("/api/admin/bay-scanner-rules") : Promise.resolve(null));
  requests.push(hasPermission("manage_bay_layout") ? fetchJson("/api/admin/bay-auto-assigner") : Promise.resolve(null));
  requests.push(hasPermission("edit_delivery_lists") ? fetchJson("/api/admin/cross-date-scan-settings") : Promise.resolve(null));
  requests.push(hasPermission("manage_roles") ? fetchJson("/api/admin/roles") : Promise.resolve(null));
  const [summary, users, sessions, customerRules, customerEmails, bayScannerRules, bayAutoAssignSettings, crossDateScanSettings, roles] = await Promise.all(requests);
  if (summary) {
    state.adminSummary = summary;
    state.supersededReviewSummary = {
      pendingSupersededOrderReviews: Number(summary.pendingSupersededOrderReviews || 0),
      approvedSupersededOrderReviews: Number(summary.approvedSupersededOrderReviews || 0),
      keptSupersededOrderReviews: Number(summary.keptSupersededOrderReviews || 0),
    };
    renderSupersededReviewCount();
  }
  if (summary && els.adminSummary) {
    els.adminSummary.innerHTML = [
      miniStat("Active Delivery Lists", summary.activeDeliveryDates ?? summary.activeDeliveryLists ?? 0, `${summary.activeDeliveryLists ?? 0} active stages`),
      miniStat("Scans Today", summary.scanEventsToday ?? summary.scanEvents ?? 0),
      miniStat("Line Items", summary.lineItems ?? 0),
      miniStat("Active Users", summary.activeUsers ?? 0),
    ].join("");
  }
  if (els.adminLastUpdated) els.adminLastUpdated.textContent = `Last updated: ${new Date().toLocaleString()}`;
  if (summary) {
    // The Admin summary contains database-backed import history, but unchanged
    // automation checks may exist only in the newest run snapshot. Merge instead
    // of replacing so No Changes timestamps survive an Admin-page refresh.
    state.adminRecentImports = dlsAutomationMergeRecentImports(
      state.adminRecentImports,
      summary.recentImports || [],
    );
    renderImportHistory(state.adminRecentImports);
    renderAdminDeleteControls();
    renderAdminResetControls();
    if (els.tempFolderInput && !els.tempFolderInput.value && summary.tempDeliveryListsDir) els.tempFolderInput.value = summary.tempDeliveryListsDir;
  }
  state.adminUsers = users?.users || [];
  state.activeSessions = sessions?.sessions || [];
  state.adminCustomerRouteRules = customerRules?.rules || [];
  state.customerEmailSettings = customerEmails || state.customerEmailSettings || { contacts: [], cc: [], outbox: [] };
  state.bayScannerSettings = bayScannerRules || state.bayScannerSettings || { manualRules: [], barcodeRules: [] };
  state.bayAutoAssignSettings = bayAutoAssignSettings || state.bayAutoAssignSettings;
  state.crossDateScanSettings = crossDateScanSettings || state.crossDateScanSettings;
  state.adminRoles = roles?.roles || state.adminRoles || [];
  state.allPermissions = roles?.permissions || state.allPermissions || [];
  renderAdminUsers();
  renderAdminStations();
  renderManualEditStageOptions();
  renderCustomerRouteRules();
  renderCustomerEmailOverview();
  renderBayScannerRuleOverview();
  renderBayAutoAssignOverview();
  renderCrossDateScanOverview();
  renderActiveSessions();
}

/**
 * Purpose: Run the admin delivery list cutoff date workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function adminDeliveryListCutoffDate(pastDays = state.adminDeliveryListVisiblePastDays) {
  const cutoff = new Date();
  cutoff.setHours(0, 0, 0, 0);
  cutoff.setDate(cutoff.getDate() - Math.max(Number(pastDays || 0), 0));
  return cutoff;
}

/**
 * Purpose: Run the delivery list is in admin window workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function deliveryListIsInAdminWindow(list, pastDays = state.adminDeliveryListVisiblePastDays) {
  const deliveryDate = parseDateKey(list?.deliveryDate);

  if (!deliveryDate) return true;

  return deliveryDate >= adminDeliveryListCutoffDate(pastDays);
}

/**
 * Purpose: Run the admin delivery list hidden older rows workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function adminDeliveryListHiddenOlderRows(lists = state.lists, pastDays = state.adminDeliveryListVisiblePastDays) {
  return lists.filter((list) => !deliveryListIsInAdminWindow(list, pastDays));
}

/**
 * Purpose: Run the admin delivery list window label workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function adminDeliveryListWindowLabel(pastDays = state.adminDeliveryListVisiblePastDays) {
  const days = Math.max(Number(pastDays || 0), ADMIN_DELIVERY_LIST_DEFAULT_PAST_DAYS);

  if (days % 7 === 0) {
    const weeks = Math.max(Math.round(days / 7), 1);
    return `all future dates and the last ${weeks === 1 ? "week" : `${weeks} weeks`}`;
  }

  return `all future dates and the last ${days} days`;
}

/**
 * Purpose: Run the admin delivery list modal results HTML workflow for the browser application.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function adminDeliveryListModalResultsHtml(lists = state.lists, query = "") {
  const cleanQuery = String(query || "").trim();

  return deliveryListAdminRows(lists, 0, true, {
    includeLoadMore: !cleanQuery,
    query: cleanQuery,
    visiblePastDays: state.adminDeliveryListVisiblePastDays,
    sourceCount: state.lists.length,
  });
}

/**
 * Purpose: Render the render admin delivery list modal results workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
 */
function renderAdminDeliveryListModalResults(lists = state.lists, query = "") {
  const target = document.getElementById("adminDeliveryListModalResults");

  if (!target) return;

  target.innerHTML = adminDeliveryListModalResultsHtml(lists, query);
}

/**
 * Purpose: Load the refresh admin delivery list modal workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Requests current data, updates shared state, and invokes the existing renderer for affected controls.
 */
async function refreshAdminDeliveryListModal() {
  const searchInput = document.getElementById("adminDeliveryListModalSearch");
  const query = searchInput?.value.trim() || "";

  if (!query) {
    renderAdminDeliveryListModalResults(state.lists, "");
    return;
  }

  renderAdminDeliveryListModalResults(await searchAdminDeliveryLists(query), query);
}

/**
 * Purpose: Run the delivery list admin rows workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function deliveryListAdminRows(lists = state.lists, limit = 7, editable = false, options = {}) {
  const cleanQuery = String(options.query || "").trim();
  const includeLoadMore = Boolean(options.includeLoadMore);
  const visiblePastDays = Number(options.visiblePastDays || state.adminDeliveryListVisiblePastDays || ADMIN_DELIVERY_LIST_DEFAULT_PAST_DAYS);

  const sortedRows = lists
    .slice()
    .sort((a, b) => String(b.deliveryDate || "").localeCompare(String(a.deliveryDate || "")) || stageSort(a) - stageSort(b));

  const hiddenOlderRows = includeLoadMore ? adminDeliveryListHiddenOlderRows(sortedRows, visiblePastDays) : [];
  const visibleRows = includeLoadMore ? sortedRows.filter((list) => deliveryListIsInAdminWindow(list, visiblePastDays)) : sortedRows;
  const limitedRows = limit ? visibleRows.slice(0, limit) : visibleRows;
  const hiddenOlderDates = new Set(hiddenOlderRows.map((list) => list.deliveryDate).filter(Boolean));
  const shownDates = new Set(limitedRows.map((list) => list.deliveryDate).filter(Boolean));

  const summaryHtml = editable
    ? `
      <div class="admin-delivery-window-note">
        <strong>${escapeHtml(cleanQuery ? `Search results for "${cleanQuery}"` : `Showing ${adminDeliveryListWindowLabel(visiblePastDays)}`)}</strong>
        <span>${escapeHtml(shownDates.size)} delivery date${shownDates.size === 1 ? "" : "s"} / ${escapeHtml(limitedRows.length)} stage${limitedRows.length === 1 ? "" : "s"}${cleanQuery ? " found. Search checks every active delivery list, including older dates." : "."}</span>
      </div>
    `
    : "";

  const loadMoreHtml = includeLoadMore && hiddenOlderRows.length
    ? `
      <div class="admin-delivery-load-more-wrap">
        <button class="admin-delivery-load-more" type="button" data-admin-delivery-load-more>
          Load more older delivery lists
        </button>
        <span>${escapeHtml(hiddenOlderDates.size)} older delivery date${hiddenOlderDates.size === 1 ? "" : "s"} hidden (${escapeHtml(hiddenOlderRows.length)} stage${hiddenOlderRows.length === 1 ? "" : "s"}).</span>
      </div>
    `
    : "";

  if (!limitedRows.length) {
    return `
      ${summaryHtml}
      <div class="admin-empty">${escapeHtml(cleanQuery ? "No delivery lists match that search." : "No delivery lists found in the current window.")}</div>
      ${loadMoreHtml}
    `;
  }

  const groups = listsByDeliveryDate(limitedRows);

  return `
    ${summaryHtml}
    <div class="admin-delivery-edit-list">
      ${groups
        .map((group) => {
          const totalQty = group.lists.reduce((sum, list) => sum + Number(list.totalQty ?? list.itemCount ?? 0), 0);
          const scannedQty = group.lists.reduce((sum, list) => sum + Number(list.scannedQty || 0), 0);
          const percent = totalQty ? Math.round((scannedQty / totalQty) * 100) : 0;

          return `
            <details class="admin-delivery-date-group">
              <summary class="admin-delivery-date-summary">
                <span class="admin-delivery-date-main">
                  <strong>${escapeHtml(formatDisplayDate(group.date))}</strong>
                  <small>${escapeHtml(group.lists.length)} stage${group.lists.length === 1 ? "" : "s"} | ${escapeHtml(scannedQty)} / ${escapeHtml(totalQty)} pcs | ${escapeHtml(percent)}%</small>
                </span>

                <span class="admin-delivery-date-progress">
                  <span class="progress-line"><i style="width: ${Math.min(percent, 100)}%"></i></span>
                </span>

                ${
                  editable
                    ? `<span class="admin-date-action-row">
                        <button
                          type="button"
                          class="icon-only icon-reset"
                          data-admin-date-reset="${escapeHtml(group.date)}"
                          title="Reset all stages for ${escapeHtml(formatDisplayDate(group.date))}"
                          aria-label="Reset all stages for ${escapeHtml(formatDisplayDate(group.date))}"
                        ></button>
                        <button
                          type="button"
                          class="icon-only icon-trash danger"
                          data-admin-date-delete="${escapeHtml(group.date)}"
                          title="Delete all stages for ${escapeHtml(formatDisplayDate(group.date))}"
                          aria-label="Delete all stages for ${escapeHtml(formatDisplayDate(group.date))}"
                        ></button>
                      </span>`
                    : ""
                }
              </summary>

              <div class="admin-delivery-stage-list">
                ${group.lists
                  .map((list) => {
                    const listTotalQty = Number(list.totalQty ?? list.itemCount ?? 0);
                    const listScannedQty = Number(list.scannedQty || 0);
                    const listPercent = listTotalQty ? Math.round((listScannedQty / listTotalQty) * 100) : 0;

                    return `
                      <article class="admin-delivery-stage-row">
                        <span class="admin-delivery-stage-main">
                          <strong>${escapeHtml(list.stage || list.label || list.id)}</strong>
                          <small>${escapeHtml(list.scanner || "")}</small>
                        </span>

                        <span class="admin-delivery-stage-qty">
                          ${escapeHtml(listScannedQty)} / ${escapeHtml(listTotalQty)} pcs
                          <span class="progress-line"><i style="width: ${Math.min(listPercent, 100)}%"></i></span>
                        </span>

                        ${
                          editable
                            ? `<span class="admin-action-cell">
                                <button
                                  type="button"
                                  class="icon-only icon-pencil"
                                  data-admin-list-edit="${escapeHtml(list.id)}"
                                  title="Edit ${escapeHtml(list.label || list.id)}"
                                  aria-label="Edit ${escapeHtml(list.label || list.id)}"
                                ></button>
                                <button
                                  type="button"
                                  class="icon-only icon-reset"
                                  data-admin-list-reset="${escapeHtml(list.id)}"
                                  title="Reset scans for ${escapeHtml(list.label || list.id)}"
                                  aria-label="Reset scans for ${escapeHtml(list.label || list.id)}"
                                ></button>
                                <button
                                  type="button"
                                  class="icon-only icon-trash danger"
                                  data-admin-list-delete="${escapeHtml(list.id)}"
                                  title="Delete ${escapeHtml(list.label || list.id)}"
                                  aria-label="Delete ${escapeHtml(list.label || list.id)}"
                                ></button>
                              </span>`
                            : ""
                        }
                      </article>
                    `;
                  })
                  .join("")}
              </div>
            </details>
          `;
        })
        .join("")}
    </div>
    ${loadMoreHtml}
  `;
}

/** Return the accessible inline eye icon used by delivery-list change previews. */
function adminUpdatePreviewIconHtml() {
  return `<svg class="admin-update-preview-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false">
    <path d="M2.5 12c1.8-4.2 5.1-6.5 9.5-6.5s7.7 2.3 9.5 6.5c-1.8 4.2-5.1 6.5-9.5 6.5S4.3 16.2 2.5 12Z"></path>
    <circle cx="12" cy="12" r="3.2"></circle>
  </svg>`;
}

/** Classify one retained change snapshot by its actual item route first. */
function deliveryUpdatePreviewLocationKey(item = {}) {
  const route = inferredRoute(item);
  if (route === "DTC") return "dtc";
  if (route === "GNV") return "greenville";
  if (route === "CPU") return "cpu";
  if (route) return "airport";

  // Older removal snapshots did not always retain ROUTE. Use the stage only as
  // a legacy fallback; current outbound snapshots are classified by item route.
  const stageText = `${item.stage || ""} ${item.scanner || ""}`.toLowerCase();
  if (stageText.includes("dtc") || stageText.includes("deliver to customer")) return "dtc";
  if (stageText.includes("greenville") || /\bgnv\b/.test(stageText)) return "greenville";
  if (stageText.includes("customer pickup") || /\bcpu\b/.test(stageText)) return "cpu";
  return "indian-trail";
}

/**
 * Purpose: Run the search admin delivery lists workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function deliveryListUpdatePreviewHtml(payload = {}) {
  const lists = Array.isArray(payload.lists) && payload.lists.length
    ? payload.lists
    : payload.list
      ? [payload.list]
      : [];
  const primaryList = lists[0] || payload.list || {};
  const items = Array.isArray(payload.items) ? payload.items : [];
  const deliveryDate = primaryList.deliveryDate || primaryList.delivery_date || "";
  const totalPieces = items.reduce((sum, item) => sum + Number(item.qty || 0), 0);
  const metricCards = [
    ["all", items.length, "All rows"],
    ["new", Number(payload.newCount || 0), "New rows"],
    ["updated", Number(payload.updatedCount || 0), "Updated rows"],
    ["removed", Number(payload.removedCount || 0), "Removed rows"],
  ];
  const expectedChangedCount = Number(payload.expectedChangedCount || items.length);
  const previewIsIncomplete = expectedChangedCount > items.length;
  const previewErrors = Array.isArray(payload.previewErrors) ? payload.previewErrors.filter(Boolean) : [];
  const fieldDefinitions = [
    ["qty", "Quantity"],
    ["dimensions", "Dimensions"],
    ["customer", "Customer"],
    ["job", "Job"],
    ["product", "Glass / Product"],
    ["route", "Route"],
    ["queueState", "Queue state"],
    ["sourceId", "Source ID"],
    ["barcode", "Barcode"],
  ];
  const supportedFields = new Set(fieldDefinitions.map(([key]) => key));
  const changeLabels = { new: "New", updated: "Updated", removed: "Removed" };
  const locationDefinitions = [
    { key: "airport", label: "Airport Road", hint: "Airport Road and custom route orders" },
    { key: "indian-trail", label: "Indian Trail", hint: "Indian Trail route orders" },
    { key: "greenville", label: "Greenville", hint: "Greenville route orders" },
    { key: "cpu", label: "CPU", hint: "Customer Pickup orders" },
    { key: "dtc", label: "DTC", hint: "Deliver to Customer orders" },
  ];

  const displayValue = (record, key) => {
    const value = record && typeof record === "object" ? record[key] : "";
    if (key === "route") return routeLabel({ route: value }) || value || "—";
    if (key === "qty") return `${Number(value || 0)} pc${Number(value || 0) === 1 ? "" : "s"}`;
    return String(value ?? "").trim() || "—";
  };
  const changedFieldsForItem = (item) => {
    const explicit = Array.isArray(item.changedFields)
      ? item.changedFields.filter((key) => supportedFields.has(String(key)))
      : [];
    if (explicit.length) return explicit;
    const previous = item.previous && typeof item.previous === "object" ? item.previous : {};
    if (!Object.keys(previous).length) return [];
    return fieldDefinitions.map(([key]) => key).filter((key) => displayValue(previous, key) !== displayValue(item, key));
  };
  const previewLocationKey = (item) => deliveryUpdatePreviewLocationKey(item);
  const previewGlassType = (item) => String(item.glassType || item.product || "").trim() || "Other Glass";
  const previewOrderKey = (item) => String(item.order || "Unknown order").trim() || "Unknown order";
  const changeTypeForItem = (item) => {
    const value = String(item.changeType || "").toLowerCase();
    return ["new", "updated", "removed"].includes(value) ? value : "updated";
  };
  const countTypes = (rows) => ({
    new: rows.filter((item) => changeTypeForItem(item) === "new").length,
    updated: rows.filter((item) => changeTypeForItem(item) === "updated").length,
    removed: rows.filter((item) => changeTypeForItem(item) === "removed").length,
  });
  const typeBadgeHtml = (counts) => `
    ${counts.new ? `<b class="is-new">${escapeHtml(counts.new)} new</b>` : ""}
    ${counts.updated ? `<b class="is-updated">${escapeHtml(counts.updated)} updated</b>` : ""}
    ${counts.removed ? `<b class="is-removed">${escapeHtml(counts.removed)} removed</b>` : ""}`;
  const headingCountHtml = (lineCount, pieces, lineLabel = "lines") => `
    <span class="delivery-update-preview-heading-counts-v257">
      <span><b>${escapeHtml(lineCount)}</b> ${escapeHtml(lineLabel)}</span>
      <span><b>${escapeHtml(pieces)}</b> pcs</span>
    </span>`;
  const commonOrderValue = (rows, key) => {
    const values = [...new Set(rows.map((item) => String(item?.[key] || "").trim()).filter(Boolean))];
    return values.length === 1 ? values[0] : values.length > 1 ? "Multiple" : "—";
  };
  const itemSearchText = (item) => [
    item.order, item.item, item.customer, item.job, item.product, item.dimensions,
    item.route, item.stage, item.scanner, item.barcode, item.sourceId,
  ].join(" ").toLowerCase();

  const itemRowHtml = (item) => {
    const type = changeTypeForItem(item);
    const title = changeLabels[type];
    const previous = item.previous && typeof item.previous === "object" ? item.previous : {};
    const changedFields = type === "updated" ? changedFieldsForItem(item) : [];
    const diffHtml = changedFields.length
      ? `<div class="delivery-update-preview-diffs delivery-update-preview-item-diffs-v257">
          ${changedFields.map((key) => {
            const label = fieldDefinitions.find(([fieldKey]) => fieldKey === key)?.[1] || key;
            return `<span class="delivery-update-preview-diff">
              <small>${escapeHtml(label)}</small>
              <del>${escapeHtml(displayValue(previous, key))}</del>
              <i aria-hidden="true">→</i>
              <strong>${escapeHtml(displayValue(item, key))}</strong>
            </span>`;
          }).join("")}
        </div>`
      : "";
    return `<article class="delivery-update-preview-item-row-v257 is-${type}" data-preview-change-type="${type}" data-preview-search="${escapeHtml(itemSearchText(item))}">
      <div class="delivery-update-preview-item-main-v257">
        <span class="delivery-update-type">${escapeHtml(title)}</span>
        <span class="delivery-update-preview-item-number-v257"><strong>Item ${escapeHtml(item.item || "—")}</strong><small>${escapeHtml(item.dimensions || "No dimensions")}</small></span>
        <b class="delivery-update-preview-item-qty-v257">${escapeHtml(Number(item.qty || 0))} pc${Number(item.qty || 0) === 1 ? "" : "s"}</b>
      </div>
      ${diffHtml}
    </article>`;
  };

  const orderGroupHtml = (order, orderItems) => {
    const sortedItems = orderItems.slice().sort((a, b) => (
      Number(a.item || 0) - Number(b.item || 0) || String(a.item || "").localeCompare(String(b.item || ""))
    ));
    const counts = countTypes(sortedItems);
    const pieces = sortedItems.reduce((sum, item) => sum + Number(item.qty || 0), 0);
    const customer = commonOrderValue(sortedItems, "customer");
    const job = commonOrderValue(sortedItems, "job");
    const route = routeLabel({ route: commonOrderValue(sortedItems, "route") }) || commonOrderValue(sortedItems, "route");
    const glass = previewGlassType(sortedItems[0] || {});
    return `<details class="delivery-update-preview-order-group-v256 delivery-update-preview-order-group-v257" data-preview-container="order">
      <summary>
        <span class="delivery-update-preview-nested-chevron" aria-hidden="true"></span>
        <span class="delivery-update-preview-order-copy-v256"><strong>Order ${escapeHtml(order)}</strong><small>${escapeHtml(customer)}</small></span>
        ${headingCountHtml(sortedItems.length, pieces)}
        <span class="delivery-update-preview-location-badges">${typeBadgeHtml(counts)}</span>
      </summary>
      <div class="delivery-update-preview-order-body-v256 delivery-update-preview-order-body-v257">
        <div class="delivery-update-preview-order-meta-v257">
          <span><small>Customer</small><strong>${escapeHtml(customer)}</strong></span>
          <span><small>Job</small><strong>${escapeHtml(job)}</strong></span>
          <span><small>Route</small><strong>${escapeHtml(route || "—")}</strong></span>
          <span><small>Glass / Product</small><strong>${escapeHtml(glass)}</strong></span>
        </div>
        <div class="delivery-update-preview-item-list-v257">${sortedItems.map(itemRowHtml).join("")}</div>
      </div>
    </details>`;
  };

  const glassGroupHtml = (glassType, glassItems) => {
    const orders = new Map();
    glassItems.forEach((item) => {
      const order = previewOrderKey(item);
      if (!orders.has(order)) orders.set(order, []);
      orders.get(order).push(item);
    });
    const orderedOrders = [...orders.entries()].sort(([a], [b]) => (
      Number(a || 0) - Number(b || 0) || String(a).localeCompare(String(b))
    ));
    const counts = countTypes(glassItems);
    const pieces = glassItems.reduce((sum, item) => sum + Number(item.qty || 0), 0);
    return `<details class="delivery-update-preview-glass-group-v256 delivery-update-preview-glass-group-v257" data-preview-container="glass">
      <summary>
        <span class="delivery-update-preview-nested-chevron" aria-hidden="true"></span>
        <span class="delivery-update-preview-glass-copy-v256"><strong>${escapeHtml(glassType)}</strong><small>${escapeHtml(orderedOrders.length)} order${orderedOrders.length === 1 ? "" : "s"}</small></span>
        ${headingCountHtml(glassItems.length, pieces)}
        <span class="delivery-update-preview-location-badges">${typeBadgeHtml(counts)}</span>
      </summary>
      <div class="delivery-update-preview-glass-body-v256">${orderedOrders.map(([order, rows]) => orderGroupHtml(order, rows)).join("")}</div>
    </details>`;
  };

  const locationHtml = locationDefinitions.map((location) => {
    const locationItems = items
      .filter((item) => previewLocationKey(item) === location.key)
      .sort((a, b) => (
        previewGlassType(a).localeCompare(previewGlassType(b))
        || Number(a.order || 0) - Number(b.order || 0)
        || Number(a.item || 0) - Number(b.item || 0)
      ));
    if (!locationItems.length) return "";
    const glasses = new Map();
    locationItems.forEach((item) => {
      const glassType = previewGlassType(item);
      if (!glasses.has(glassType)) glasses.set(glassType, []);
      glasses.get(glassType).push(item);
    });
    const orderedGlassTypes = [...glasses.entries()].sort(([a], [b]) => a.localeCompare(b));
    const locationPieces = locationItems.reduce((sum, item) => sum + Number(item.qty || 0), 0);
    const typeCounts = countTypes(locationItems);
    return `<details class="delivery-update-preview-location-group is-${location.key} delivery-update-preview-location-group-v257" data-preview-group data-preview-container="route" data-preview-location="${location.key}">
      <summary>
        <span class="delivery-update-preview-location-chevron" aria-hidden="true"></span>
        <span class="delivery-update-preview-location-copy"><strong>${escapeHtml(location.label)}</strong><small>${escapeHtml(location.hint)}</small></span>
        ${headingCountHtml(locationItems.length, locationPieces)}
        <span class="delivery-update-preview-location-badges">${typeBadgeHtml(typeCounts)}</span>
      </summary>
      <div class="delivery-update-preview-location-body"><div class="delivery-update-preview-glass-list-v256">${orderedGlassTypes.map(([glassType, rows]) => glassGroupHtml(glassType, rows)).join("")}</div></div>
    </details>`;
  }).join("");

  return `<section class="delivery-update-preview-v184 delivery-update-preview-v230 delivery-update-preview-v248 delivery-update-preview-v251 delivery-update-preview-v252 delivery-update-preview-v256 delivery-update-preview-v257" data-preview-filter="all">
    <header class="delivery-update-preview-header-v230">
      <div><span>Delivery list changes</span><h3>${escapeHtml(formatDisplayDate(deliveryDate))}</h3><p>${escapeHtml(items.length)} changed item${items.length === 1 ? "" : "s"} · ${escapeHtml(totalPieces)} piece${totalPieces === 1 ? "" : "s"}</p></div>
      <div class="delivery-update-preview-metrics-v230">${metricCards.map(([type, value, label]) => `<span class="is-${type}"><b>${escapeHtml(value)}</b><small>${escapeHtml(label)}</small></span>`).join("")}</div>
    </header>
    ${previewErrors.length ? `<div class="delivery-update-preview-warning-v249"><strong>Some stages could not be loaded.</strong><span>${escapeHtml(previewErrors.join(" · "))}</span></div>` : ""}
    <div class="delivery-update-preview-toolbar-v248">
      <div class="delivery-update-preview-filter-buttons" role="group" aria-label="Filter delivery-list changes">${metricCards.map(([type, value, label], index) => `<button type="button" data-preview-filter-button="${type}" aria-pressed="${index === 0 ? "true" : "false"}">${escapeHtml(label)} <b>${escapeHtml(value)}</b></button>`).join("")}</div>
      <label class="delivery-update-preview-search-v248"><span>Find an order or item</span><input type="search" data-preview-search-input placeholder="Order, item, customer, job, glass type..." autocomplete="off"></label>
      <p data-preview-result-count>Showing ${escapeHtml(items.length)} of ${escapeHtml(items.length)} changes</p>
    </div>
    ${previewIsIncomplete ? `<div class="delivery-update-preview-guidance-v230 is-warning"><span aria-hidden="true"></span><p>${escapeHtml(expectedChangedCount)} changes were recorded, but only ${escapeHtml(items.length)} historical item snapshots are still available.</p></div>` : ""}
    <div class="delivery-update-preview-groups-v230 delivery-update-preview-locations-v251">${locationHtml || '<div class="admin-empty">No item-level changes were recorded for this import.</div>'}</div>
  </section>`;
}

function initializeDeliveryListUpdatePreviewControls() {
  const root = els.adminModalBody?.querySelector(".delivery-update-preview-v248");
  if (!root) return;
  const buttons = [...root.querySelectorAll("[data-preview-filter-button]")];
  const searchInput = root.querySelector("[data-preview-search-input]");
  const resultCount = root.querySelector("[data-preview-result-count]");
  const rows = [...root.querySelectorAll("[data-preview-change-type]")];
  const containers = [...root.querySelectorAll("[data-preview-container]")];
  let selectedType = "all";

  const apply = () => {
    const query = String(searchInput?.value || "").trim().toLowerCase();
    const activelyFiltering = Boolean(query) || selectedType !== "all";
    let visibleCount = 0;
    rows.forEach((row) => {
      const typeMatch = selectedType === "all" || row.dataset.previewChangeType === selectedType;
      const searchMatch = !query || String(row.dataset.previewSearch || "").includes(query);
      row.hidden = !(typeMatch && searchMatch);
      if (!row.hidden) visibleCount += 1;
    });

    // Process Item -> Order -> Glass -> Route so each parent can decide whether
    // any matching descendant remains. Filtering opens only the matching path;
    // normal viewing keeps every dropdown collapsed until the user chooses it.
    [...containers].reverse().forEach((container) => {
      const visibleChild = container.querySelector("[data-preview-change-type]:not([hidden])");
      container.hidden = !visibleChild;
      if (activelyFiltering && !container.hidden) container.open = true;
    });
    if (!activelyFiltering) {
      containers.forEach((container) => {
        if (container.dataset.previewContainer !== "route") return;
        container.hidden = !container.querySelector("[data-preview-change-type]:not([hidden])");
      });
    }

    buttons.forEach((button) => {
      button.setAttribute("aria-pressed", String(button.dataset.previewFilterButton === selectedType));
    });
    if (resultCount) resultCount.textContent = `Showing ${visibleCount} of ${rows.length} changes`;
  };

  buttons.forEach((button) => button.addEventListener("click", () => {
    selectedType = String(button.dataset.previewFilterButton || "all");
    apply();
  }));
  searchInput?.addEventListener("input", apply);
  apply();
}


function importPreviewPayloadsFromContext(contextKey, listIds) {
  const entries = state.adminImportPreviewContexts.get(String(contextKey || "")) || [];
  if (!entries.length) return [];
  const ids = new Set(listIds);
  const summaries = entries.flatMap((entry) => (
    Array.isArray(entry.stageSummaries)
      ? entry.stageSummaries
      : Array.isArray(entry.stages)
        ? entry.stages
        : []
  ));

  return [...ids].flatMap((listId) => {
    const stage = summaries.find((row) => String(row?.listId || "") === listId);
    if (!stage) return [];
    const items = Array.isArray(stage.changeItems)
      ? stage.changeItems.filter((item) => item && typeof item === "object")
      : [];
    if (!items.length && Number(stage.changedLineCount || 0) > 0) return [];
    const list = state.lists.find((row) => String(row.id || "") === listId) || {
      id: listId,
      deliveryDate: entries[0]?.deliveryDate || "",
      stage: stage.stage || stage.label || "Historical stage",
      scanner: stage.scanner || stage.stageProfile || "",
    };
    return [{
      list,
      items,
      stageCreated: Boolean(stage.created || stage.stageCreated),
      expectedChangedCount: Number(stage.changedLineCount || items.length),
      removedPieceQty: Number(stage.removedPieceQty || 0),
      previewSource: "selected-import-run",
    }];
  });
}

async function openDeliveryListUpdatePreview(listIds, routeGroup = "", contextKey = "") {
  const ids = [...new Set(String(listIds || "").split(",").map((value) => value.trim()).filter(Boolean))];
  if (!ids.length) throw new Error("No changed delivery-list stages were supplied for preview.");

  openAdminModal("deliveryUpdatePreview", {
    title: "Delivery List Update Preview",
    eyebrow: "Delivery List Management",
    description: "",
    status: "Loading",
    body: `<div class="admin-empty loading">Loading changes...</div>`,
  });

  try {
    let payloads = importPreviewPayloadsFromContext(contextKey, ids);
    let failedRequests = [];
    if (!payloads.length) {
      const requests = await Promise.allSettled(ids.map((listId) => (
        fetchJson(`/api/admin/delivery-list-update-preview?listId=${encodeURIComponent(listId)}`)
      )));
      payloads = requests
        .filter((result) => result.status === "fulfilled")
        .map((result) => result.value);
      failedRequests = requests.filter((result) => result.status === "rejected");
    }
    if (!payloads.length) {
      throw failedRequests[0]?.reason || new Error("No delivery-list changes could be loaded.");
    }
    const lists = payloads.map((payload) => payload.list).filter(Boolean);
    const allItems = payloads.flatMap((payload) => (
      (payload.items || []).map((item) => {
        const recordedType = String(item.changeType || "updated").toLowerCase();
        const changeType = payload.stageCreated && recordedType !== "removed" ? "new" : recordedType;
        return {
          ...item,
          changeType,
          stage: payload.list?.stage || payload.list?.label || "",
          scanner: payload.list?.scanner || "",
        };
      })
    ));
    const normalizedRouteGroup = String(routeGroup || "").trim().replaceAll("_", "-");
    const items = normalizedRouteGroup
      ? allItems.filter((item) => deliveryUpdatePreviewLocationKey(item) === normalizedRouteGroup)
      : allItems;
    const combined = {
      lists,
      list: lists[0] || {},
      items,
      newCount: items.filter((item) => item.changeType === "new").length,
      updatedCount: items.filter((item) => item.changeType === "updated").length,
      removedCount: items.filter((item) => item.changeType === "removed").length,
      removedPieceQty: payloads.reduce((sum, payload) => sum + Number(payload.removedPieceQty || 0), 0),
      expectedChangedCount: normalizedRouteGroup
        ? items.length
        : payloads.reduce((sum, payload) => sum + Number(payload.expectedChangedCount || (payload.items || []).length), 0),
      previewRouteGroup: normalizedRouteGroup,
      previewSources: [...new Set(payloads.map((payload) => String(payload.previewSource || "notices")).filter(Boolean))],
      previewErrors: failedRequests.map((result) => String(result.reason?.message || result.reason || "A stage preview could not be loaded.")),
    };
    if (els.adminModalBody) els.adminModalBody.innerHTML = deliveryListUpdatePreviewHtml(combined);
    if (els.adminModalStatusText) {
      els.adminModalStatusText.textContent = `${items.length} change${items.length === 1 ? "" : "s"}`;
    }
    initializeDeliveryListUpdatePreviewControls();
    applyLanguageToRoot(els.adminModalBody);
  } catch (error) {
    if (els.adminModalBody) els.adminModalBody.innerHTML = `<div class="admin-empty review">${escapeHtml(error.message)}</div>`;
    throw error;
  }
}

async function searchAdminDeliveryLists(query) {
  const clean = String(query || "").trim();
  const local = state.lists.filter((list) =>
    [list.label, list.deliveryDate, formatDisplayDate(list.deliveryDate), list.stage, list.scanner]
      .some((value) => String(value || "").toLowerCase().includes(clean.toLowerCase())),
  );
  if (!state.backend || clean.length < 2) return local;
  try {
    const payload = await fetchJson(`/api/admin/line-items/search?q=${encodeURIComponent(clean)}`);
    const matchingIds = new Set((payload.results || []).map((item) => item.listId).filter(Boolean));
    const merged = [...local];
    for (const list of state.lists) {
      if (matchingIds.has(list.id) && !merged.some((existing) => existing.id === list.id)) merged.push(list);
    }
    return merged;
  } catch (error) {
    console.warn("Admin delivery-list search failed", error);
    return local;
  }
}

/**
 * Purpose: Run the active recent imports workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function activeRecentImports(imports = state.adminRecentImports || []) {
  const activeListIds = new Set(state.lists.map((list) => list.id));
  const activeByDate = listsByDeliveryDate(state.lists);
  const yesterday = new Date();
  yesterday.setDate(yesterday.getDate() - 1);
  yesterday.setHours(0, 0, 0, 0);

  const cleanedImports = imports
    .map((entry) => {
      const deliveryDate = String(entry.deliveryDate || "").trim();
      const deliveryDateLists = deliveryDate
        ? state.lists.filter((list) => String(list.deliveryDate || "") === deliveryDate)
        : [];
      const suppliedListIds = [
        ...(Array.isArray(entry.listIds) ? entry.listIds : []),
        ...(Array.isArray(entry.changedListIds) ? entry.changedListIds : []),
        ...(Array.isArray(entry.reactivatedListIds) ? entry.reactivatedListIds : []),
      ];

      const stageSummaryHasChanges = (row = {}) =>
        Number(row.changedLineCount || 0) > 0 ||
        Number(row.changedPieceQty || 0) > 0 ||
        Number(row.addedPieceQty || 0) > 0 ||
        Number(row.removedLineCount || 0) > 0 ||
        Number(row.removedPieceQty || 0) > 0 ||
        Boolean(row.created || row.reactivated);

      // Keep a removal-only stage in Delivery List Management even when A+W
      // removed its final active item. The delivery-list header and notice
      // snapshots still exist, so the stage-level preview remains reviewable.
      let stageSummaries = Array.isArray(entry.stageSummaries)
        ? entry.stageSummaries.filter((row) => (
            row.listId && (activeListIds.has(row.listId) || stageSummaryHasChanges(row))
          ))
        : [];

      // A successful No Changes run intentionally does not rewrite the scanner
      // database, so the importer can return a date-level result without changed
      // stage rows. Hydrate those rows from the live catalog so Delivery List
      // Management still shows every stage and the run-completion timestamp.
      if (!stageSummaries.length && deliveryDateLists.length) {
        stageSummaries = deliveryDateLists.map((list) => ({
          listId: list.id,
          stage: list.stage,
          stageProfile: list.scanner,
          label: list.label,
          totalQty: Number(list.totalQty || 0),
          changedLineCount: 0,
          changedPieceQty: 0,
          addedPieceQty: 0,
          created: false,
          importedAt: entry.importedAt || entry.checkedAt || entry.updatedAt || "",
          checkedAt: entry.checkedAt || entry.importedAt || entry.updatedAt || "",
          updatedAt: entry.updatedAt || entry.importedAt || entry.checkedAt || "",
        }));
      }

      const changedSummaryIds = new Set(
        stageSummaries.filter(stageSummaryHasChanges).map((row) => row.listId),
      );
      const listIds = [...new Set([
        ...suppliedListIds,
        ...stageSummaries.map((row) => row.listId),
      ])].filter((listId) => activeListIds.has(listId) || changedSummaryIds.has(listId));

      return {
        ...entry,
        listIds,
        stageSummaries,
      };
    })
    .filter((entry) => {
      const hasActiveListIds = Array.isArray(entry.listIds) && entry.listIds.length > 0;
      const hasActiveStageSummaries = Array.isArray(entry.stageSummaries) && entry.stageSummaries.length > 0;

      return hasActiveListIds || hasActiveStageSummaries;
    });

  const importedDateKeys = new Set(cleanedImports.map((entry) => String(entry.deliveryDate || "")).filter(Boolean));
  const liveDateEntries = activeByDate
    .filter((group) => {
      const date = parseDateKey(group.date);
      return date && date >= yesterday && !importedDateKeys.has(group.date);
    })
    .map((group) => ({
      id: `active-${group.date}`,
      batchId: `active-${group.date}`,
      deliveryDate: group.date,
      sourceName: "Active delivery lists",
      importKind: "active_window",
      rowCount: group.lists.reduce((sum, list) => sum + Number(list.itemCount || 0), 0),
      totalQty: group.lists.reduce((sum, list) => sum + Number(list.totalQty || 0), 0),
      importedAt: "",
      createdCount: 0,
      updatedCount: 0,
      addedPieceQty: 0,
      changedPieceQty: 0,
      stageSummaries: group.lists.map((list) => ({
        listId: list.id,
        stage: list.stage,
        stageProfile: list.scanner,
        totalQty: list.totalQty || 0,
        changedLineCount: 0,
        changedPieceQty: 0,
        addedPieceQty: 0,
        created: false,
      })),
      listIds: group.lists.map((list) => list.id),
    }));

  return [...cleanedImports, ...liveDateEntries];
}

/**
 * Purpose: Render the render admin delivery lists workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
 */
function normalizeAdminDeliveryListsMarkup(markup = "") {
  return String(markup || "").replace(
    /(<details\s+class="admin-import-date-group[^>]*?)\s+open(\s*>)/g,
    "$1$2",
  );
}

function rememberOpenAdminDeliveryGroups() {
  if (!els.adminDeliveryLists) return;
  els.adminDeliveryLists.querySelectorAll(".admin-import-date-group[data-admin-delivery-group-key]").forEach((details) => {
    const key = String(details.dataset.adminDeliveryGroupKey || "");
    if (!key) return;
    if (details.open) state.adminOpenDeliveryGroups.add(key);
    else state.adminOpenDeliveryGroups.delete(key);
  });
}

function renderAdminDeliveryLists() {
  if (!els.adminDeliveryLists) return;
  const today = todayKey();
  if (state.adminTodayImportDate && state.adminTodayImportDate !== today) {
    state.adminTodayImportEntries = [];
    state.adminTodayImportLoaded = false;
    state.adminTodayImportDate = "";
    state.adminImportRunPage = 1;
    state.adminSelectedImportRunKey = "";
  }

  // Delivery List Management refreshes while the automation controller checks
  // for new runs. Preserve the user's manual open/closed choices and avoid
  // replacing identical markup, which previously caused the list cards to flash.
  rememberOpenAdminDeliveryGroups();
  const markup = renderAdminImportRunBrowser(activeRecentImports());
  const normalizedMarkup = normalizeAdminDeliveryListsMarkup(markup);
  if (normalizedMarkup !== state.adminDeliveryListsNormalizedMarkup) {
    els.adminDeliveryLists.innerHTML = markup;
    state.adminDeliveryListsNormalizedMarkup = normalizedMarkup;
  }

  if (!state.adminTodayImportLoaded) void refreshAdminTodayImportRuns({ render: true });
}

function actionHistoryLabel(action = "") {
  return String(action || "Change")
    .replace(/[_-]+/g, " ")
    .replace(/\b\w/g, (letter) => letter.toUpperCase());
}

function actionHistoryDateTime(value = "") {
  if (!value) return "Unknown time";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return String(value);
  return date.toLocaleString([], {
    month: "numeric",
    day: "numeric",
    year: "numeric",
    hour: "numeric",
    minute: "2-digit",
  });
}

function actionHistoryDetail(event = {}) {
  const payload = event.payload || {};
  if (Array.isArray(payload.changedFields) && payload.changedFields.length) {
    return `Changed ${payload.changedFields.map((field) => actionHistoryLabel(field)).join(", ")}`;
  }
  if (payload.sourceRackCode && payload.targetRackCode) {
    const scope = payload.deliveryDate ? ` for ${formatDisplayDate(payload.deliveryDate)}` : "";
    const pieces = Number(payload.pieceQty || 0);
    const quantity = pieces ? ` · ${pieces} piece${pieces === 1 ? "" : "s"}` : "";
    return `Rack ${payload.sourceRackCode} → ${payload.targetRackCode}${scope}${quantity}`;
  }
  if (payload.destinationOverrideMinutes) return `${payload.destinationOverrideMinutes}-minute override window`;
  if (payload.rackCode) return `Rack ${payload.rackCode}`;
  if (payload.targetRackCode) return `Destination rack ${payload.targetRackCode}`;
  if (event.reason) return event.reason;
  return `${actionHistoryLabel(event.entityType || "record")} ${event.entityId || ""}`.trim();
}

function actionHistoryDefaultFilters() {
  return { query: "", user: "", action: "", dateFrom: "", dateTo: "" };
}

function actionHistoryLocalDateKey(value = "") {
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function actionHistoryScope(scope, context = "") {
  let entry = actionHistoryUi.scopes.get(scope);
  if (!entry) {
    entry = {
      context: "",
      rackCode: "",
      events: [],
      filters: actionHistoryDefaultFilters(),
      page: 1,
      pageSize: 50,
      totalCount: 0,
      totalPages: 1,
      users: [],
      actions: [],
      refs: null,
      toolbar: null,
      loading: false,
      requestId: 0,
      filterTimer: null,
    };
    actionHistoryUi.scopes.set(scope, entry);
  }
  if (entry.context !== context) {
    entry.context = context;
    entry.rackCode = "";
    entry.events = [];
    entry.filters = actionHistoryDefaultFilters();
    entry.page = 1;
    entry.totalCount = 0;
    entry.totalPages = 1;
    entry.users = [];
    entry.actions = [];
  }
  return entry;
}

function actionHistoryFiltersActive(filters = {}) {
  return Boolean(filters.query || filters.user || filters.action || filters.dateFrom || filters.dateTo);
}

function actionHistoryToolbarMarkup(entry) {
  const filters = entry.filters;
  const users = Array.isArray(entry.users) ? entry.users : [];
  const actions = Array.isArray(entry.actions) ? entry.actions : [];
  const page = Math.max(Number(entry.page || 1), 1);
  const totalPages = Math.max(Number(entry.totalPages || 1), 1);
  return `
    <div class="modal-action-history-filter-grid">
      <label class="modal-action-history-filter-search">
        <span>Search log</span>
        <input type="search" autocomplete="off" data-action-history-filter="query" value="${escapeHtml(filters.query)}" placeholder="Search actions, users, or details...">
      </label>
      <label>
        <span>User</span>
        <select data-action-history-filter="user">
          <option value="">All users</option>
          ${users.map((value) => `<option value="${escapeHtml(value)}" ${filters.user === value ? "selected" : ""}>${escapeHtml(value)}</option>`).join("")}
        </select>
      </label>
      <label>
        <span>Action</span>
        <select data-action-history-filter="action">
          <option value="">All actions</option>
          ${actions.map((value) => `<option value="${escapeHtml(value)}" ${filters.action === value ? "selected" : ""}>${escapeHtml(actionHistoryLabel(value))}</option>`).join("")}
        </select>
      </label>
      <label>
        <span>From date</span>
        <input type="date" data-action-history-filter="dateFrom" value="${escapeHtml(filters.dateFrom)}">
      </label>
      <label>
        <span>Through date</span>
        <input type="date" data-action-history-filter="dateTo" value="${escapeHtml(filters.dateTo)}">
      </label>
    </div>
    <div class="modal-action-history-filter-footer">
      <span data-action-history-filter-result></span>
      <div class="modal-action-history-pager" aria-label="Action history pages">
        <button type="button" class="secondary" data-action-history-page="${page - 1}" ${page <= 1 || entry.loading ? "disabled" : ""}>Previous</button>
        <strong>Page ${page} of ${totalPages}</strong>
        <button type="button" class="secondary" data-action-history-page="${page + 1}" ${page >= totalPages || entry.loading ? "disabled" : ""}>Next</button>
      </div>
      <button type="button" class="secondary" data-action-history-clear ${actionHistoryFiltersActive(filters) ? "" : "disabled"}>Clear filters</button>
    </div>`;
}

function ensureActionHistoryToolbar(scope, entry) {
  const list = entry.refs?.list;
  if (!list) return null;
  let toolbar = list.parentElement?.querySelector(`.modal-action-history-filters[data-action-history-scope="${CSS.escape(scope)}"]`);
  if (!toolbar) {
    toolbar = document.createElement("section");
    toolbar.className = "modal-action-history-filters";
    toolbar.dataset.actionHistoryScope = scope;
    toolbar.setAttribute("aria-label", "Action history filters");
    toolbar.addEventListener("input", (event) => {
      const control = event.target.closest?.("[data-action-history-filter]");
      if (!control) return;
      const current = actionHistoryUi.scopes.get(scope);
      if (!current) return;
      current.filters[control.dataset.actionHistoryFilter] = control.value;
      current.page = 1;
      if (control.dataset.actionHistoryFilter === "query") {
        window.clearTimeout(current.filterTimer);
        current.filterTimer = window.setTimeout(() => {
          loadActionHistoryScope(scope).catch((error) => showInlineError(error.message, true));
        }, 260);
      }
    });
    toolbar.addEventListener("change", (event) => {
      const control = event.target.closest?.("[data-action-history-filter]");
      if (!control) return;
      const current = actionHistoryUi.scopes.get(scope);
      if (!current) return;
      current.filters[control.dataset.actionHistoryFilter] = control.value;
      current.page = 1;
      loadActionHistoryScope(scope).catch((error) => showInlineError(error.message, true));
    });
    toolbar.addEventListener("click", (event) => {
      const current = actionHistoryUi.scopes.get(scope);
      if (!current) return;
      const clear = event.target.closest?.("[data-action-history-clear]");
      if (clear) {
        current.filters = actionHistoryDefaultFilters();
        current.page = 1;
        loadActionHistoryScope(scope).catch((error) => showInlineError(error.message, true));
        return;
      }
      const pageButton = event.target.closest?.("[data-action-history-page]");
      if (!pageButton || pageButton.disabled) return;
      current.page = Math.max(Number(pageButton.dataset.actionHistoryPage || 1), 1);
      loadActionHistoryScope(scope).catch((error) => showInlineError(error.message, true));
    });
    list.before(toolbar);
  }
  entry.toolbar = toolbar;
  return toolbar;
}

function actionHistoryRowsMarkup(rows = [], hasEvents = false, loading = false) {
  if (loading) {
    return `<div class="admin-empty loading">Loading action history...</div>`;
  }
  if (!rows.length) {
    return `<div class="admin-empty">${hasEvents ? "No action-history events match the selected filters." : "No action history has been recorded for this GUI yet."}</div>`;
  }
  return rows.map((event) => {
    const tags = [
      event.entityType ? `<b>${escapeHtml(String(event.entityType).replaceAll("_", " "))}</b>` : "",
      event.station ? `<i>${escapeHtml(event.station)}</i>` : "",
    ].filter(Boolean).join("");
    return `
      <article class="modal-action-history-row rack-history-event-row">
        <span class="modal-action-history-icon" aria-hidden="true"></span>
        <div class="rack-history-event-copy">
          <strong>${escapeHtml(actionHistoryLabel(event.action))}</strong>
          <span>${escapeHtml(actionHistoryDetail(event))}</span>
          ${tags ? `<div class="rack-history-event-tags">${tags}</div>` : ""}
        </div>
        <div class="rack-history-event-meta">
          <time datetime="${escapeHtml(event.createdAt || "")}">${escapeHtml(actionHistoryDateTime(event.createdAt))}</time>
          <small>${escapeHtml(event.user || "system")}</small>
        </div>
      </article>`;
  }).join("");
}

function renderActionHistoryScopeRows(scope) {
  const entry = actionHistoryUi.scopes.get(scope);
  if (!entry?.refs) return;
  const { summary, count, list } = entry.refs;
  const total = Number(entry.totalCount || 0);
  const pageStart = total ? ((Number(entry.page || 1) - 1) * Number(entry.pageSize || 50)) + 1 : 0;
  const pageEnd = total ? Math.min(pageStart + entry.events.length - 1, total) : 0;
  count.textContent = String(total);
  summary.textContent = entry.events.length
    ? `Last change ${actionHistoryDateTime(entry.events[0].createdAt)} by ${entry.events[0].user || "system"}`
    : (entry.loading ? "Loading recorded changes..." : "No recorded changes for this workspace yet");
  list.innerHTML = actionHistoryRowsMarkup(entry.events, total > 0, entry.loading);
  if (entry.toolbar) {
    const result = entry.toolbar.querySelector("[data-action-history-filter-result]");
    const clear = entry.toolbar.querySelector("[data-action-history-clear]");
    if (result) result.textContent = total ? `${pageStart}-${pageEnd} of ${total} events` : "0 events";
    if (clear) clear.disabled = !actionHistoryFiltersActive(entry.filters) || entry.loading;
  }
  applyLanguageToRoot(entry.refs.root || list.parentElement);
}

function renderActionHistoryScope(scope) {
  const entry = actionHistoryUi.scopes.get(scope);
  if (!entry?.refs) return;
  const toolbar = ensureActionHistoryToolbar(scope, entry);
  if (toolbar) toolbar.innerHTML = actionHistoryToolbarMarkup(entry);
  renderActionHistoryScopeRows(scope);
}

function setActionHistoryScope(scope, context, payload, refs, rackCode = "") {
  const entry = actionHistoryScope(scope, context);
  const data = Array.isArray(payload) ? { events: payload, totalCount: payload.length } : (payload || {});
  entry.rackCode = rackCode || entry.rackCode || "";
  entry.events = Array.isArray(data.events) ? data.events : [];
  entry.page = Math.max(Number(data.page || entry.page || 1), 1);
  entry.pageSize = Math.min(Math.max(Number(data.pageSize || entry.pageSize || 50), 1), 50);
  entry.totalCount = Math.max(Number(data.totalCount ?? entry.events.length), 0);
  entry.totalPages = Math.max(Number(data.totalPages || Math.ceil(entry.totalCount / entry.pageSize) || 1), 1);
  entry.users = Array.isArray(data.users) ? data.users : entry.users;
  entry.actions = Array.isArray(data.actions) ? data.actions : entry.actions;
  entry.refs = refs;
  entry.loading = false;
  renderActionHistoryScope(scope);
  return entry.totalCount;
}

async function loadActionHistoryScope(scope) {
  const entry = actionHistoryUi.scopes.get(scope);
  if (!state.backend || !entry?.context) return;
  const requestId = ++entry.requestId;
  entry.loading = true;
  renderActionHistoryScope(scope);
  const params = new URLSearchParams({
    context: entry.context,
    page: String(entry.page || 1),
    pageSize: String(Math.min(Number(entry.pageSize || 50), 50)),
  });
  if (entry.rackCode) params.set("rackCode", entry.rackCode);
  for (const [key, value] of Object.entries(entry.filters || {})) {
    if (String(value || "").trim()) params.set(key, String(value));
  }
  try {
    const payload = await fetchJson(`/api/admin/action-history?${params.toString()}`);
    if (requestId !== entry.requestId) return;
    setActionHistoryScope(scope, entry.context, payload, entry.refs, entry.rackCode);
  } catch (error) {
    if (requestId !== entry.requestId) return;
    entry.loading = false;
    renderActionHistoryScope(scope);
    throw error;
  }
}

function renderModalActionHistory(payload = [], target = "admin", context = "", rackCode = "") {
  const isOperations = target === "operations";
  const details = isOperations ? els.operationsModalHistory : els.adminModalHistory;
  const summary = isOperations ? els.operationsModalHistorySummary : els.adminModalHistorySummary;
  const count = isOperations ? els.operationsModalHistoryCount : els.adminModalHistoryCount;
  const list = isOperations ? els.operationsModalHistoryList : els.adminModalHistoryList;
  if (!details || !summary || !count || !list) return;
  const resolvedContext = context || (isOperations ? state.operationsModalKind : els.adminModal?.dataset.kind || "");
  const total = setActionHistoryScope(target, resolvedContext, payload, { root: details, summary, count, list }, rackCode);
  if (isOperations && state.operationsModalKind === "reject-log") {
    const rejectTabCount = document.getElementById("rejectOperationsHistoryCount");
    if (rejectTabCount) rejectTabCount.textContent = String(total);
  }
  if (isOperations && state.operationsModalKind === "rack-details" && els.operationsRackHistoryCount) {
    els.operationsRackHistoryCount.textContent = String(total);
  }
}

async function loadModalActionHistory(context, target = "admin") {
  if (!state.backend || !context) return;
  const rackCode = context === "rack-details" ? String(state.selectedRackOverviewCode || "").trim() : "";
  const isOperations = target === "operations";
  const details = isOperations ? els.operationsModalHistory : els.adminModalHistory;
  const summary = isOperations ? els.operationsModalHistorySummary : els.adminModalHistorySummary;
  const count = isOperations ? els.operationsModalHistoryCount : els.adminModalHistoryCount;
  const list = isOperations ? els.operationsModalHistoryList : els.adminModalHistoryList;
  if (!details || !summary || !count || !list) return;
  const entry = actionHistoryScope(target, context);
  if (entry.rackCode !== rackCode) {
    entry.rackCode = rackCode;
    entry.events = [];
    entry.page = 1;
    entry.totalCount = 0;
    entry.totalPages = 1;
    entry.users = [];
    entry.actions = [];
  }
  entry.refs = { root: details, summary, count, list };
  entry.page = Math.max(Number(entry.page || 1), 1);
  await loadActionHistoryScope(target);
  const total = entry.totalCount;
  if (isOperations && state.operationsModalKind === "reject-log") {
    const rejectTabCount = document.getElementById("rejectOperationsHistoryCount");
    if (rejectTabCount) rejectTabCount.textContent = String(total);
  }
  if (isOperations && state.operationsModalKind === "rack-details" && els.operationsRackHistoryCount) {
    els.operationsRackHistoryCount.textContent = String(total);
  }
}

async function refreshOpenModalActionHistory() {
  if (els.adminModal && !els.adminModal.hidden && els.adminModal.dataset.kind) {
    await loadModalActionHistory(els.adminModal.dataset.kind, "admin");
  }
  if (els.operationsModal && !els.operationsModal.hidden && els.operationsModal.dataset.kind) {
    await loadModalActionHistory(els.operationsModal.dataset.kind, "operations");
  }
}


const BAY_MODAL_HISTORY_CONFIG = Object.freeze({
  stale: { context: "oldBays", scope: "bay-stale", countId: "staleBayHistoryCount", summaryId: "staleBayHistorySummary", listId: "staleBayHistoryList" },
  rush: { context: "rush", scope: "bay-rush", countId: "sdiHistoryCount", summaryId: "sdiHistorySummary", listId: "sdiHistoryList" },
  manage: { context: "manageBayItems", scope: "bay-manage", countId: "manageItemsHistoryCount", summaryId: "manageItemsHistorySummary", listId: "manageItemsHistoryList" },
  editor: { context: "editBays", scope: "bay-editor", countId: "bayEditorHistoryCount", summaryId: "bayEditorHistorySummary", listId: "bayEditorHistoryList" },
});

function renderBayModalActionHistory(kind, payload = []) {
  const config = BAY_MODAL_HISTORY_CONFIG[kind];
  if (!config) return;
  const count = document.getElementById(config.countId);
  const summary = document.getElementById(config.summaryId);
  const list = document.getElementById(config.listId);
  if (!count || !summary || !list) return;
  const root = list.closest(".bay-operation-history") || list.parentElement;
  setActionHistoryScope(config.scope, config.context, payload, { root, summary, count, list });
}

async function loadBayModalActionHistory(kind) {
  const config = BAY_MODAL_HISTORY_CONFIG[kind];
  if (!state.backend || !config) return;
  const count = document.getElementById(config.countId);
  const summary = document.getElementById(config.summaryId);
  const list = document.getElementById(config.listId);
  if (!count || !summary || !list) return;
  const root = list.closest(".bay-operation-history") || list.parentElement;
  const entry = actionHistoryScope(config.scope, config.context);
  entry.refs = { root, summary, count, list };
  try {
    await loadActionHistoryScope(config.scope);
  } catch (error) {
    list.innerHTML = `<div class="admin-empty review">Action history could not be loaded. ${escapeHtml(error.message)}</div>`;
  }
}

function setBayModalSection(kind, section = "workspace") {
  const firstView = document.querySelector(`[data-bay-modal-panel="${CSS.escape(kind)}"]`);
  const modal = firstView?.closest(".modal-panel");
  if (!modal) return;
  modal.querySelectorAll(`[data-bay-modal="${CSS.escape(kind)}"]`).forEach((button) => {
    const active = button.dataset.bayModalSection === section;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-selected", String(active));
  });
  modal.querySelectorAll(`[data-bay-modal-panel="${CSS.escape(kind)}"]`).forEach((view) => {
    view.hidden = view.dataset.bayModalView !== section;
  });
  if (kind === "rush" && section === "current") renderSdiCurrentList();
  if (section === "history") void loadBayModalActionHistory(kind);
}

function renderSupersededReviewCount() {
  if (!els.supersededOrderReviewCount) return;
  const count = Number(state.supersededReviewSummary?.pendingSupersededOrderReviews || 0);
  els.supersededOrderReviewCount.textContent = String(count);
  els.supersededOrderReviewCount.hidden = count <= 0;
  els.supersededOrderReviewCount.closest("button")?.classList.toggle("has-pending-review", count > 0);
}

async function refreshSupersededReviewSummary() {
  if (!state.backend || !hasAnyPermission(["view_admin", "edit_delivery_lists"])) return;
  try {
    const summary = await fetchJson("/api/admin/superseded-order-reviews/summary");
    state.supersededReviewSummary = {
      pendingSupersededOrderReviews: Number(summary.pendingSupersededOrderReviews || 0),
      approvedSupersededOrderReviews: Number(summary.approvedSupersededOrderReviews || 0),
      keptSupersededOrderReviews: Number(summary.keptSupersededOrderReviews || 0),
    };
    renderSupersededReviewCount();
  } catch {
    // Keep the previous count visible; the next import/admin refresh retries.
  }
}

function supersededReviewStatusLabel(status = "") {
  return ({ pending: "Needs review", review_later: "Review later", approved: "Removal approved", keep_both: "Keep both" })[status] || "Needs review";
}

function supersededReviewItemRows(items = []) {
  if (!items.length) return `<tr><td colspan="6">No item evidence was returned.</td></tr>`;
  return items.map((item) => {
    const batches = [item.productionBatch1, item.productionBatch2, item.productionBatch3].map((value) => Number(value || 0)).join("/");
    const dimensions = item.dimensions || `${Number(item.widthUnits || 0)} × ${Number(item.heightUnits || 0)} source units`;
    return `<tr>
      <td>${escapeHtml(item.itemNumber || "")}</td>
      <td>${escapeHtml(item.product || item.job || "")}</td>
      <td>${escapeHtml(dimensions)}</td>
      <td>${escapeHtml(item.quantity ?? 0)}</td>
      <td>${escapeHtml(`${item.orderStatus ?? 0}/${item.itemStatus ?? 0}`)}</td>
      <td>${escapeHtml(batches)}</td>
    </tr>`;
  }).join("");
}

function supersededOrderReviewCardHtml(review = {}) {
  const originalImpact = review.originalImpact || review.liveImpact || {};
  const replacementImpact = review.replacementImpact || {};
  const evidence = review.evidence || {};
  const status = String(review.status || "pending");
  const suggestedOrder = String(review.originalOrderNumber || "");
  const approvedRemoveOrder = String(review.approvedRemoveOrderNumber || "");
  const selectedRemoveOrder = approvedRemoveOrder || suggestedOrder;
  const decisionCopy = review.decidedAt
    ? `<small>Decision: ${escapeHtml(supersededReviewStatusLabel(status))}${approvedRemoveOrder ? ` · removed order ${escapeHtml(approvedRemoveOrder)}` : ""} by ${escapeHtml(review.decidedBy || "unknown")} · ${escapeHtml(formatDisplayDate(review.decidedAt))}</small>`
    : `<small>Detected ${escapeHtml(formatDisplayDate(review.lastSeenAt || review.detectedAt || ""))}</small>`;
  const impactMarkup = (label, orderNumber, impact) => `<span class="superseded-review-impact-option-v257">
    <small>${escapeHtml(label)}</small>
    <strong>Order ${escapeHtml(orderNumber)}</strong>
    <em>${Number(impact.activeLineCount || 0)} rows · ${Number(impact.pieceQty || 0)} pcs · ${Number(impact.scannedQty || 0)} scanned</em>
  </span>`;
  return `<article class="superseded-review-card status-${escapeHtml(status)}" data-superseded-review-id="${escapeHtml(review.id)}">
    <header class="superseded-review-card-header">
      <div>
        <span class="superseded-review-eyebrow">${escapeHtml(formatDisplayDate(review.deliveryDate))} · A+W identity ${escapeHtml(review.headerIdentity || "not available")}</span>
        <strong>Order ${escapeHtml(review.originalOrderNumber)} ↔ ${escapeHtml(review.replacementOrderNumber)}</strong>
        ${decisionCopy}
      </div>
      <span class="superseded-review-status">${escapeHtml(supersededReviewStatusLabel(status))}</span>
    </header>
    <div class="superseded-review-evidence">
      <span>Same A+W identity</span>
      <span>${Number(evidence.exactItemOverlapCount || 0)} exact item match${Number(evidence.exactItemOverlapCount || 0) === 1 ? "" : "es"}</span>
      <span>Suggested removal: order ${escapeHtml(suggestedOrder)}</span>
      <span>Suggestion only — Admin chooses which order is removed</span>
    </div>
    <div class="superseded-review-impact ${Number(originalImpact.scannedQty || 0) + Number(replacementImpact.scannedQty || 0) > 0 ? "has-scans" : ""}">
      <strong>Current scanner impact</strong>
      <div class="superseded-review-impact-grid-v257">
        ${impactMarkup("Original candidate", review.originalOrderNumber, originalImpact)}
        ${impactMarkup("Replacement candidate", review.replacementOrderNumber, replacementImpact)}
      </div>
    </div>
    <div class="superseded-review-compare">
      <section>
        <h3>Original candidate · ${escapeHtml(review.originalOrderNumber)}</h3>
        <table><thead><tr><th>Item</th><th>Product / Job</th><th>Dimensions</th><th>Qty</th><th>Status</th><th>Batches</th></tr></thead><tbody>${supersededReviewItemRows(review.originalItems)}</tbody></table>
      </section>
      <section>
        <h3>Replacement candidate · ${escapeHtml(review.replacementOrderNumber)}</h3>
        <table><thead><tr><th>Item</th><th>Product / Job</th><th>Dimensions</th><th>Qty</th><th>Status</th><th>Batches</th></tr></thead><tbody>${supersededReviewItemRows(review.replacementItems)}</tbody></table>
      </section>
    </div>
    <div class="superseded-review-removal-choice-v257" role="radiogroup" aria-label="Choose which candidate order to remove">
      <div><strong>Choose the order to remove</strong><small>The first choice is suggested from the A+W evidence, but either candidate may be retained.</small></div>
      <label class="${selectedRemoveOrder === String(review.originalOrderNumber) ? "is-selected" : ""}">
        <input type="radio" name="superseded-remove-${escapeHtml(review.id)}" value="${escapeHtml(review.originalOrderNumber)}" ${selectedRemoveOrder === String(review.originalOrderNumber) ? "checked" : ""}>
        <span><strong>Remove order ${escapeHtml(review.originalOrderNumber)}</strong><small>Suggested · keep ${escapeHtml(review.replacementOrderNumber)}</small></span>
      </label>
      <label class="${selectedRemoveOrder === String(review.replacementOrderNumber) ? "is-selected" : ""}">
        <input type="radio" name="superseded-remove-${escapeHtml(review.id)}" value="${escapeHtml(review.replacementOrderNumber)}" ${selectedRemoveOrder === String(review.replacementOrderNumber) ? "checked" : ""}>
        <span><strong>Remove order ${escapeHtml(review.replacementOrderNumber)}</strong><small>Keep ${escapeHtml(review.originalOrderNumber)}</small></span>
      </label>
    </div>
    ${review.decisionReason ? `<p class="superseded-review-reason"><strong>Decision note:</strong> ${escapeHtml(review.decisionReason)}</p>` : ""}
    <footer class="superseded-review-actions">
      <button type="button" class="danger" data-superseded-decision="approve" data-review-id="${escapeHtml(review.id)}">Approve selected removal</button>
      <button type="button" class="secondary" data-superseded-decision="keep_both" data-review-id="${escapeHtml(review.id)}">Keep both</button>
      <button type="button" class="secondary" data-superseded-decision="review_later" data-review-id="${escapeHtml(review.id)}">Review later</button>
    </footer>
  </article>`;
}

function supersededOrderReviewModalHtml() {
  const filter = state.supersededReviewFilter || "open";
  const reviews = (state.supersededOrderReviews || []).filter((review) => {
    if (filter === "open") return ["pending", "review_later"].includes(review.status);
    if (filter === "all") return true;
    return review.status === filter;
  });
  const summary = state.supersededReviewSummary || {};
  return `<div class="superseded-review-shell">
    <section class="superseded-review-hero">
      <div><span>Safe local reconciliation</span><strong>Production status creates a review candidate—it never deletes a row.</strong><p>Approval stores exact delivery-date/order/item keys. Keep Both prevents the same unchanged pair from returning.</p></div>
      <div class="superseded-review-kpis"><span><small>Needs review</small><strong>${Number(summary.pendingSupersededOrderReviews || 0)}</strong></span><span><small>Approved</small><strong>${Number(summary.approvedSupersededOrderReviews || 0)}</strong></span><span><small>Kept</small><strong>${Number(summary.keptSupersededOrderReviews || 0)}</strong></span></div>
    </section>
    <nav class="superseded-review-tabs" aria-label="Superseded-order review filters">
      ${[["open", "Needs review"], ["approved", "Approved"], ["keep_both", "Keep both"], ["all", "All"]].map(([value, label]) => `<button type="button" class="${filter === value ? "is-active" : ""}" data-superseded-filter="${value}">${label}</button>`).join("")}
    </nav>
    <div class="superseded-review-list">${reviews.length ? reviews.map(supersededOrderReviewCardHtml).join("") : `<div class="admin-empty success"><strong>No matching reviews.</strong><span>The next automatic SQL window will add candidates when A+W shows a likely replacement pair.</span></div>`}</div>
  </div>`;
}

async function loadSupersededOrderReviews() {
  const payload = await fetchJson("/api/admin/superseded-order-reviews");
  state.supersededOrderReviews = payload.reviews || [];
  state.supersededReviewSummary = {
    pendingSupersededOrderReviews: Number(payload.pendingSupersededOrderReviews || 0),
    approvedSupersededOrderReviews: Number(payload.approvedSupersededOrderReviews || 0),
    keptSupersededOrderReviews: Number(payload.keptSupersededOrderReviews || 0),
  };
  renderSupersededReviewCount();
  return payload;
}

async function decideSupersededOrderReview(reviewId, action) {
  const review = state.supersededOrderReviews.find((entry) => Number(entry.id) === Number(reviewId));
  if (!review) return;
  let removeOrderNumber = "";
  if (action === "approve") {
    const selected = els.adminModalBody?.querySelector(`input[name="superseded-remove-${CSS.escape(String(reviewId))}"]:checked`);
    removeOrderNumber = String(selected?.value || review.originalOrderNumber || "").trim();
    const validOrders = [String(review.originalOrderNumber || ""), String(review.replacementOrderNumber || "")];
    if (!validOrders.includes(removeOrderNumber)) throw new Error("Choose which candidate order should be removed.");
    const removeOriginal = removeOrderNumber === String(review.originalOrderNumber || "");
    const impact = removeOriginal ? (review.originalImpact || review.liveImpact || {}) : (review.replacementImpact || {});
    const keepOrderNumber = removeOriginal ? review.replacementOrderNumber : review.originalOrderNumber;
    const suggested = removeOriginal ? " This is the suggested removal." : " This overrides the suggested removal.";
    const confirmed = await confirmWebAppAction({
      title: `Remove A+W order ${removeOrderNumber}?`,
      message: `Only the exact item keys shown for order ${removeOrderNumber} on ${formatDisplayDate(review.deliveryDate)} will be removed and suppressed from future imports.${suggested}`,
      details: `${Number(impact.activeLineCount || 0)} active stage row(s), ${Number(impact.pieceQty || 0)} piece(s), ${Number(impact.scannedQty || 0)} already scanned. Order ${keepOrderNumber} will be retained.`,
      confirmLabel: `Remove Order ${removeOrderNumber}`,
      danger: true,
    });
    if (!confirmed) return;
  }
  await fetchJson("/api/admin/superseded-order-reviews/decision", {
    method: "POST",
    body: JSON.stringify({ reviewId: Number(reviewId), action, removeOrderNumber, ...requestContext() }),
  });
  await loadSupersededOrderReviews();
  if (els.adminModalBody && els.adminModal?.dataset.kind === "supersededOrders") {
    els.adminModalBody.innerHTML = supersededOrderReviewModalHtml();
    applyLanguageToRoot(els.adminModalBody);
  }
  await loadDeliveryLists(state.activeListId);
  state.adminTodayImportLoaded = false;
  await refreshAdminTodayImportRuns({ render: false });
  renderAdminDeliveryLists();
}

