/**
 * Purpose: Run the categorized permissions workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function categorizedPermissions(permissions = []) {
  const allPermissions = permissions || [];
  const assigned = new Set(PERMISSION_CATEGORIES.flatMap((category) => category.permissions));

  const categories = PERMISSION_CATEGORIES
    .map((category) => ({
      ...category,
      permissions: category.permissions.filter((permission) => allPermissions.includes(permission)),
    }))
    .filter((category) => category.permissions.length);

  const uncategorized = allPermissions.filter((permission) => !assigned.has(permission));

  if (uncategorized.length) {
    categories.push({
      title: "Other",
      description: "New or uncategorized permissions.",
      permissions: uncategorized,
    });
  }

  return categories;
}

/**
 * Purpose: Run the role permission category key workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function rolePermissionCategoryKey(roleName, categoryTitle) {
  return `${String(roleName || "").trim()}::${String(categoryTitle || "").trim()}`;
}

/**
 * Purpose: Run the reset role permission UI session workflow for the browser application.
 * Effects: May update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function resetRolePermissionUiSession() {
  state.rolePermissionOpenRoles = new Set();
  state.rolePermissionOpenCategories = new Set();
  state.rolePermissionScrollTop = 0;
}

/**
 * Purpose: Run the remember role permission UI state workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function rememberRolePermissionUiState() {
  const editor = document.querySelector(".role-permission-editor");

  if (els.adminModalBody?.contains(editor)) {
    state.rolePermissionScrollTop = els.adminModalBody.scrollTop || 0;
  }

  document.querySelectorAll(".role-permission-card[data-role-card]").forEach((details) => {
    const roleName = details.dataset.roleCard || "";

    if (details.open) {
      state.rolePermissionOpenRoles.add(roleName);
    } else {
      state.rolePermissionOpenRoles.delete(roleName);
    }
  });

  document.querySelectorAll(".permission-category[data-role-name][data-category-title]").forEach((details) => {
    const key = rolePermissionCategoryKey(details.dataset.roleName, details.dataset.categoryTitle);

    if (details.open) {
      state.rolePermissionOpenCategories.add(key);
    } else {
      state.rolePermissionOpenCategories.delete(key);
    }
  });
}

/**
 * Purpose: Run the restore role permission UI scroll workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function restoreRolePermissionUiScroll() {
  window.requestAnimationFrame(() => {
    if (els.adminModalBody) {
      els.adminModalBody.scrollTop = state.rolePermissionScrollTop || 0;
    }
  });
}

/**
 * Purpose: Run the role permission category HTML workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function rolePermissionCategoryHtml(roleName, category, selected) {
  const checkedCount = category.permissions.filter((permission) => selected.has(permission)).length;
  const categoryKey = rolePermissionCategoryKey(roleName, category.title);
  const open = state.rolePermissionOpenCategories.has(categoryKey);

  return `
    <details
      class="permission-category"
      data-role-name="${escapeHtml(roleName)}"
      data-category-title="${escapeHtml(category.title)}"
      ${open ? "open" : ""}
    >
      <summary>
        <span>
          <strong>${escapeHtml(category.title)}</strong>
          <small>${escapeHtml(category.description)}</small>
        </span>
        <b>${escapeHtml(checkedCount)} / ${escapeHtml(category.permissions.length)}</b>
      </summary>

      <div class="role-permission-grid">
        ${category.permissions
          .map(
            (permission) => `
              <label class="${selected.has(permission) ? "is-checked" : ""}">
                <input type="checkbox" value="${escapeHtml(permission)}" ${selected.has(permission) ? "checked" : ""}>
                <span class="permission-option-copy">
                  <strong>${escapeHtml(permissionLabel(permission))}</strong>
                  <small>${escapeHtml(permissionDescription(permission))}</small>
                </span>
              </label>
            `,
          )
          .join("")}
      </div>
    </details>
  `;
}

/**
 * Purpose: Run the role permission count text workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function rolePermissionCountText(role, permissions) {
  const selectedCount = Array.isArray(role.permissions) ? role.permissions.length : 0;
  const totalCount = Array.isArray(permissions) ? permissions.length : 0;

  return `${selectedCount} of ${totalCount} permissions`;
}

/**
 * Purpose: Run the role permissions modal HTML workflow for the browser application.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function roleCreatePermissionCategoryHtml(category) {
  return `
    <section class="permission-category role-create-permission-category is-static" data-role-create-category="${escapeHtml(category.title)}">
      <header>
        <span><strong>${escapeHtml(category.title)}</strong><small>${escapeHtml(category.description)}</small></span>
        <b data-permission-category-count>0 / ${escapeHtml(category.permissions.length)}</b>
      </header>
      <div class="role-permission-grid">
        ${category.permissions.map((permission) => `
          <label>
            <input type="checkbox" value="${escapeHtml(permission)}">
            <span class="permission-option-copy">
              <strong>${escapeHtml(permissionLabel(permission))}</strong>
              <small>${escapeHtml(permissionDescription(permission))}</small>
            </span>
          </label>`).join("")}
      </div>
    </section>`;
}

function rolePermissionsModalHtml() {
  const roles = state.adminRoles || [];
  const permissions = state.allPermissions || [];

  if (!roles.length || !permissions.length) {
    return `<div class="admin-empty">Role permissions are loading. Close and reopen this panel if they do not appear.</div>`;
  }

  const categories = categorizedPermissions(permissions);
  const assignedPermissionCount = new Set(roles.flatMap((role) => role.permissions || [])).size;

  return `
    <div class="role-permission-editor role-manager-v142">
      <section class="role-manager-overview">
        <div>
          <span class="role-manager-eyebrow">Access control</span>
          <strong>Roles &amp; Permissions</strong>
          <p>Create purpose-built roles, then open any role to fine-tune exactly what its users can and cannot do.</p>
        </div>
        <div class="role-manager-overview-stats">
          <span><b>${escapeHtml(roles.length)}</b><small>Roles</small></span>
          <span><b>${escapeHtml(permissions.length)}</b><small>Available permissions</small></span>
          <span><b>${escapeHtml(assignedPermissionCount)}</b><small>Permissions in use</small></span>
        </div>
      </section>

      <section class="role-create-card is-open">
        <header class="role-create-heading">
          <span class="role-create-summary-icon" aria-hidden="true"></span>
          <span><strong>Create a new role</strong><small>Name the role, describe its purpose, and choose only the permissions it needs.</small></span>
        </header>
        <form id="createRoleForm" class="role-create-form">
          <div class="role-create-fields">
            <label><span>Role name *</span><input id="newRoleName" name="name" type="text" maxlength="60" autocomplete="off" placeholder="Example: Shipping Lead" required></label>
            <label><span>Description</span><input id="newRoleDescription" name="description" type="text" maxlength="240" autocomplete="off" placeholder="What this role is responsible for"></label>
          </div>
          <div class="role-create-permission-toolbar">
            <div><strong>Starting permissions</strong><span>Unchecked permissions will not be granted.</span></div>
            <div>
              <button type="button" class="secondary" data-role-create-selection="all">Select all</button>
              <button type="button" class="secondary" data-role-create-selection="none">Clear all</button>
            </div>
          </div>
          <div class="role-create-permission-list">
            ${categories.map(roleCreatePermissionCategoryHtml).join("")}
          </div>
          <footer class="role-create-footer">
            <span id="createRoleStatus">A role may be created with no permissions and configured later.</span>
            <button type="submit" class="primary">Create Role</button>
          </footer>
        </form>
      </section>

      <section class="role-library">
        <header><div><strong>Existing roles</strong><span>Open a role, change permission selections, then save that role.</span></div><b>${escapeHtml(roles.length)} total</b></header>
        <div class="role-library-list">
          ${roles.map((role) => {
            const selected = new Set(role.permissions || []);
            const roleOpen = state.rolePermissionOpenRoles.has(role.name);
            return `
              <details class="role-permission-card" data-role-card="${escapeHtml(role.name)}" ${roleOpen ? "open" : ""}>
                <summary class="role-permission-summary">
                  <span class="role-collapse-icon" aria-hidden="true"></span>
                  <span class="role-permission-title">
                    <strong>${escapeHtml(role.name)}</strong>
                    <small>${escapeHtml(role.description || permissionSummaryFromPermissions(role.permissions || []))}</small>
                  </span>
                  <span class="role-permission-count">${escapeHtml(rolePermissionCountText(role, permissions))}</span>
                  <button type="button" class="role-permission-save" data-save-role-permissions="${escapeHtml(role.name)}" title="Save ${escapeHtml(role.name)} permissions">Save</button>
                </summary>
                <div class="role-permission-body">
                  ${categories.map((category) => rolePermissionCategoryHtml(role.name, category, selected)).join("")}
                </div>
              </details>`;
          }).join("")}
        </div>
      </section>
    </div>`;
}

function wireRolePermissionControls(root = els.adminModalBody) {
  if (!root) return;
  root.querySelectorAll(".permission-category").forEach((category) => {
    if (category.dataset.permissionWired === "true") return;
    category.dataset.permissionWired = "true";
    const summary = category.matches("details") ? category.querySelector(":scope > summary") : null;
    summary?.addEventListener("click", (event) => {
      if (event.target.closest("button, input, label")) return;
      event.preventDefault();
      category.open = !category.open;
    });
    const updateCount = () => {
      const inputs = [...category.querySelectorAll('input[type="checkbox"]')];
      const count = inputs.filter((item) => item.checked).length;
      const badge = category.querySelector("[data-permission-category-count]") || summary?.querySelector("b");
      if (badge) badge.textContent = `${count} / ${inputs.length}`;
    };
    category.querySelectorAll('input[type="checkbox"]').forEach((input) => {
      input.addEventListener("change", () => {
        input.closest("label")?.classList.toggle("is-checked", input.checked);
        updateCount();
      });
    });
    updateCount();
  });
}

async function createRoleFromForm(form) {
  const data = new FormData(form);
  const name = String(data.get("name") || "").trim();
  const description = String(data.get("description") || "").trim();
  const permissions = [...form.querySelectorAll('.role-create-permission-list input[type="checkbox"]:checked')]
    .map((input) => input.value)
    .filter(Boolean);
  const status = form.querySelector("#createRoleStatus");
  const submit = form.querySelector('button[type="submit"]');

  if (!name) {
    status.textContent = "Enter a role name.";
    form.querySelector("#newRoleName")?.focus();
    return;
  }

  if (!permissions.length) {
    const confirmed = await confirmWebAppAction({
      title: "Create role with no permissions?",
      message: `Create <strong>${escapeHtml(name)}</strong> without any permissions?`,
      details: "The role will exist, but users assigned to it will not be able to open application features until permissions are added.",
      confirmLabel: "Create Empty Role",
      danger: false,
    });
    if (!confirmed) return;
  }

  submit.disabled = true;
  status.textContent = "Creating role...";
  try {
    const payload = await fetchJson("/api/admin/roles", {
      method: "POST",
      body: JSON.stringify({ name, description, permissions }),
    });
    state.adminRoles = payload.roles || [];
    state.allPermissions = payload.permissions || state.allPermissions;
    state.rolePermissionOpenRoles.add(name);
    if (els.adminModalBody) {
      els.adminModalBody.innerHTML = adminModalContent("roles");
      wireRolePermissionControls();
    }
    await refreshAdminPage();
    showSaveConfirmation(`${name} was created and is ready to assign to users.`);
  } catch (error) {
    status.textContent = error.message;
    throw error;
  } finally {
    submit.disabled = false;
  }
}

function setCreateRolePermissionSelection(mode) {
  const form = document.getElementById("createRoleForm");
  if (!form) return;
  const checked = mode === "all";
  form.querySelectorAll('.role-create-permission-list input[type="checkbox"]').forEach((input) => {
    input.checked = checked;
    input.closest("label")?.classList.toggle("is-checked", checked);
  });
  form.querySelectorAll("[data-role-create-category]").forEach((category) => {
    const inputs = [...category.querySelectorAll('input[type="checkbox"]')];
    const badge = category.querySelector("[data-permission-category-count]");
    if (badge) badge.textContent = `${inputs.filter((input) => input.checked).length} / ${inputs.length}`;
  });
  const status = form.querySelector("#createRoleStatus");
  if (status) status.textContent = checked ? "All available permissions selected." : "All permissions cleared.";
}

/**
 * Purpose: Run the permission summary from permissions workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function permissionSummaryFromPermissions(permissions) {
  const list = permissions || [];
  if (list.includes("view_admin")) return "Administration access";
  if (list.includes("manage_users")) return "User and system management";
  if (list.includes("manage_racks") || list.includes("transfer_rack_contents")) return "Rack and transportation management";
  if (list.includes("view_bays")) return "Indian Trail and Bay Map access";
  if (list.includes("scan_delivery_lists") || list.includes("scan")) return "Scanning and delivery-list access";
  return "Custom access";
}

/**
 * Purpose: Run the permission summary for user workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function permissionSummaryForUser(user) {
  const directPermissions = Array.isArray(user?.permissions) ? user.permissions : [];

  if (directPermissions.length) {
    return permissionSummaryFromPermissions(directPermissions);
  }

  const rolePermissions = (state.adminRoles || [])
    .filter((role) => (user?.roles || []).includes(role.name))
    .flatMap((role) => role.permissions || []);

  if (rolePermissions.length) {
    return permissionSummaryFromPermissions(rolePermissions);
  }

  const roleText = (user?.roles || []).join(", ");
  return roleText ? `${roleText} access` : "Custom access";
}

/**
 * Purpose: Run the save role permissions workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function saveRolePermissions(roleName) {
  rememberRolePermissionUiState();

  const card = document.querySelector(`[data-role-card="${CSS.escape(roleName)}"]`);

  if (!card) return;

  const permissions = [...card.querySelectorAll("input[type='checkbox']:checked")].map((input) => input.value);

  if (!permissions.length) {
    const confirmed = await confirmWebAppAction({
      title: "Save role with no permissions?",
      message: `Save <strong>${escapeHtml(roleName)}</strong> with no permissions?`,
      details: "Users with this role will not be able to access application features.",
      confirmLabel: "Save Empty Role",
    });
    if (!confirmed) return;
  }

  const payload = await fetchJson("/api/admin/roles/permissions", {
    method: "POST",
    body: JSON.stringify({ role: roleName, permissions }),
  });

  state.adminRoles = payload.roles || [];
  state.allPermissions = payload.permissions || state.allPermissions;

  if (els.adminModalBody) {
    els.adminModalBody.innerHTML = adminModalContent("roles");
    wireRolePermissionControls();
    restoreRolePermissionUiScroll();
  }

  await refreshAdminPage();

  showSaveConfirmation(`${roleName} permissions were saved. Users with that role will sign in again to refresh access.`);
}

/**
 * Purpose: Run the manual edit delivery date for list workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditDeliveryDateForList(listId) {
  const selectedList = state.lists.find((item) => item.id === listId);

  return selectedList?.deliveryDate || state.lists[0]?.deliveryDate || "";
}

/**
 * Purpose: Run the manual edit stage lists for current delivery workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditStageListsForCurrentDelivery(selectedListId) {
  const deliveryDate = manualEditDeliveryDateForList(selectedListId);
  const stageLists = state.lists
    .filter((list) => list.deliveryDate === deliveryDate)
    .sort((a, b) => stageSort(a) - stageSort(b) || String(a.label || "").localeCompare(String(b.label || "")));

  return stageLists.length ? stageLists : state.lists.slice();
}

/**
 * Purpose: Run the manual edit stage summary workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditStageSummary(listId) {
  const list = state.lists.find((item) => item.id === listId) || state.lists[0] || {};

  if (!list.id) {
    return "No stage selected";
  }

  return `${formatDisplayDate(list.deliveryDate)} - ${list.stage || "Stage"} - ${list.scanner || ""}`;
}

/**
 * Purpose: Run the manual edit modal HTML workflow for the browser application.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditFilterIsActive(group, value) {
  if (group === "attention") return (state.manualEditFilters.attention || []).includes(value);
  if (group === "glassType") {
    const selected = state.manualEditFilters.glassTypes || [];
    return value === "all" ? selected.length === 0 : selected.includes(value);
  }
  return String(state.manualEditFilters[group] || "all") === value;
}

function manualEditActiveFilterCount() {
  return ["progress", "route", "location"].filter((key) => String(state.manualEditFilters[key] || "all") !== "all").length
    + (state.manualEditFilters.attention || []).length
    + (state.manualEditFilters.glassTypes || []).length;
}

function manualEditFilterButton(group, value, label) {
  return `<button type="button" class="tab ${manualEditFilterIsActive(group, value) ? "is-active" : ""}" data-manual-edit-filter-group="${escapeHtml(group)}" data-manual-edit-filter-value="${escapeHtml(value)}">${escapeHtml(label)}</button>`;
}

