/**
 * Purpose: Run the ensure manual edit lookups loaded workflow for the browser application.
 * Effects: May call the backend api, may update shared client state.
 * Flow: Requests current data, updates shared state, and invokes the existing renderer for affected controls.
 */
async function ensureManualEditLookupsLoaded() {
  if (!state.backend) return;

  const lookups = await Promise.allSettled([
    fetchJson("/api/racks"),
    fetchJson("/api/indian-trail/bays"),
    fetchJson("/api/admin/manual-edit-lookups"),
  ]);

  const rackResult = lookups[0];

  if (rackResult.status === "fulfilled") {
    state.racks = rackResult.value.racks || [];
    state.rackSummary = rackResult.value.summary || null;
  }

  const bayResult = lookups[1];

  if (bayResult.status === "fulfilled") {
    state.bays = bayResult.value.bays || [];
    state.bayEvents = bayResult.value.events || state.bayEvents || [];
  }

  const manualLookupResult = lookups[2];

  if (manualLookupResult.status === "fulfilled") {
    adoptManualEditLookups(manualLookupResult.value);
  }
}

/**
 * Purpose: Open the open manual edit for list workflow using the existing shared UI state.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function openManualEditForList(listId) {
  state.manualEditDirty = false;
  state.manualEditListId = listId || state.activeListId || state.lists[0]?.id || "";
  state.manualEditQuery = "";
  state.manualEditFilters = { progress: "all", route: "all", location: "all", attention: [], glassTypes: [] };
  state.manualEditResultRows = [];
  state.manualEditTotalRows = 0;
  state.manualEditVisibleCount = 20;
  state.manualEditGlassTypes = [];

  openAdminModal("manualEdit");

  await ensureManualEditLookupsLoaded();
  await runManualEditModalSearch(true);
}

/**
 * Purpose: Load the fetch manual edit results workflow using the existing shared UI state.
 * Effects: May call the backend api.
 * Flow: Requests current data, updates shared state, and invokes the existing renderer for affected controls.
 */
async function fetchManualEditBatch(query, listId, limit = 20, offset = 0, filters = state.manualEditFilters) {
  const params = new URLSearchParams();
  if (query) params.set("q", query);
  if (listId) params.set("listId", listId);
  params.set("limit", String(limit));
  params.set("offset", String(offset));
  if (filters?.progress && filters.progress !== "all") params.set("progress", filters.progress);
  if (filters?.route && filters.route !== "all") params.set("route", filters.route);
  if (filters?.location && filters.location !== "all") params.set("location", filters.location);
  if (Array.isArray(filters?.attention) && filters.attention.length) params.set("attention", filters.attention.join(","));
  for (const glassType of filters?.glassTypes || []) {
    if (String(glassType || "").trim()) params.append("glassType", String(glassType).trim());
  }
  const payload = await fetchJson(`/api/admin/line-items/search?${params.toString()}`);
  return {
    results: payload.results || [],
    total: Math.max(Number(payload.total || 0), (payload.results || []).length),
    filterOptions: payload.filterOptions || { glassTypes: [] },
  };
}

/** Retain the older array-returning helper for the compact Admin-page editor. */
async function fetchManualEditResults(query, listId) {
  return (await fetchManualEditBatch(query, listId, 100, 0)).results;
}

/**
 * Purpose: Run the run manual edit modal search workflow for the browser application.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function runManualEditModalSearch(loadAll = false) {
  const requestId = ++state.manualEditSearchRequestId;
  const stage = document.getElementById("manualEditModalStage")?.value || state.manualEditListId || "";
  const query = loadAll ? "" : (document.getElementById("manualEditModalSearch")?.value.trim() || "");

  if (loadAll) {
    const searchInput = document.getElementById("manualEditModalSearch");
    if (searchInput) searchInput.value = "";
    state.manualEditFilters = { progress: "all", route: "all", location: "all", attention: [], glassTypes: [] };
    refreshManualEditFilterDrawer(false);
  }

  state.manualEditListId = stage;
  state.manualEditQuery = query;

  const currentStageLabel = document.querySelector(".manual-edit-current-stage");
  if (currentStageLabel) {
    currentStageLabel.textContent = manualEditStageSummary(stage);
  }

  const target = document.getElementById("manualEditModalResults");

  if (target) {
    target.innerHTML = `
      <div class="manual-edit-loading">
        <div class="admin-empty loading">
          <strong>Loading editable rows...</strong>
          <span class="loading-bar"><i></i></span>
        </div>
      </div>
    `;
  }

  const resultPage = await fetchManualEditBatch(query, stage, 20, 0);
  if (requestId !== state.manualEditSearchRequestId) return;
  state.manualEditResultRows = resultPage.results;
  state.manualEditTotalRows = resultPage.total;
  state.manualEditVisibleCount = 20;
  state.manualEditGlassTypes = Array.isArray(resultPage.filterOptions?.glassTypes)
    ? resultPage.filterOptions.glassTypes
    : [];
  const availableGlassTypes = new Set(state.manualEditGlassTypes.map((option) => String(option.label || "")));
  state.manualEditFilters.glassTypes = (state.manualEditFilters.glassTypes || []).filter((label) => availableGlassTypes.has(label));
  refreshManualEditFilterDrawer(false);
  const html = manualEditResultsHtml(state.manualEditResultRows, state.manualEditVisibleCount, state.manualEditTotalRows);

  if (target) {
    target.innerHTML = html;
  }

  if (els.manualEditResults) {
    els.manualEditResults.innerHTML = html;
  }

  state.manualEditDirty = false;
}

/** Reveal the next batch of editable rows without another server request. */
async function loadMoreManualEditRows() {
  state.manualEditResultRows = state.manualEditResultRows.filter((item) => !item._manualEditFilterMismatch);
  const button = document.querySelector("[data-manual-edit-load-more]");
  if (button) {
    button.disabled = true;
    button.textContent = "Loading...";
  }
  const resultPage = await fetchManualEditBatch(
    state.manualEditQuery,
    state.manualEditListId,
    20,
    state.manualEditResultRows.length,
  );
  const knownIds = new Set(state.manualEditResultRows.map((item) => String(item.lineItemId || "")));
  state.manualEditResultRows.push(
    ...resultPage.results.filter((item) => !knownIds.has(String(item.lineItemId || ""))),
  );
  state.manualEditTotalRows = resultPage.total;
  state.manualEditVisibleCount = state.manualEditResultRows.length;
  const html = manualEditResultsHtml(state.manualEditResultRows, state.manualEditVisibleCount, state.manualEditTotalRows);
  const target = document.getElementById("manualEditModalResults");
  if (target) target.innerHTML = html;
}

/**
 * Purpose: Render the render manual edit stage options workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
 */
function renderManualEditStageOptions() {
  if (!els.manualEditStageSelect) return;
  const current = els.manualEditStageSelect.value;
  const options = [`<option value="">All stages</option>`].concat(
    state.lists
      .slice()
      .sort((a, b) => String(b.deliveryDate || "").localeCompare(String(a.deliveryDate || "")) || String(a.stage || "").localeCompare(String(b.stage || "")))
      .map((list) => `<option value="${escapeHtml(list.id)}">${escapeHtml(formatDisplayDate(list.deliveryDate))} - ${escapeHtml(list.stage)}${list.scanner ? ` (${escapeHtml(list.scanner)})` : ""}</option>`),
  );
  els.manualEditStageSelect.innerHTML = options.join("");
  els.manualEditStageSelect.value = state.lists.some((list) => list.id === current) ? current : "";
}

/**
 * Purpose: Render the render import history workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may call the backend api, may update shared client state.
 * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
 */
function renderImportHistory(imports) {
  state.adminRecentImports = imports || [];

  const activeImports = activeRecentImports(state.adminRecentImports);

  if (els.adminDeliveryLists) {
    els.adminDeliveryLists.innerHTML = renderAdminImportRunBrowser(activeImports);
  }

  if (!els.importHistory) return;

  els.importHistory.innerHTML = renderAdminImportRunBrowser(activeImports);
}

/**
 * Purpose: Run the import history rows workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function importHistoryRows(imports = []) {
  state.adminImportPreviewContexts.clear();
  // The selected run is already normalized and de-duplicated by run identity.
  // Do not collapse rows by delivery date here: one run can legitimately contain
  // multiple source results for the same date, and every result must remain visible.
  const rows = imports
    .slice()
    .sort((a, b) =>
      String(b.deliveryDate || "").localeCompare(String(a.deliveryDate || "")) ||
      String(b.importedAt || "").localeCompare(String(a.importedAt || "")) ||
      String(a.sourceName || a.fileName || "").localeCompare(String(b.sourceName || b.fileName || "")) ||
      String(a.stage || "").localeCompare(String(b.stage || "")),
    );

  if (!rows.length) {
    return `<div class="admin-empty">No import history yet. Imports from the temp folder or single files will appear here.</div>`;
  }

  /**
   * Purpose: Run the stage name for row workflow for the browser application.
   * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
   * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
   */
  const stageNameForRow = (row, list) =>
    String(row.stage || row.stageProfile || row.stageSheetName || list?.stage || list?.label || row.listId || "Updated stage");

  /**
   * Purpose: Run the is staging row workflow for the browser application.
   * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
   * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
   */
  const isStagingRow = (row, list) => /staging/i.test(stageNameForRow(row, list));

  /**
   * Purpose: Run the stage category for import row workflow for the browser application.
   * Effects: May call the backend api.
   * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
   */
  const stageCategoryForImportRow = (row, list) =>
    stageCategory({
      stage: stageNameForRow(row, list),
      scanner: row.stageProfile || row.scanner || list?.scanner || "",
    });

  /**
   * Purpose: Update the updated qty for row workflow using the existing shared UI state.
   * Effects: May call the backend api, may update shared client state.
   * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
   */
  const updatedQtyForRow = (row, list) => {
    // Delivery List Management describes the selected import event. Prefer the
    // post-import quantity saved with that event before falling back to the live
    // catalog. Using the live total first could display only a later route/delta
    // list and turn a valid 111 + 9 = 120 import into 111 + 9 = 9.
    const importedTotal = row.totalQty ?? row.updatedQty ?? row.newQty;
    if (importedTotal !== undefined && importedTotal !== null && importedTotal !== "") {
      return Number(importedTotal || 0);
    }
    const liveTotal = list?.totalQty;
    if (liveTotal !== undefined && liveTotal !== null && liveTotal !== "") {
      return Number(liveTotal || 0);
    }
    return 0;
  };

  /**
   * Purpose: Run the changed qty for row workflow for the browser application.
   * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
   * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
   */
  const quantityChangeForRow = (row, list) => {
    const updatedQty = updatedQtyForRow(row, list);
    const removed = Number(row.removedPieceQty ?? row.removedQty ?? 0);
    const changed = Number(row.changedPieceQty ?? row.changedQty ?? 0);
    const newPieces = Number(row.newPieceQty ?? 0);
    const added = Number(row.addedPieceQty ?? row.addedQty ?? 0);
    const explicitUpdated = Number(row.updatedPieceQty ?? row.updatedQtyChange ?? 0);
    const updated = row.created
      ? updatedQty
      : (newPieces + explicitUpdated) || added || Math.max(changed - removed, 0);
    return { positive: updated, updated, removed };
  };

  const changedQtyForRow = (row, list) => {
    const change = quantityChangeForRow(row, list);
    return change.positive + change.removed;
  };

  const netQuantityDeltaHtml = (delta) => {
    const value = Number(delta || 0);
    if (value > 0) return `<span class="qty-change is-added">+${escapeHtml(value)}</span>`;
    if (value < 0) return `<span class="qty-change is-removed">${escapeHtml(value)}</span>`;
    return `<span class="qty-change is-zero">0</span>`;
  };

  const quantityFlowChangesHtml = (addedQty, removedQty) => {
    const added = Math.max(Number(addedQty || 0), 0);
    const removed = Math.max(Number(removedQty || 0), 0);
    if (!added && !removed) return `<span class="qty-change is-zero">0</span>`;
    return `<span class="qty-change-set-v257">${added ? `<span class="qty-change is-added">+${escapeHtml(added)} pcs</span>` : ""}${removed ? `<span class="qty-change is-removed">-${escapeHtml(removed)} pcs</span>` : ""}</span>`;
  };

  const quantityChangeHtmlForRow = (row, list) => {
    const change = quantityChangeForRow(row, list);
    if (change.updated && change.removed) {
      return `<span class="qty-change is-mixed"><b>Updated ${escapeHtml(change.updated)} pcs</b><b>Removed ${escapeHtml(change.removed)} pcs</b></span>`;
    }
    if (change.removed) {
      return `<span class="qty-change is-removed">Removed ${escapeHtml(change.removed)} pcs</span>`;
    }
    if (change.updated) {
      return `<span class="qty-change">Updated ${escapeHtml(change.updated)} pcs</span>`;
    }
    return `<span class="qty-change is-zero">No changes</span>`;
  };

  /**
   * Purpose: Run the original qty for row workflow for the browser application.
   * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
   * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
   */
  const originalQtyForRow = (row, list) => {
    const updatedQty = updatedQtyForRow(row, list);
    const explicitAddedQty = Number(row.addedPieceQty ?? row.addedQty ?? 0);
    const explicitChangedQty = Number(row.changedPieceQty ?? row.changedQty ?? 0);
    const explicitRemovedQty = Number(row.removedPieceQty ?? row.removedQty ?? 0);
    const explicitOriginalQty = row.originalQty ?? row.originalPieceQty ?? row.previousQty ?? row.oldQty ?? row.beforeQty;

    if (row.created) return 0;

    if (explicitOriginalQty !== undefined && explicitOriginalQty !== null && explicitOriginalQty !== "") {
      const originalQty = Number(explicitOriginalQty || 0);

      // Older import-history records sometimes stored 0 even when an unchanged
      // stage already contained pieces. In that case, the current total is the
      // original quantity—not a newly-added quantity.
      if (originalQty <= 0 && updatedQty > 0 && !explicitAddedQty && !explicitChangedQty) {
        return updatedQty;
      }

      if (originalQty <= 0 && updatedQty > 0 && explicitAddedQty > 0) {
        return Math.max(updatedQty - explicitAddedQty, 0);
      }

      return originalQty;
    }

    return Math.max(updatedQty - explicitAddedQty + explicitRemovedQty, 0);
  };

  /**
   * Purpose: Run the is new stage row workflow for the browser application.
   * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
   * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
   */
  const isNewStageRow = (row, list) => {
    const originalQty = originalQtyForRow(row, list);
    const updatedQty = updatedQtyForRow(row, list);
    const hasRecordedChanges =
      Number(row.changedLineCount || 0) > 0 ||
      Number(row.changedPieceQty || 0) > 0 ||
      Number(row.addedPieceQty || 0) > 0 ||
      Number(row.removedLineCount || 0) > 0 ||
      Number(row.removedPieceQty || 0) > 0;

    return Boolean(row.created) || (originalQty <= 0 && updatedQty > 0 && hasRecordedChanges);
  };

  /**
   * Purpose: Run the stage rows for entry workflow for the browser application.
   * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
   * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
   */
  const stageRowsForEntry = (entry) => {
    if (Array.isArray(entry.stageSummaries) && entry.stageSummaries.length) {
      return entry.stageSummaries;
    }

    return (entry.listIds || []).map((listId) => {
      const list = state.lists.find((item) => item.id === listId);

      return {
        listId,
        stage: list?.stage || listId,
        totalQty: list?.totalQty ?? entry.totalQty ?? 0,
        changedLineCount: entry.changedLineCount || 0,
        changedPieceQty: entry.changedPieceQty || entry.addedPieceQty || 0,
        addedPieceQty: entry.addedPieceQty || 0,
        created: Boolean(entry.createdCount),
      };
    });
  };

  /**
   * Purpose: Run the has stage changes workflow for the browser application.
   * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
   * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
   */
  const hasStageChanges = (row) =>
    row.created ||
    Number(row.changedLineCount || 0) ||
    Number(row.changedPieceQty || 0) ||
    Number(row.addedPieceQty || 0) ||
    Number(row.removedLineCount || 0) ||
    Number(row.removedPieceQty || 0);

  const retainedPreviewCountForRow = (row, list) => {
    const catalogCount = Number(list?.newItemCount || 0)
      + Number(list?.updatedItemCount || 0)
      + Number(list?.removedItemCount || 0);
    return catalogCount || Number(row.latestPreviewCount || 0) || Number(row.changedLineCount || 0);
  };

  /**
   * Purpose: Run the stage row key workflow for the browser application.
   * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
   * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
   */
  const stageRowKey = (row) => {
    const list = state.lists.find((item) => item.id === row.listId);

    return String(row.listId || stageNameForRow(row, list))
      .trim()
      .toLowerCase()
      .replace(/\s+/g, " ");
  };

  /**
   * Purpose: Run the stage row priority workflow for the browser application.
   * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
   * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
   */
  const stageRowPriority = (row) => {
    const list = state.lists.find((item) => item.id === row.listId);
    const originalQty = originalQtyForRow(row, list);
    const updatedQty = updatedQtyForRow(row, list);
    const changedQty = changedQtyForRow(row, list);
    const changedLineCount = Number(row.changedLineCount || 0);
    const isNewStage = isNewStageRow(row, list);

    return (
      (originalQty > 0 ? 100000000 : 0) +
      (!isNewStage ? 10000000 : 0) +
      (changedLineCount * 100000) +
      (changedQty * 1000) +
      updatedQty
    );
  };

  /**
   * Purpose: Run the collapse duplicate stage rows workflow for the browser application.
   * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
   * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
   */
  const collapseDuplicateStageRows = (stageRows) => {
    const byStage = new Map();

    for (const row of stageRows) {
      const key = stageRowKey(row);

      if (!key) continue;

      const existing = byStage.get(key);

      if (!existing || stageRowPriority(row) > stageRowPriority(existing)) {
        byStage.set(key, row);
      }
    }

    return [...byStage.values()];
  };

  const managementStageDefinitions = {
    airport: { key: "airport", label: "Airport Road", printRouteGroup: "airport", sort: 0 },
    indian_trail: { key: "indian_trail", label: "Indian Trail", printRouteGroup: "indian_trail", sort: 1 },
    greenville: { key: "greenville", label: "Greenville", printRouteGroup: "greenville", sort: 2 },
    cpu: { key: "cpu", label: "CPU", printRouteGroup: "cpu", sort: 3 },
    dtc: { key: "dtc", label: "DTC", printRouteGroup: "dtc", sort: 4 },
  };

  const stageSortForRow = (row) => {
    const list = state.lists.find((item) => item.id === row.listId);
    return stageSort(list || { stage: stageNameForRow(row, list), scanner: row.stageProfile || "" });
  };

  const isAirportSourceRow = (row, list) => {
    const category = stageCategoryForImportRow(row, list);
    const signal = `${row.listId || ""} ${stageNameForRow(row, list)} ${row.stageProfile || ""}`.toLowerCase();
    return (category === "staged" || category === "outbound")
      && (signal.includes("airport") || signal.includes("staging-airport") || signal.includes("outbound-airport"));
  };

  const allStageRowsForGroup = (group, changedStageRows) => {
    const byStage = new Map();
    const addRow = (row) => {
      const key = stageRowKey(row);
      if (!key || byStage.has(key)) return;
      byStage.set(key, row);
    };

    changedStageRows.forEach(addRow);
    state.lists
      .filter((list) => String(list.deliveryDate || "") === String(group.deliveryDate || ""))
      .forEach((list) => {
        addRow({
          listId: list.id,
          stage: list.stage,
          stageProfile: list.scanner,
          totalQty: list.totalQty || 0,
          changedLineCount: 0,
          changedPieceQty: 0,
          addedPieceQty: 0,
          removedLineCount: 0,
          removedPieceQty: 0,
          created: false,
        });
      });

    return [...byStage.values()].sort((a, b) => {
      const sortDiff = stageSortForRow(a) - stageSortForRow(b);
      if (sortDiff) return sortDiff;
      const listA = state.lists.find((item) => item.id === a.listId);
      const listB = state.lists.find((item) => item.id === b.listId);
      return stageNameForRow(a, listA).localeCompare(stageNameForRow(b, listB));
    });
  };

  const outboundSourceForDate = (deliveryDate, stageRows = []) => {
    const row = stageRows.find((candidate) => {
      const list = state.lists.find((item) => item.id === candidate.listId);
      return stageCategoryForImportRow(candidate, list) === "outbound" && isAirportSourceRow(candidate, list);
    });
    const list = state.lists.find((candidate) => (
      String(candidate.deliveryDate || "") === String(deliveryDate || "")
      && stageCategory(candidate) === "outbound"
    ));
    return { row: row || null, list: list || null };
  };

  /** Restore every stage row while collapsing only Staging/Outbound into Airport Road. */
  const managementRowsForGroup = (group, changedStageRows) => {
    const allRows = allStageRowsForGroup(group, changedStageRows);
    const airportRows = allRows.filter((row) => {
      const list = state.lists.find((item) => item.id === row.listId);
      return isAirportSourceRow(row, list);
    });
    const nonAirportRows = allRows.filter((row) => {
      const list = state.lists.find((item) => item.id === row.listId);
      return !isAirportSourceRow(row, list);
    });
    const outboundSource = outboundSourceForDate(group.deliveryDate, allRows);

    const buildRow = (rowsForDisplay, definition, fallbackRow = null) => {
      const changedRows = rowsForDisplay.filter(hasStageChanges);
      const representative = (changedRows.length ? changedRows : rowsForDisplay)
        .slice()
        .sort((a, b) => {
          const listA = state.lists.find((item) => item.id === a.listId);
          const listB = state.lists.find((item) => item.id === b.listId);
          const categoryA = stageCategoryForImportRow(a, listA);
          const categoryB = stageCategoryForImportRow(b, listB);
          const airportPreferenceA = definition.key === "airport" && categoryA === "outbound" ? 1000000000 : 0;
          const airportPreferenceB = definition.key === "airport" && categoryB === "outbound" ? 1000000000 : 0;
          return (airportPreferenceB + stageRowPriority(b)) - (airportPreferenceA + stageRowPriority(a));
        })[0] || fallbackRow;
      if (!representative) return null;

      const list = state.lists.find((item) => item.id === representative.listId);
      const rowHasChanges = changedRows.length > 0;
      const changeRow = changedRows
        .slice()
        .sort((a, b) => stageRowPriority(b) - stageRowPriority(a))[0] || representative;
      const changeList = state.lists.find((item) => item.id === changeRow.listId);
      const change = quantityChangeForRow(changeRow, changeList);
      const routePreviewCount = rowHasChanges
        ? Math.max(...changedRows.map((row) => {
            const candidateList = state.lists.find((item) => item.id === row.listId);
            return retainedPreviewCountForRow(row, candidateList);
          }), 0)
        : 0;
      const authoritativePreviewCount = outboundSource.row
        ? retainedPreviewCountForRow(outboundSource.row, outboundSource.list)
        : 0;
      // Route-level previews always read from the date's authoritative Outbound
      // catalog when it exists. The route filter then selects Greenville, CPU,
      // DTC, Indian Trail, or Airport orders by the item's actual route. This
      // avoids stale/retired destination-stage IDs such as an old CPU list.
      const previewSourceId = rowHasChanges
        ? (outboundSource.list?.id
            ? String(outboundSource.list.id)
            : String(changeRow.listId || ""))
        : "";
      const printSourceId = outboundSource.list?.id
        ? String(outboundSource.list.id)
        : (list && Number(list.totalQty || 0) > 0 ? String(list.id) : "");

      return {
        ...definition,
        representative,
        list,
        rowHasChanges,
        previewListIds: previewSourceId ? [previewSourceId] : [],
        previewCount: routePreviewCount || authoritativePreviewCount,
        previewRouteGroup: definition.key === "airport" ? "" : definition.key.replaceAll("_", "-"),
        printListIds: printSourceId ? [printSourceId] : [],
        originalQty: originalQtyForRow(representative, list),
        updatedQty: updatedQtyForRow(representative, list),
        addedPieceQty: (() => {
          const originalQty = originalQtyForRow(representative, list);
          const updatedQty = updatedQtyForRow(representative, list);
          const recordedAdded = Number(changeRow.addedPieceQty ?? changeRow.addedQty ?? 0);
          return recordedAdded || Math.max(updatedQty + Number(change.removed || 0) - originalQty, 0);
        })(),
        updatedPieceQty: change.updated,
        removedPieceQty: change.removed,
        isNew: rowHasChanges && isNewStageRow(changeRow, changeList),
      };
    };

    const rows = [];
    if (airportRows.length) {
      const airportRow = buildRow(airportRows, managementStageDefinitions.airport);
      if (airportRow) rows.push(airportRow);
    }

    for (const row of nonAirportRows) {
      const list = state.lists.find((item) => item.id === row.listId);
      const category = stageCategoryForImportRow(row, list);
      let definition;
      if (category === "received") definition = managementStageDefinitions.indian_trail;
      else if (category === "greenville") definition = managementStageDefinitions.greenville;
      else if (category === "pickup") definition = managementStageDefinitions.cpu;
      else if (category === "dtc") definition = managementStageDefinitions.dtc;
      else {
        const label = stageNameForRow(row, list);
        definition = {
          key: `custom-${slugify(label || row.listId || "route")}`,
          label,
          printRouteGroup: "airport",
          sort: 20 + stageSortForRow(row),
        };
      }
      const managementRow = buildRow([row], definition, row);
      if (managementRow) rows.push(managementRow);
    }

    return rows.sort((a, b) => a.sort - b.sort || a.label.localeCompare(b.label));
  };

  const groups = new Map();

  for (const entry of rows) {
    const groupKey = [
      String(entry.deliveryDate || ""),
      String(entry.sourceName || entry.fileName || ""),
    ].join("|") || String(entry.importedAt || "unknown");

    if (!groups.has(groupKey)) {
      groups.set(groupKey, {
        key: groupKey,
        deliveryDate: entry.deliveryDate || "",
        sourceName: entry.sourceName || entry.fileName || "Imported delivery list",
        importedAt: entry.importedAt || entry.updatedAt || entry.createdAt || "",
        entries: [],
        stageRows: [],
      });
    }

    const group = groups.get(groupKey);
    const entryStageRows = stageRowsForEntry(entry);

    group.entries.push(entry);
    group.stageRows.push(...entryStageRows);


    if (entry.importedAt || entry.updatedAt || entry.createdAt) {
      group.importedAt = entry.importedAt || entry.updatedAt || entry.createdAt;
    }
  }

  return `
    <div class="admin-import-date-list">
      ${[...groups.values()]
        .map((group, index) => {
          const previewContextKey = `${group.key}|${group.importedAt || ""}|${index}`;
          state.adminImportPreviewContexts.set(previewContextKey, group.entries.slice());
          const changedStageRows = collapseDuplicateStageRows(group.stageRows.filter(hasStageChanges));
          const allStageRows = allStageRowsForGroup(group, changedStageRows);
          const managementRows = managementRowsForGroup(group, changedStageRows);
          const stagingRows = allStageRows.filter((row) => {
            const list = state.lists.find((item) => item.id === row.listId);
            return isStagingRow(row, list);
          });

          const changedStagingRows = changedStageRows.filter((row) => {
            const list = state.lists.find((item) => item.id === row.listId);
            return isStagingRow(row, list);
          });

          const stagingOriginalQty = stagingRows.reduce((sum, row) => {
            const list = state.lists.find((item) => item.id === row.listId);
            return sum + originalQtyForRow(row, list);
          }, 0);

          const stagingUpdatedQty = stagingRows.reduce((sum, row) => {
            const list = state.lists.find((item) => item.id === row.listId);
            return sum + updatedQtyForRow(row, list);
          }, 0);
          const stagingRemovedQty = stagingRows.reduce((sum, row) => sum + Number(row.removedPieceQty || 0), 0);
          const stagingRecordedAddedQty = stagingRows.reduce((sum, row) => sum + Number(row.addedPieceQty || 0), 0);
          const stagingAddedQty = stagingRecordedAddedQty || Math.max(stagingUpdatedQty + stagingRemovedQty - stagingOriginalQty, 0);
          const changedManagementRows = managementRows.filter((row) => row.rowHasChanges);
          const newManagementRows = changedManagementRows.filter((row) => row.isNew);
          const updatedManagementRows = changedManagementRows.filter((row) => !row.isNew);
          const hasNewStages = newManagementRows.length > 0;
          const hasUpdatedStages = updatedManagementRows.length > 0;
          const removedManagementRows = changedManagementRows.filter((row) => Number(row.removedPieceQty || 0) > 0);
          const hasRemovedPieces = removedManagementRows.length > 0;
          const isBrandNewDeliveryList = changedManagementRows.length > 0
            && changedManagementRows.every((row) => row.isNew)
            && changedManagementRows.some((row) => row.key === "airport");
          const outboundSource = outboundSourceForDate(group.deliveryDate, allStageRows);
          const printableIds = outboundSource.list?.id ? [String(outboundSource.list.id)] : [];
          const fallbackPreviewIds = changedManagementRows
            .flatMap((row) => row.previewListIds)
            .filter(Boolean);
          const previewListIds = outboundSource.list?.id
            ? [String(outboundSource.list.id)]
            : [...new Set(fallbackPreviewIds)];
          const outboundPreviewCount = outboundSource.row
            ? retainedPreviewCountForRow(outboundSource.row, outboundSource.list)
            : 0;
          const previewItemCount = outboundPreviewCount
            || Math.max(...changedManagementRows.map((row) => Number(row.previewCount || 0)), 0);
          const printButtonLabel = "Print / Export Airport Road Delivery List";
          const hasAnyChanges = changedManagementRows.length > 0;
          const groupClass = !hasAnyChanges
            ? "is-no-update-batch"
            : isBrandNewDeliveryList
              ? "is-new-delivery-list"
              : hasNewStages && hasUpdatedStages
                ? "is-mixed-batch"
                : hasNewStages
                  ? "is-new-route-batch"
                  : "is-updated-batch";
          const importedText = group.importedAt ? `Updated at: ${formatDateTime(group.importedAt)}` : "Updated at: --";
          const sourceFileText = group.sourceName ? `File: ${group.sourceName}` : "";
          const groupStatusHtml = hasAnyChanges
            ? `
              ${hasUpdatedStages ? `<span class="import-status-pill updated">Updated</span>` : ""}
              ${hasRemovedPieces ? `<span class="import-status-pill removed">Removed</span>` : ""}
              ${isBrandNewDeliveryList ? `<span class="import-status-pill new">New Delivery List</span>` : ""}
              ${hasNewStages && !isBrandNewDeliveryList ? `<span class="import-status-pill new-stage">New Stage</span>` : ""}
            `
            : `<span class="import-status-pill no-change">No Updates</span>`;

          const stageHtml = managementRows.length
            ? managementRows
                .map((managementRow) => {
                  const rowIsNew = managementRow.isNew;
                  const rowHasChanges = managementRow.rowHasChanges;
                  const routeClass = `route-row-${managementRow.key.replaceAll("_", "-")}`;
                  const rowChangeClass = rowIsNew
                    ? "is-new-row"
                    : rowHasChanges
                      ? "is-updated-row"
                      : "is-unchanged-row";
                  const kindLabel = rowIsNew ? "New Stage" : rowHasChanges ? "Updated" : "No Updates";
                  const kindClass = rowIsNew ? "new-stage" : rowHasChanges ? "updated" : "no-change";
                  const hasRetainedPreview = rowHasChanges
                    && managementRow.previewListIds.length > 0
                    && managementRow.previewCount > 0;
                  const canPrintRoute = managementRow.printListIds.length > 0 && managementRow.updatedQty > 0;
                  const printRouteLabel = canPrintRoute
                    ? `Print / Export ${managementRow.label}`
                    : "No active items are available to print";
                  const changeHtml = quantityFlowChangesHtml(managementRow.addedPieceQty, managementRow.removedPieceQty);
                  const rowStatusHtml = `${rowHasChanges && !rowIsNew ? `<span class="import-status-pill updated">Updated</span>` : ""}${Number(managementRow.removedPieceQty || 0) ? `<span class="import-status-pill removed">Removed</span>` : ""}${rowIsNew ? `<span class="import-status-pill new-stage">New Stage</span>` : ""}${!rowHasChanges ? `<span class="import-status-pill no-change">No Updates</span>` : ""}`;

                  return `
                    <tr class="${routeClass} ${rowChangeClass} ${Number(managementRow.removedPieceQty || 0) ? "has-removals" : ""}">
                      <td><span class="stage-pill-admin admin-import-route-pill">${escapeHtml(managementRow.label)}</span></td>
                      <td><span class="qty-before">${escapeHtml(managementRow.originalQty)} pcs</span></td>
                      <td>${changeHtml}</td>
                      <td><strong>${escapeHtml(managementRow.updatedQty)} pcs</strong></td>
                      <td><span class="admin-import-row-status-v257">${rowStatusHtml}</span></td>
                      <td>
                        <span class="admin-import-stage-actions-v230">
                          ${hasRetainedPreview
                            ? `<button
                                type="button"
                                class="admin-import-icon-button admin-update-preview-button"
                                data-admin-list-update-preview="${escapeHtml(managementRow.previewListIds.join(","))}"
                                data-admin-preview-context="${escapeHtml(previewContextKey)}"
                                ${managementRow.previewRouteGroup ? `data-admin-preview-route-group="${escapeHtml(managementRow.previewRouteGroup)}"` : ""}
                                aria-label="Preview ${managementRow.previewCount} changed row${managementRow.previewCount === 1 ? "" : "s"} for ${escapeHtml(managementRow.label)}"
                                title="Preview ${escapeHtml(managementRow.label)} changes (${managementRow.previewCount} row${managementRow.previewCount === 1 ? "" : "s"})"
                              >${adminUpdatePreviewIconHtml()}</button>`
                            : ""}
                          <button
                            type="button"
                            class="admin-import-icon-button"
                            ${canPrintRoute ? `data-print-lists="${escapeHtml(managementRow.printListIds.join(","))}" data-print-date="${escapeHtml(group.deliveryDate)}" data-print-route-groups="${escapeHtml(managementRow.printRouteGroup)}"` : "disabled"}
                            aria-label="${escapeHtml(printRouteLabel)}"
                            title="${escapeHtml(printRouteLabel)}"
                          ><span class="admin-import-print-icon" aria-hidden="true"></span></button>
                        </span>
                      </td>
                    </tr>
                  `;
                })
                .join("")
            : `
              <tr>
                <td colspan="6">No delivery-list stages are available.</td>
              </tr>
            `;

          const groupOpen = state.adminOpenDeliveryGroups.has(group.key);

          return `
            <details
              class="admin-import-date-group ${groupClass}"
              data-admin-delivery-group-key="${escapeHtml(group.key)}"
              ${groupOpen ? "open" : ""}
            >
<summary class="admin-import-date-summary">
  <span class="admin-import-expand-arrow" aria-hidden="true"></span>
  <span class="admin-import-date-main">
    <span class="admin-import-date-title">
      <strong>${escapeHtml(formatDisplayDate(group.deliveryDate))}</strong>
      <span class="admin-import-status-pills">
        ${groupStatusHtml}
      </span>
    </span>

    <span class="admin-import-date-meta">
      <small class="admin-import-updated-at">${escapeHtml(importedText)}</small>
      ${sourceFileText ? `<small class="admin-import-source-file">${escapeHtml(sourceFileText)}</small>` : ""}
    </span>
  </span>

  <span class="admin-import-date-qty">
    <span class="admin-import-qty-flow">
      <span class="qty-before">${escapeHtml(stagingOriginalQty)} pcs</span>
      ${quantityFlowChangesHtml(stagingAddedQty, stagingRemovedQty)}
      <strong>${escapeHtml(stagingUpdatedQty)} pcs</strong>
    </span>
  </span>

  <span class="admin-import-summary-actions">
    ${
      hasAnyChanges && previewListIds.length
        ? `<button
            type="button"
            class="admin-import-icon-button admin-update-preview-button"
            data-admin-list-update-preview="${escapeHtml(previewListIds.join(","))}"
            data-admin-preview-context="${escapeHtml(previewContextKey)}"
            aria-label="Preview ${escapeHtml(previewItemCount)} changed row${previewItemCount === 1 ? "" : "s"}"
            title="Preview ${escapeHtml(previewItemCount)} changed row${previewItemCount === 1 ? "" : "s"}"
          >${adminUpdatePreviewIconHtml()}</button>`
        : ""
    }
    ${
      printableIds.length
        ? `<button
            type="button"
            class="admin-import-icon-button"
            data-print-lists="${escapeHtml(printableIds.join(","))}"
            data-print-date="${escapeHtml(group.deliveryDate)}"
            data-print-route-groups="airport"
            aria-label="${escapeHtml(printButtonLabel)}"
            title="${escapeHtml(printButtonLabel)}"
          ><span class="admin-import-print-icon" aria-hidden="true"></span></button>`
        : ""
    }
  </span>
</summary>

              <div class="admin-import-stage-wrap">
                <table>
                  <thead>
                    <tr>
                      <th>Stage / Route</th>
                      <th>Original Qty</th>
                      <th>Changes</th>
                      <th>Current Qty</th>
                      <th>Status</th>
                      <th></th>
                    </tr>
                  </thead>
                  <tbody>
                    ${stageHtml}
                  </tbody>
                </table>
              </div>
            </details>
          `;
        })
        .join("")}
    </div>
  `;
}

/**
 * Purpose: Render the render admin delete controls workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may call the backend api, may update shared client state.
 * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
 */
function renderAdminDeleteControls() {
  if (!els.deleteDateSelect || !els.deleteListSelect) return;
  const groups = listsByDeliveryDate();
  const selectedDate = els.deleteDateSelect.value || groups[0]?.date || "";
  els.deleteDateSelect.dataset.deliveryDateSelect = "true";
  els.deleteDateSelect.innerHTML = groupedDeliveryDateOptions(
    groups,
    (group) => `<option value="${escapeHtml(group.date)}">${escapeHtml(formatNumericDeliveryDate(group.date))}</option>`,
  );
  els.deleteDateSelect.value = groups.some((group) => group.date === selectedDate) ? selectedDate : groups[0]?.date || "";
  const lists = groups.find((group) => group.date === els.deleteDateSelect.value)?.lists || [];
  const selectedList = els.deleteListSelect.value || lists[0]?.id || "";
  els.deleteListSelect.innerHTML = lists
    .map((list) => `<option value="${escapeHtml(list.id)}">${escapeHtml(list.stage)} - ${escapeHtml(list.scanner)}</option>`)
    .join("");
  els.deleteListSelect.value = lists.some((list) => list.id === selectedList) ? selectedList : lists[0]?.id || "";
}

/**
 * Purpose: Render the render admin reset controls workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Reads normalized state, builds the relevant markup, and refreshes only the owned interface region.
 */
function renderAdminResetControls() {
  if (!els.resetListSelect) return;
  const selected = els.resetListSelect.value || state.activeListId || state.lists[0]?.id || "";
  els.resetListSelect.innerHTML = state.lists
    .map((list) => `<option value="${escapeHtml(list.id)}">${escapeHtml(formatDisplayDate(list.deliveryDate))} - ${escapeHtml(list.stage)} - ${escapeHtml(list.scanner)}</option>`)
    .join("");
  els.resetListSelect.value = state.lists.some((list) => list.id === selected) ? selected : state.lists[0]?.id || "";
}

/**
 * Purpose: Run the reset selected admin scans workflow for the browser application.
 * Effects: Updates visible dom state, may call the backend api, may update shared client state.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
async function resetSelectedAdminScans() {
  const listId = els.resetListSelect?.value || "";
  await resetAdminScansForList(listId);
}

/**
 * Purpose: Run the reset admin scans for list workflow for the browser application.
 * Effects: May call the backend api, may update shared client state.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
async function resetAdminScansForList(listId) {
  const list = state.lists.find((item) => item.id === listId);
  if (!list) return;
  const confirmed = await confirmWebAppAction({
    title: "Reset scans?",
    message: `Reset all scan quantities and scan history for <strong>${escapeHtml(list.label)}</strong>.`,
    details: "This keeps the delivery-list rows but returns this stage to zero scanned quantity.",
    confirmLabel: "Reset scans",
    requiredText: "RESET",
    requiredTextLabel: "Type RESET to reset this delivery-list stage",
  });

  if (!confirmed) {
    if (els.resetScansStatus) els.resetScansStatus.innerHTML = `<strong>Reset cancelled</strong><span>No scan data was changed.</span>`;
    return;
  }
  const payload = await fetchJson("/api/reset", {
    method: "POST",
    body: JSON.stringify({ listId, confirmText: "RESET", ...requestContext() }),
  });
  if (payload.meta?.id === state.activeListId) applyBackendPayload(payload);
  await loadDeliveryLists(state.activeListId);
  if (els.resetScansStatus) els.resetScansStatus.innerHTML = `<strong>Scans reset</strong><span>${escapeHtml(list.label)} is back to zero scanned quantity.</span>`;
  renderAdminDeliveryLists();
  playAppSound("destructive_action", { force: true });
}

/**
 * Purpose: Run the reset admin scans for date workflow for the browser application.
 * Effects: May call the backend api, may update shared client state.
 * Flow: Validates the user action, delegates to the shared workflow/API, and presents success or error feedback.
 */
async function resetAdminScansForDate(deliveryDate) {
  const lists = state.lists.filter((list) => list.deliveryDate === deliveryDate);

  if (!lists.length) return;

  const confirmed = await confirmWebAppAction({
    title: "Reset every stage for this date?",
    message: `Reset all scan quantities and scan history for every stage on <strong>${escapeHtml(formatDisplayDate(deliveryDate))}</strong>.`,
    details: `${lists.length} stage${lists.length === 1 ? "" : "s"} will be reset. Delivery-list rows will stay in place.`,
    confirmLabel: "Reset all stages",
    requiredText: "RESET",
    requiredTextLabel: "Type RESET to reset every stage for this date",
  });

  if (!confirmed) {
    if (els.resetScansStatus) {
      els.resetScansStatus.innerHTML = `<strong>Reset cancelled</strong><span>No scan data was changed.</span>`;
    }

    return;
  }

  for (const list of lists) {
    await fetchJson("/api/reset", {
      method: "POST",
      body: JSON.stringify({ listId: list.id, confirmText: "RESET", ...requestContext() }),
    });
  }

  await loadDeliveryLists(state.activeListId);
  if (state.activeListId && lists.some((list) => list.id === state.activeListId)) {
    await activateList(state.activeListId, false);
  }
  await refreshAdminPage();

  renderHome();
  renderScanPage();
  renderDeliveryListSelect();
  renderAdminDeleteControls();
  renderAdminResetControls();
  renderAdminDeliveryLists();

  await refreshAdminDeliveryListModal();

  if (els.resetScansStatus) {
    els.resetScansStatus.innerHTML = `<strong>Scans reset</strong><span>Every stage for ${escapeHtml(formatDisplayDate(deliveryDate))} is back to zero scanned quantity.</span>`;
  }
  playAppSound("destructive_action", { force: true });
}

/**
 * Purpose: Remove the delete admin delivery date by date workflow using the existing shared UI state.
 * Effects: May call the backend api.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function deleteAdminDeliveryDateByDate(deliveryDate) {
  if (!deliveryDate) return;

  const lists = state.lists.filter((list) => list.deliveryDate === deliveryDate);
  const confirmed = await confirmWebAppAction({
    title: "Delete every stage for this date?",
    message: `Delete every delivery-list stage for <strong>${escapeHtml(formatDisplayDate(deliveryDate))}</strong>.`,
    details: `${lists.length || "All matching"} stage${lists.length === 1 ? "" : "s"} will be removed. This cannot be undone from the web app.`,
    confirmLabel: "Delete date",
    requiredText: "DELETE",
    requiredTextLabel: "Type DELETE to remove every stage for this date",
  });

  if (!confirmed) return;

  const result = await fetchJson("/api/admin/delete-date", {
    method: "POST",
    body: JSON.stringify({ deliveryDate, confirmText: "DELETE", ...requestContext() }),
  });

  state.lists = result.lists || [];

  if (!state.lists.some((list) => list.id === state.activeListId)) {
    state.activeListId = state.lists[0]?.id || "";

    if (state.activeListId) {
      await activateList(state.activeListId, false);
    } else {
      state.meta = null;
      state.items = [];
      state.recent = [];
      state.errors = [];
      state.lastScan = null;
    }
  }

  await loadDeliveryLists(state.activeListId);
  await refreshAdminPage();

  renderHome();
  renderScanPage();
  renderDeliveryListSelect();
  renderAdminDeleteControls();
  renderAdminResetControls();
  renderAdminDeliveryLists();

  await refreshAdminDeliveryListModal();

  if (els.deleteListStatus) {
    els.deleteListStatus.innerHTML = `<strong>Deleted date</strong><span>${escapeHtml(result.deletedCount || 0)} stages removed.</span>`;
  }
  playAppSound("destructive_action", { force: true });
}

/**
 * Purpose: Remove the delete selected delivery list workflow using the existing shared UI state.
 * Effects: Updates visible dom state, may call the backend api, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function deleteSelectedDeliveryList(deleteDate = false) {
  if (!state.backend) return;

  const deliveryDate = els.deleteDateSelect?.value || "";
  const listId = els.deleteListSelect?.value || "";

  if (deleteDate) {
    if (!deliveryDate) return;

    const lists = state.lists.filter((list) => list.deliveryDate === deliveryDate);
    const confirmed = await confirmWebAppAction({
      title: "Delete every stage for this date?",
      message: `Delete every delivery-list stage for <strong>${escapeHtml(formatDisplayDate(deliveryDate))}</strong>.`,
      details: `${lists.length || "All matching"} stage${lists.length === 1 ? "" : "s"} will be removed. This cannot be undone from the web app.`,
      confirmLabel: "Delete date",
      requiredText: "DELETE",
      requiredTextLabel: "Type DELETE to remove every stage for this date",
    });

    if (!confirmed) return;

    const result = await fetchJson("/api/admin/delete-date", {
      method: "POST",
      body: JSON.stringify({ deliveryDate, confirmText: "DELETE", ...requestContext() }),
    });
    state.lists = result.lists || [];
    if (els.deleteListStatus) els.deleteListStatus.innerHTML = `<strong>Deleted date</strong><span>${escapeHtml(result.deletedCount || 0)} stages removed.</span>`;
  } else {
    const list = state.lists.find((item) => item.id === listId);
    if (!list) return;

    const confirmed = await confirmWebAppAction({
      title: "Delete this delivery-list stage?",
      message: `Delete <strong>${escapeHtml(list.label)}</strong>.`,
      details: "This removes that stage and its rows from the active delivery-list set.",
      confirmLabel: "Delete stage",
      requiredText: "DELETE",
      requiredTextLabel: "Type DELETE to remove this delivery-list stage",
    });

    if (!confirmed) return;

    const result = await fetchJson("/api/admin/delete-list", {
      method: "POST",
      body: JSON.stringify({ listId, confirmText: "DELETE", ...requestContext() }),
    });
    state.lists = result.lists || [];
    if (els.deleteListStatus) els.deleteListStatus.innerHTML = `<strong>Deleted stage</strong><span>${escapeHtml(result.deletedListId || listId)} removed.</span>`;
  }

  if (!state.lists.some((list) => list.id === state.activeListId)) {
    state.activeListId = state.lists[0]?.id || "";

    if (state.activeListId) {
      await activateList(state.activeListId, false);
    } else {
      state.meta = null;
      state.items = [];
      state.recent = [];
      state.errors = [];
      state.lastScan = null;
    }
  }

  await loadDeliveryLists(state.activeListId);
  await refreshAdminPage();

  renderHome();
  renderScanPage();
  renderDeliveryListSelect();
  renderAdminDeleteControls();
  renderAdminDeliveryLists();
  playAppSound("destructive_action", { force: true });
}

