const MANUAL_EDIT_CUSTOM_VALUE = "__manual_edit_custom__";

/**
 * Purpose: Run the manual edit option has value workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditOptionHasValue(options, value) {
  const cleanValue = String(value ?? "");

  return options.some(([optionValue]) => String(optionValue ?? "") === cleanValue);
}

/**
 * Purpose: Run the lookup options workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function lookupOptions(items = [], blankLabel = "Blank") {
  const seen = new Set();
  const options = [["", blankLabel]];
  for (const item of items || []) {
    const value = String(item.value ?? "").trim();
    if (!value || seen.has(value)) continue;
    seen.add(value);
    options.push([value, item.label || value]);
  }
  return options;
}

/**
 * Purpose: Run the manual edit is custom choice workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditIsCustomChoice(options, value) {
  const cleanValue = String(value ?? "").trim();

  return Boolean(cleanValue) && !manualEditOptionHasValue(options, cleanValue);
}

/**
 * Purpose: Run the manual edit select options workflow for the browser application.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditSelectOptions(options, selectedValue = "", customLabel = "Custom value...") {
  const selected = String(selectedValue ?? "");
  const selectedIsCustom = manualEditIsCustomChoice(options, selected);
  const seen = new Set();

  const optionHtml = options
    .filter(([value]) => {
      const key = String(value ?? "");

      if (seen.has(key)) return false;

      seen.add(key);
      return true;
    })
    .map(([value, label]) => {
      const cleanValue = String(value ?? "");
      const isSelected = !selectedIsCustom && cleanValue === selected;

      return `<option value="${escapeHtml(cleanValue)}" ${isSelected ? "selected" : ""}>${escapeHtml(label)}</option>`;
    })
    .join("");

  return `
    ${optionHtml}
    <option value="${MANUAL_EDIT_CUSTOM_VALUE}" ${selectedIsCustom ? "selected" : ""}>${escapeHtml(customLabel)}</option>
  `;
}

/**
 * Purpose: Run the manual edit choice field HTML workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditChoiceFieldHtml({ field, label, value = "", options = [], customLabel = "", wide = false }) {
  const cleanField = String(field || "");
  const cleanLabel = String(label || cleanField);
  const cleanValue = String(value ?? "");
  const customText = customLabel || `Custom ${cleanLabel.toLowerCase()}...`;
  const isCustom = manualEditIsCustomChoice(options, cleanValue);

  return `
    <label class="manual-field has-custom ${wide ? "wide" : ""}">
      <span>${escapeHtml(cleanLabel)}</span>

      <div class="manual-choice-control ${isCustom ? "is-custom" : ""}" data-choice-control data-choice-field="${escapeHtml(cleanField)}">
        <select
          class="manual-edit-select manual-edit-choice-select"
          data-choice-field="${escapeHtml(cleanField)}"
          aria-label="${escapeHtml(cleanLabel)} dropdown"
          title="${escapeHtml(cleanValue || cleanLabel)}"
          ${isCustom ? "hidden" : ""}
        >
          ${manualEditSelectOptions(options, cleanValue, customText)}
        </select>

        <div class="manual-custom-control" ${isCustom ? "" : "hidden"}>
          <input
            class="manual-edit-input manual-edit-custom-input"
            data-custom-field="${escapeHtml(cleanField)}"
            type="text"
            value="${escapeHtml(isCustom ? cleanValue : "")}"
            placeholder="${escapeHtml(customText.replace("...", ""))}"
            aria-label="Custom ${escapeHtml(cleanLabel)}"
          >
          <button
            type="button"
            class="manual-custom-clear"
            data-manual-custom-clear="${escapeHtml(cleanField)}"
            title="Back to ${escapeHtml(cleanLabel)} dropdown"
            aria-label="Back to ${escapeHtml(cleanLabel)} dropdown"
          >×</button>
        </div>

        <input data-edit-field="${escapeHtml(cleanField)}" type="hidden" value="${escapeHtml(cleanValue)}">
      </div>
    </label>
  `;
}

/**
 * Purpose: Run the manual edit choice hidden input workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditChoiceHiddenInput(control) {
  const field = control?.dataset?.choiceField || "";

  return control?.querySelector(`[data-edit-field="${CSS.escape(field)}"]`) || null;
}


/**
 * Return the value currently shown by a manual-edit choice control.
 * Reading the visible control prevents a stale hidden mirror from discarding
 * a route, location, product, or process selection during save.
 */
function manualEditVisibleChoiceValue(row, field) {
  const control = row?.querySelector(`[data-choice-control][data-choice-field="${CSS.escape(field)}"]`);
  if (!control) return row?.querySelector(`[data-edit-field="${CSS.escape(field)}"]`)?.value ?? "";

  if (control.classList.contains("is-custom")) {
    return control.querySelector(".manual-edit-custom-input")?.value ?? "";
  }

  const select = control.querySelector(".manual-edit-choice-select");
  if (select && select.value !== MANUAL_EDIT_CUSTOM_VALUE) return select.value;
  return manualEditChoiceHiddenInput(control)?.value ?? "";
}

/**
 * Purpose: Run the manual edit set choice value workflow for the browser application.
 * Effects: May update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditSetChoiceValue(control, value, markDirty = true) {
  const hiddenInput = manualEditChoiceHiddenInput(control);

  if (!hiddenInput) return;

  hiddenInput.value = value;

  if (markDirty) {
    state.manualEditDirty = true;
    hiddenInput.dispatchEvent(new Event("input", { bubbles: true }));
  }
}

/**
 * Purpose: Run the manual edit show custom choice workflow for the browser application.
 * Effects: Updates visible dom state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditShowCustomChoice(control, startingValue = "") {
  if (!control) return;

  const select = control.querySelector(".manual-edit-choice-select");
  const customWrap = control.querySelector(".manual-custom-control");
  const customInput = control.querySelector(".manual-edit-custom-input");

  control.classList.add("is-custom");

  if (select) {
    select.hidden = true;
    select.value = MANUAL_EDIT_CUSTOM_VALUE;
  }

  if (customWrap) customWrap.hidden = false;

  if (customInput) {
    customInput.value = startingValue;
    manualEditSetChoiceValue(control, startingValue, false);
    window.setTimeout(() => customInput.focus(), 20);
  }
}

/**
 * Purpose: Run the manual edit show select choice workflow for the browser application.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditShowSelectChoice(control) {
  if (!control) return;

  const select = control.querySelector(".manual-edit-choice-select");
  const customWrap = control.querySelector(".manual-custom-control");
  const customInput = control.querySelector(".manual-edit-custom-input");

  control.classList.remove("is-custom");

  if (customInput) customInput.value = "";
  if (customWrap) customWrap.hidden = true;

  if (select) {
    select.hidden = false;

    if (select.value === MANUAL_EDIT_CUSTOM_VALUE) {
      select.value = "";
    }

    manualEditSetChoiceValue(control, select.value, true);
    window.setTimeout(() => select.focus(), 20);
  }
}

/**
 * Purpose: Run the manual edit apply choice select workflow for the browser application.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditApplyChoiceSelect(select) {
  const control = select?.closest("[data-choice-control]");

  if (!control) return;

  if (select.value === MANUAL_EDIT_CUSTOM_VALUE) {
    manualEditShowCustomChoice(control, "");
    state.manualEditDirty = true;
    return;
  }

  manualEditSetChoiceValue(control, select.value, true);
}

/**
 * Purpose: Run the manual edit apply custom input workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditApplyCustomInput(customInput) {
  const control = customInput?.closest("[data-choice-control]");

  if (!control) return;

  manualEditSetChoiceValue(control, customInput.value, false);
  state.manualEditDirty = true;
}

/**
 * Purpose: Run the manual edit clear custom choice workflow for the browser application.
 * Effects: May update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditClearCustomChoice(button) {
  const control = button?.closest("[data-choice-control]");

  if (!control) return;

  manualEditShowSelectChoice(control);
  state.manualEditDirty = true;
}

/**
 * Purpose: Run the manual edit sync choice select workflow for the browser application.
 * Effects: Updates visible dom state, may update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditSyncChoiceSelect(input) {
  const field = input?.dataset?.editField || "";
  const row = input?.closest("[data-edit-row]");
  const control = row?.querySelector(`[data-choice-control][data-choice-field="${CSS.escape(field)}"]`);
  const select = control?.querySelector(".manual-edit-choice-select");

  if (!control || !select) return;

  const value = String(input.value ?? "");
  const hasMatchingOption = [...select.options].some((option) => option.value === value);

  if (value && !hasMatchingOption) {
    manualEditShowCustomChoice(control, value);
    return;
  }

  manualEditShowSelectChoice(control);
  select.value = hasMatchingOption ? value : "";
}

/**
 * Purpose: Run the manual edit current location value workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditCurrentLocationValue(item) {
  return String(item.location || item.rackCode || item.bayCode || "").trim();
}

/**
 * Purpose: Run the manual edit location options workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditLocationOptions(item) {
  const options = [
    ["", "No location / clear"],
  ];

  const racks = (state.racks || [])
    .slice()
    .sort((a, b) => {
      if (a.code === "T") return -1;
      if (b.code === "T") return 1;

      return String(a.code || "").localeCompare(String(b.code || ""), undefined, { numeric: true });
    });

  for (const rack of racks) {
    const code = String(rack.code || "").trim();

    if (!code) continue;

    const name = rack.name || rack.type || "Rack";
    const qty = Number(rack.qty || 0);
    const status = rackStatusLabel(rack);

    options.push([
      code,
      isTruckRack(rack)
        ? `${code} - ${name || (code === "T" ? "Truck / no rack" : `Truck ${code.replace(/^T/i, "")}`)} (${qty} pcs, ${status})`
        : `${code} - ${name} (${qty} pcs, ${status})`,
    ]);
  }

  const bays = (state.bays || [])
    .slice()
    .sort((a, b) => String(a.bayCode || a.code || "").localeCompare(String(b.bayCode || b.code || ""), undefined, { numeric: true }));

  for (const bay of bays) {
    const bayCode = String(bay.bayCode || bay.code || "").trim();

    if (!bayCode) continue;

    options.push([
      bayCode,
      `Bay ${bay.displayName || bayCode}`,
    ]);
  }

  return options;
}

/**
 * Purpose: Run the manual edit route options workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditRouteSelectionValue(value) {
  const raw = String(value || "").trim();
  const designation = canonicalRouteDesignation(raw);
  if (designation.matched) return designation.route || "INDIAN TRAIL";
  return raw || "INDIAN TRAIL";
}

function manualEditRouteOptions() {
  const seen = new Set();
  const lookupRoutes = lookupOptions(state.manualEditLookups?.routes || [], "Indian Trail / Standard")
    .map(([value, label]) => [manualEditRouteSelectionValue(value), label])
    .filter(([value]) => {
      const key = String(value || "").trim().toUpperCase();
      if (!key || seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  if (lookupRoutes.length > 1) return lookupRoutes;
  return [
    ["INDIAN TRAIL", "Indian Trail / Standard"],
    ["CPU", "Customer Pickup"],
    ["GNV", "Greenville"],
    ["DTC", "Deliver to Customer"],
  ];
}

/**
 * Purpose: Run the manual edit process options workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditProcessOptions() {
  const lookupProcesses = lookupOptions(state.manualEditLookups?.processes || [], "Normal / blank");
  const hasRemake = lookupProcesses.some(([value]) => /^remake$/i.test(String(value || "").trim()));
  if (lookupProcesses.length > 1) {
    return hasRemake ? lookupProcesses : [...lookupProcesses, ["Remake", "Remake"]];
  }
  return [
    ["", "Normal / blank"],
    ["New", "New"],
    ["Updated", "Updated"],
    ["Rush", "Rush"],
    ["Remake", "Remake"],
    ["SDI", "SDI"],
    ["Review", "Needs Review"],
  ];
}

function manualEditProcessDisplayValue(item = {}) {
  const process = String(item.processState || "").trim();
  if (isRemakeItem(item) && (!process || /^(standard|normal|blank)$/i.test(process))) return "Remake";
  return process;
}

/**
 * Purpose: Run the manual edit product options workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditProductOptions(results = []) {
  const productValues = uniqueText([
    ...(state.manualEditLookups?.products || []).map((item) => item.value),
    ...results.map((item) => item.product),
    ...state.items.map((item) => item.product),
    ...state.lists.flatMap((list) => list.items || []).map((item) => item.product),
  ]).sort((a, b) => a.localeCompare(b));

  return [
    ["", "Blank product"],
    ...productValues.map((value) => {
      /**
       * Purpose: Run the lookup workflow for the browser application.
       * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
       * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
       */
      const lookup = (state.manualEditLookups?.products || []).find((item) => String(item.value) === String(value));
      return [value, lookup?.label || value];
    }),
  ];
}

/**
 * Purpose: Run the manual edit set row error workflow for the browser application.
 * Effects: May update shared client state.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditSetRowError(row, message = "") {
  if (!row) return;

  const errorBox = row.querySelector(".manual-edit-row-error");

  row.classList.toggle("is-invalid", Boolean(message));

  row.querySelectorAll(".manual-edit-input.is-invalid, .manual-edit-select.is-invalid").forEach((field) => {
    field.classList.remove("is-invalid");
  });

  if (errorBox) {
    errorBox.hidden = !message;
    errorBox.textContent = message;
  }
}

/**
 * Purpose: Run the manual edit validate row workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditValidateRow(row) {
  if (!row) return false;

  const qtyInput = row.querySelector('[data-edit-field="qty"]');
  const scannedInput = row.querySelector('[data-edit-field="scanned"]');

  if (!qtyInput || !scannedInput) {
    manualEditSetRowError(row, "");
    return true;
  }

  const qty = Number(qtyInput.value || 0);
  const scanned = Number(scannedInput.value || 0);

  scannedInput.max = String(Math.max(qty, 0));

  if (!Number.isFinite(qty) || qty < 0) {
    qtyInput.classList.add("is-invalid");
    manualEditSetRowError(row, "Qty must be zero or greater.");
    return false;
  }

  if (!Number.isFinite(scanned) || scanned < 0) {
    scannedInput.classList.add("is-invalid");
    manualEditSetRowError(row, "Scanned quantity must be zero or greater.");
    return false;
  }

  if (scanned > qty) {
    scannedInput.classList.add("is-invalid");
    manualEditSetRowError(row, "Scanned quantity cannot be greater than Qty.");
    return false;
  }

  manualEditSetRowError(row, "");

  return true;
}

/**
 * Return the editable values currently displayed in one expanded Manual Edit card.
 * The clicked card is passed directly so stale or duplicate modal markup can never
 * substitute a different row during save.
 */
function manualEditCollectRowData(row, lineItemId) {
  const value = (field) => row?.querySelector(`[data-edit-field="${CSS.escape(field)}"]`)?.value ?? "";
  const data = {
    lineItemId: String(lineItemId || row?.dataset?.editRow || ""),
    order: value("order"),
    item: value("item"),
    customer: value("customer"),
    qty: value("qty"),
    scanned: value("scanned"),
    dimensions: value("dimensions"),
    job: value("job"),
    queueState: value("queueState"),
    protectFromAwImport: Boolean(row?.querySelector('[data-edit-field="protectFromAwImport"]')?.checked),
  };

  for (const field of ["location", "route", "processState", "product"]) {
    data[field] = manualEditVisibleChoiceValue(row, field);
  }

  data.route = manualEditRouteSelectionValue(data.route);
  data.routeOverride = data.route;
  return data;
}

function manualEditOriginalRowData(row) {
  try {
    return JSON.parse(row?.dataset?.manualEditOriginal || "{}");
  } catch (_error) {
    return {};
  }
}

function manualEditComparableValue(field, value) {
  if (["qty", "scanned"].includes(field)) return Number(value || 0);
  if (field === "protectFromAwImport") return Boolean(value);
  if (field === "item") {
    const text = String(value || "").trim();
    return /^\d+$/.test(text) ? text.padStart(3, "0") : text;
  }
  if (field === "order") {
    const text = String(value || "").trim();
    return /^\d+$/.test(text) ? String(Number(text)) : text;
  }
  if (field === "route") return manualEditRouteSelectionValue(value);
  if (field === "location") return String(value || "").trim().toUpperCase();
  return String(value ?? "");
}

function manualEditChangedFields(row, data) {
  const original = manualEditOriginalRowData(row);
  return [
    "order",
    "item",
    "customer",
    "qty",
    "scanned",
    "location",
    "route",
    "processState",
    "product",
    "dimensions",
    "job",
    "queueState",
    "protectFromAwImport",
  ].filter((field) => (
    manualEditComparableValue(field, data[field]) !== manualEditComparableValue(field, original[field])
  ));
}

/**
 * Purpose: Run the manual edit results HTML workflow for the browser application.
 * Effects: Keeps side effects limited to the behavior implied by the function name and its direct callers.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function manualEditResultsHtml(results, visibleCount = 20, totalCount = results.length) {
  const visibleRows = results.slice(0, Math.max(Number(visibleCount || 20), 20));
  const totalRows = Math.max(Number(totalCount || 0), results.filter((item) => !item._manualEditFilterMismatch).length);
  const pinnedRows = visibleRows.filter((item) => item._manualEditFilterMismatch).length;
  const matchingVisibleRows = Math.max(visibleRows.length - pinnedRows, 0);
  const remainingRows = Math.max(totalRows - matchingVisibleRows, 0);

  return results.length
    ? `
      <div class="manual-edit-result-summary">
        <span>Showing ${escapeHtml(matchingVisibleRows)} of ${escapeHtml(totalRows)} matching row${totalRows === 1 ? "" : "s"}${pinnedRows ? ` + ${escapeHtml(pinnedRows)} recently updated` : ""}</span>
        <small>${pinnedRows ? "The saved row remains visible until the next search or filter change." : "Rows start collapsed. Expand one to edit it."}</small>
      </div>

      <div class="manual-edit-card-list">
        ${visibleRows
          .map((item) => {
            const rowLabel = `${item.order || ""}-${item.item || ""}`;
            const stageText = item.stage || item.deliveryLabel || "";
            const qtyValue = Math.max(Number(item.qty || 0), 0);
            const scannedValue = Math.min(Math.max(Number(item.scanned || 0), 0), qtyValue);
            const locationValue = manualEditCurrentLocationValue(item);
            const scannedClass = scannedValue > 0 ? " is-scanned" : " is-unscanned";
            const completeClass = qtyValue > 0 && scannedValue >= qtyValue ? " is-complete" : "";
            const updatedClass = item._manualEditJustUpdated ? " is-just-updated" : "";
            const mismatchClass = item._manualEditFilterMismatch ? " is-filter-mismatch" : "";
            const originalValues = {
              order: item.order || "",
              item: item.item || "",
              customer: item.customer || "",
              qty: qtyValue,
              scanned: scannedValue,
              location: locationValue,
              route: manualEditRouteSelectionValue(item.route),
              processState: manualEditProcessDisplayValue(item),
              product: item.product || "",
              dimensions: item.dimensions || "",
              job: item.job || "",
              queueState: item.queueState || "",
              protectFromAwImport: Boolean(item.protectFromAwImport),
            };

            return `
              <details
                class="manual-edit-card${scannedClass}${completeClass}${updatedClass}${mismatchClass}"
                data-edit-row="${escapeHtml(item.lineItemId)}"
                data-manual-edit-original="${escapeHtml(JSON.stringify(originalValues))}"
                ${item._manualEditJustUpdated ? "open" : ""}
              >
                <summary class="manual-edit-card-header">
                  <div class="manual-edit-card-title">
                    <div class="manual-edit-card-title-line">
                      <strong>${escapeHtml(item.order)}-${escapeHtml(item.item)}</strong>
                      <span class="manual-edit-scan-status ${scannedValue > 0 ? "is-scanned" : "is-unscanned"}">${scannedValue > 0 ? "Scanned" : "Not scanned"}</span>
                    </div>
                    <span>${escapeHtml(item.job || "No Job Nr.")} &bull; ${escapeHtml(item.customer || "No customer")}</span>
                    ${item._manualEditFilterMismatch ? `<small class="manual-edit-saved-filter-note">Saved successfully — this item no longer matches the active filters.</small>` : ""}
                  </div>

                  <div class="manual-edit-card-stage" title="${escapeHtml(stageText)}">
                    <span>Stage</span>
                    <strong>${escapeHtml(stageText || "No stage")}</strong>
                  </div>

                  <div class="manual-edit-card-quantity">
                    <span>Quantity</span>
                    <strong>${escapeHtml(scannedValue)} / ${escapeHtml(qtyValue)}</strong>
                  </div>

                  <div class="manual-edit-row-actions">
                    <button
                      type="button"
                      class="icon-only icon-save manual-edit-action-button"
                      data-save-line-item="${escapeHtml(item.lineItemId)}"
                      title="Save ${escapeHtml(rowLabel)}"
                      aria-label="Save ${escapeHtml(rowLabel)}"
                    ></button>
                    <button
                      type="button"
                      class="icon-only icon-trash danger manual-edit-action-button"
                      data-delete-line-item="${escapeHtml(item.lineItemId)}"
                      title="Delete ${escapeHtml(rowLabel)}"
                      aria-label="Delete ${escapeHtml(rowLabel)}"
                    ></button>
                  </div>
                  <span class="manual-edit-card-chevron" aria-hidden="true"></span>
                </summary>

                <div class="manual-edit-card-body">
                  <div class="manual-edit-card-grid">

                  <label class="manual-field">
                    <span>Order</span>
                    <input class="manual-edit-input" data-edit-field="order" type="text" value="${escapeHtml(item.order)}">
                  </label>

                  <label class="manual-field small">
                    <span>Item</span>
                    <input class="manual-edit-input" data-edit-field="item" type="text" value="${escapeHtml(item.item)}">
                  </label>

                  <label class="manual-field wide">
                    <span>Customer</span>
                    <input class="manual-edit-input" data-edit-field="customer" type="text" value="${escapeHtml(item.customer)}">
                  </label>

                  <label class="manual-field small">
                    <span>Qty</span>
                    <input class="manual-edit-input" data-edit-field="qty" type="number" min="0" value="${escapeHtml(qtyValue)}">
                  </label>

                  <label class="manual-field small">
                    <span>Scanned</span>
                    <input class="manual-edit-input" data-edit-field="scanned" type="number" min="0" max="${escapeHtml(qtyValue)}" value="${escapeHtml(scannedValue)}">
                  </label>

                  ${manualEditChoiceFieldHtml({
                    field: "location",
                    label: "Location",
                    value: locationValue,
                    options: manualEditLocationOptions(item),
                    customLabel: "Custom location...",
                  })}

                  ${manualEditChoiceFieldHtml({
                    field: "route",
                    label: "Route",
                    value: manualEditRouteSelectionValue(item.route),
                    options: manualEditRouteOptions(),
                    customLabel: "Custom route...",
                  })}

                  ${manualEditChoiceFieldHtml({
                    field: "processState",
                    label: "Process",
                    value: manualEditProcessDisplayValue(item),
                    options: manualEditProcessOptions(),
                    customLabel: "Custom process...",
                  })}

                  ${manualEditChoiceFieldHtml({
                    field: "product",
                    label: "Product",
                    value: item.product || "",
                    options: manualEditProductOptions(visibleRows),
                    customLabel: "Custom product...",
                    wide: true,
                  })}

                  <label class="manual-field wide">
                    <span>Dimensions</span>
                    <input class="manual-edit-input" data-edit-field="dimensions" type="text" value="${escapeHtml(item.dimensions || "")}">
                  </label>

                  <label class="manual-field wide">
                    <span>Job</span>
                    <input class="manual-edit-input" data-edit-field="job" type="text" value="${escapeHtml(item.job || "")}">
                  </label>

                  <input data-edit-field="queueState" type="hidden" value="${escapeHtml(item.queueState || "")}">

                  ${(item.manualOnly || item.manualSource) ? `
                    <label class="manual-order-only-toggle manual-edit-protection-toggle">
                      <input data-edit-field="protectFromAwImport" type="checkbox" ${item.protectFromAwImport ? "checked" : ""}>
                      <span><strong>Protect from A+W import</strong><small>Keep this manual row separate when A+W publishes the same order/item.</small></span>
                    </label>
                  ` : `<input data-edit-field="protectFromAwImport" type="hidden" value="">`}
                  </div>

                  <div class="manual-edit-row-error" hidden aria-live="polite"></div>
                </div>
              </details>
            `;
          })
          .join("")}
      </div>
      ${remainingRows ? `
        <div class="manual-edit-load-more">
          <button type="button" data-manual-edit-load-more>Load 20 more</button>
          <span>${escapeHtml(remainingRows)} row${remainingRows === 1 ? "" : "s"} remaining</span>
        </div>
      ` : ""}
    `
    : `<div class="admin-empty">No editable rows found.</div>`;
}

/**
 * Purpose: Run the save manual line item workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function saveManualLineItem(lineItemId, sourceButton = null) {
  const row = sourceButton?.closest("[data-edit-row]")
    || document.querySelector(`[data-edit-row="${CSS.escape(lineItemId)}"]`);

  if (!row) return;

  closeCustomSelect(false);
  if (document.activeElement instanceof HTMLInputElement || document.activeElement instanceof HTMLSelectElement) {
    document.activeElement.blur();
  }

  if (!manualEditValidateRow(row)) {
    row.querySelector(".is-invalid")?.focus();
    return;
  }

  const data = manualEditCollectRowData(row, lineItemId);
  const clientChangedFields = manualEditChangedFields(row, data);
  const saveButton = sourceButton || row.querySelector("[data-save-line-item]");

  if (!clientChangedFields.length) {
    showFloatingNotice("No edited values were detected in this row.", "notice");
    return;
  }

  data.clientChangedFields = clientChangedFields;
  data.originalValues = manualEditOriginalRowData(row);

  row.classList.add("is-saving");
  if (saveButton) saveButton.disabled = true;
  try {
    const payload = await fetchJson("/api/admin/line-item", {
      method: "POST",
      body: JSON.stringify(data),
    });

    if (!Number(payload.logicalUpdatedCount || 0)) {
      throw new Error(
        `The server did not apply the edited ${clientChangedFields.join(", ")} value${clientChangedFields.length === 1 ? "" : "s"}. `
        + "The row has been left open so the entered values are not lost.",
      );
    }

    const payloadListId = String(payload.meta?.id || "");
    const catalogList = state.lists.find((list) => String(list.id || "") === payloadListId);
    if (catalogList && Array.isArray(payload.items)) {
      catalogList.items = cloneItems(payload.items);
      catalogList.totalQty = pieceCount(catalogList.items);
      catalogList.scannedQty = catalogList.items.reduce((sum, item) => sum + itemScannedPieceQty(item), 0);
    }
    if (payloadListId && payloadListId === state.activeListId) {
      applyBackendPayload(payload);
      if (state.page === "scan") scheduleScanRender();
    }

    const resultItem = state.manualEditResultRows.find((item) => String(item.lineItemId || "") === String(lineItemId));
    if (resultItem) {
      Object.assign(resultItem, {
        order: data.order,
        item: data.item,
        customer: data.customer,
        qty: Number(data.qty || 0),
        scanned: Number(data.scanned || 0),
        route: data.route,
        processState: data.processState,
        product: data.product,
        dimensions: data.dimensions,
        job: data.job,
        queueState: data.queueState,
        protectFromAwImport: Boolean(data.protectFromAwImport),
        location: data.location,
        locationDisplay: data.location,
      });
    }

    const preferredListId = payload.destinationListId || payloadListId || state.activeListId;
    await loadDeliveryLists(preferredListId);
    const refreshLimit = Math.max(state.manualEditResultRows.filter((item) => !item._manualEditFilterMismatch).length, 20);
    const refreshed = await fetchManualEditBatch(state.manualEditQuery, state.manualEditListId, refreshLimit, 0, state.manualEditFilters);
    const verifiedItem = payload.updatedItem && Object.keys(payload.updatedItem).length
      ? { ...payload.updatedItem }
      : {
          ...(resultItem || {}),
          lineItemId,
          order: data.order,
          item: data.item,
          customer: data.customer,
          qty: Number(data.qty || 0),
          scanned: Number(data.scanned || 0),
          route: data.route,
          processState: data.processState,
          product: data.product,
          dimensions: data.dimensions,
          job: data.job,
          queueState: data.queueState,
          location: data.location,
          locationDisplay: data.location,
        };
    const verifiedKey = `${String(verifiedItem.order || "")}::${String(verifiedItem.item || "").padStart(3, "0")}`;
    const matchingIndex = refreshed.results.findIndex((item) => (
      `${String(item.order || "")}::${String(item.item || "").padStart(3, "0")}` === verifiedKey
    ));
    if (matchingIndex >= 0) {
      refreshed.results[matchingIndex] = {
        ...refreshed.results[matchingIndex],
        ...verifiedItem,
        _manualEditJustUpdated: true,
        _manualEditFilterMismatch: false,
      };
    } else {
      refreshed.results.unshift({
        ...verifiedItem,
        _manualEditJustUpdated: true,
        _manualEditFilterMismatch: true,
      });
    }
    state.manualEditGlassTypes = Array.isArray(refreshed.filterOptions?.glassTypes)
      ? refreshed.filterOptions.glassTypes
      : state.manualEditGlassTypes;
    const refreshedGlassTypes = new Set(state.manualEditGlassTypes.map((option) => String(option.label || "")));
    state.manualEditFilters.glassTypes = (state.manualEditFilters.glassTypes || []).filter((label) => refreshedGlassTypes.has(label));
    refreshManualEditFilterDrawer(false);
    state.manualEditResultRows = refreshed.results;
    state.manualEditTotalRows = refreshed.total;
    state.manualEditVisibleCount = state.manualEditResultRows.length;
    const resultsTarget = document.getElementById("manualEditModalResults");
    if (resultsTarget) resultsTarget.innerHTML = manualEditResultsHtml(state.manualEditResultRows, state.manualEditVisibleCount, state.manualEditTotalRows);

    state.manualEditDirty = false;
    await refreshOpenModalActionHistory().catch(() => {});
    showSaveConfirmation(payload.message || "Line item updated and verified.");
  } finally {
    row.classList.remove("is-saving");
    if (saveButton) saveButton.disabled = false;
  }
}

/**
 * Purpose: Remove the delete manual line item workflow using the existing shared UI state.
 * Effects: May call the backend api.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
async function deleteManualLineItem(lineItemId) {
  const confirmed = await confirmWebAppAction({
    title: "Delete delivery-list item?",
    message: "Delete this line item from its delivery list?",
    details: "This removes the line from the selected delivery-list stage.",
    confirmLabel: "Delete Line Item",
  });
  if (!confirmed) return;
  const payload = await fetchJson("/api/admin/line-item/delete", {
    method: "POST",
    body: JSON.stringify({ lineItemId }),
  });
  if (payload.meta?.id === state.activeListId) applyBackendPayload(payload);
  await loadDeliveryLists(state.activeListId);
  if (!els.adminModal?.hidden && state.manualEditListId) await runManualEditModalSearch(!state.manualEditQuery);
  else await runManualEditSearch();
  state.manualEditDirty = false;
  renderScanPage();
  playAppSound("destructive_action", { force: true });
}

/**
 * Purpose: Run the export static CSV workflow for the browser application.
 * Effects: May call the backend api.
 * Flow: Normalizes inputs, performs one named responsibility, and returns data or control to the caller.
 */
function exportStaticCsv() {
  const header = ["barcode", "order", "item", "qty", "scanned", "remaining", "dimensions", "customer", "route", "job", "product", "suggestedBay"];
  const rows = state.items.map((item) => {
    const row = { ...item, barcode: canonicalBarcode(item.order, item.item), remaining: Math.max(Number(item.qty) - Number(item.scanned), 0) };
    return header.map((key) => JSON.stringify(row[key] ?? "")).join(",");
  });
  const blob = new Blob([[header.join(","), ...rows].join("\n")], { type: "text/csv" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = "delivery-list-export.csv";
  link.click();
  URL.revokeObjectURL(url);
}

/* --------------------------------------------------------------------------
   v135 operational workflows
   These functions own Reject Tracking, rack detail/history modals, manual order
   creation, and stable import-run navigation. Keep new work in these owners
   instead of appending page-specific override blocks elsewhere in the file.
   -------------------------------------------------------------------------- */

const OPERATIONS_MODAL_PROFILES = {
  "rack-details": {
    controlCenter: true,
    showStatus: true,
    eyebrow: "Rack Operations",
    description: "Review assigned pieces, current rack status, packing actions, and controlled rack recovery from one live workspace.",
    context: "Individual rack workspace",
    status: "Live rack data",
    group: "racks",
  },
  "rack-history": {
    controlCenter: true,
    showStatus: false,
    eyebrow: "Rack Records",
    description: "Review packing-list snapshots or investigate actions across every rack from one searchable history workspace.",
    context: "Rack history workspace",
    status: "Audited rack records",
    group: "racks",
  },
};

function applyOperationsModalProfile(kind, options = {}) {
  const profile = { ...(OPERATIONS_MODAL_PROFILES[kind] || {}), ...options };
  const controlCenter = Boolean(profile.controlCenter);
  if (els.operationsModal) {
    els.operationsModal.dataset.kind = kind;
    els.operationsModal.dataset.group = profile.group || "operations";
    els.operationsModal.classList.toggle("is-control-center", controlCenter);
  }
  if (els.operationsModalEyebrow) els.operationsModalEyebrow.textContent = profile.eyebrow || "Operations";
  if (els.operationsModalTitle) els.operationsModalTitle.textContent = profile.title || "Operations";
  if (els.operationsModalDescription) els.operationsModalDescription.textContent = profile.description || "";
  if (els.operationsModalStatusText) {
    els.operationsModalStatusText.textContent = profile.status || "Live operations";
    const statusPill = els.operationsModalStatusText.closest(".operations-modal-health-pill");
    if (statusPill) statusPill.hidden = !Boolean(profile.showStatus);
  }
  if (els.rejectOperationsTabs) els.rejectOperationsTabs.hidden = kind !== "reject-log";
  if (els.operationsRackTabs) els.operationsRackTabs.hidden = kind !== "rack-details";
  if (els.operationsRackRecordsTabs) els.operationsRackRecordsTabs.hidden = kind !== "rack-history";
  if (els.operationsModalRackActions) els.operationsModalRackActions.hidden = kind !== "rack-details";
  if (els.operationsModal) els.operationsModal.classList.remove("show-reject-history");
  els.rejectOperationsTabs?.querySelectorAll("[data-reject-modal-view]").forEach((button) => {
    const active = button.dataset.rejectModalView === "entry";
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-selected", String(active));
  });
  return profile;
}

function openOperationsModal({
  kind = "operations",
  eyebrow = "",
  title = "",
  description = "",
  context = "",
  status = "",
  showStatus = null,
  group = "",
  body = "",
} = {}) {
  if (!els.operationsModal || !els.operationsModalBody) return;
  state.operationsModalKind = kind;
  if (!['rack-details', 'rack-history'].includes(kind)) clearRackOperationsVisual();
  applyOperationsModalProfile(kind, {
    ...(eyebrow ? { eyebrow } : {}),
    ...(title ? { title } : {}),
    ...(description ? { description } : {}),
    ...(context ? { context } : {}),
    ...(status ? { status } : {}),
    ...(showStatus !== null ? { showStatus: Boolean(showStatus) } : {}),
    ...(group ? { group } : {}),
  });
  els.operationsModalBody.innerHTML = body;
  els.operationsModalBody.hidden = false;
  applyLanguageToRoot(els.operationsModal);
  const isRackDetails = kind === "rack-details";
  const isRackHistory = kind === "rack-history";
  const showActionHistory = !isRackHistory;
  els.operationsModal?.classList.remove("show-rack-history");
  els.operationsRackTabs?.querySelectorAll("[data-rack-modal-view]").forEach((button) => {
    const active = button.dataset.rackModalView === "workspace";
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-selected", String(active));
  });
  els.operationsRackRecordsTabs?.querySelectorAll("[data-rack-records-view]").forEach((button) => {
    const active = button.dataset.rackRecordsView === "packing";
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-selected", String(active));
  });
  if (els.operationsModalHistory) {
    els.operationsModalHistory.hidden = isRackDetails || !showActionHistory;
    els.operationsModalHistory.open = isRackDetails;
  }
  if (!isRackDetails && els.operationsModalRackActions) {
    els.operationsModalRackActions.hidden = true;
    els.operationsModalRackActions.replaceChildren();
  }
  renderModalActionHistory([], "operations");
  if (showActionHistory) {
    loadModalActionHistory(kind, "operations").catch(() => renderModalActionHistory([], "operations"));
  }
  els.operationsModal.hidden = false;
  els.operationsModal.setAttribute("aria-hidden", "false");
  if (els.operationsModalBackdrop) {
    els.operationsModalBackdrop.hidden = false;
    els.operationsModalBackdrop.setAttribute("aria-hidden", "false");
  }
  updateModalScrollLock();
}

function closeOperationsModal() {
  state.operationsModalKind = "";
  state.rackMoveItemId = "";
  if (els.operationsModal) {
    delete els.operationsModal.dataset.kind;
    delete els.operationsModal.dataset.group;
    clearRackOperationsVisual();
    els.operationsModal.classList.remove("is-control-center", "show-reject-history", "show-rack-history");
    els.operationsModal.hidden = true;
    els.operationsModal.setAttribute("aria-hidden", "true");
  }
  state.rejectLogOpening = false;
  if (els.rejectOperationsTabs) els.rejectOperationsTabs.hidden = true;
  if (els.operationsRackTabs) els.operationsRackTabs.hidden = true;
  if (els.operationsRackRecordsTabs) els.operationsRackRecordsTabs.hidden = true;
  if (els.operationsModalRackActions) {
    els.operationsModalRackActions.hidden = true;
    els.operationsModalRackActions.replaceChildren();
  }
  if (els.operationsModalBody) els.operationsModalBody.hidden = false;
  if (els.operationsModalBackdrop) {
    els.operationsModalBackdrop.hidden = true;
    els.operationsModalBackdrop.setAttribute("aria-hidden", "true");
  }
  if (els.operationsModalBody) els.operationsModalBody.replaceChildren();
  if (els.operationsModalHistory) {
    els.operationsModalHistory.hidden = false;
    els.operationsModalHistory.open = false;
  }
  renderModalActionHistory([], "operations");
  updateModalScrollLock();
}

function compactRackItemHtml(item, currentRackCode = state.selectedRackOverviewCode) {
  const rackItemId = String(item.rackItemId || "");
  const itemLabel = `${item.order}-${item.item}`;
  return `
    <article class="rack-modal-line">
      <div class="rack-modal-line-primary">
        <strong>${escapeHtml(itemLabel)}</strong>
        <span>Qty ${escapeHtml(item.rackQty || 1)}</span>
      </div>
      <div class="rack-modal-line-details">
        <span>${escapeHtml(item.customer || "No customer")}</span>
        <span>${escapeHtml(item.job || item.product || "No job")}</span>
        <span>${escapeHtml(item.dimensions || "No dimensions")}</span>
        <span>${escapeHtml(item.deliveryDate ? formatDisplayDate(item.deliveryDate) : "No delivery date")}</span>
      </div>
      ${item.rackAddedAt ? `<small class="rack-modal-line-time">Scanned ${escapeHtml(formatDateTime(item.rackAddedAt))}</small>` : ""}
      ${hasPermission("manage_racks") ? `
        <div class="rack-modal-line-actions">
          <button class="icon-only icon-move rack-scope-move-button" type="button"
            data-rack-modal-move-item="${escapeHtml(rackItemId)}"
            data-source-rack="${escapeHtml(currentRackCode)}"
            data-rack-item-label="${escapeHtml(itemLabel)}"
            title="Move item" aria-label="Move ${escapeHtml(itemLabel)}"></button>
          <button class="icon-only icon-trash danger" type="button" data-rack-modal-clear-item="${escapeHtml(rackItemId)}" data-rack-modal-clear-label="${escapeHtml(itemLabel)}" title="Clear item" aria-label="Clear ${escapeHtml(itemLabel)}"></button>
        </div>` : ""}
    </article>`;
}

function rackTransferOptions(currentRackCode) {
  return state.racks
    .filter((rack) => (
      String(rack.code) !== String(currentRackCode)
      && String(rack.status || "Open").trim().toLowerCase() === "open"
    ))
    .map((rack) => `<option value="${escapeHtml(rack.code)}">${escapeHtml(rackOptionLabel(rack))}</option>`)
    .join("");
}

function rackModalHeaderActionsHtml(rack) {
  if (!rack) return "";
  const isTruck = isTruckRack(rack);
  const statusLower = String(rack.status || "Open").trim().toLowerCase();
  const hasItems = Number(rack.qty || 0) > 0;
  const canTransfer = hasPermission("transfer_rack_contents") || hasPermission("manage_racks");
  const transferOptions = rackTransferOptions(rack.code);
  const printLabel = isTruck ? "Print Truck Packing Slip" : "Print Packing Slip";
  return `
    ${hasItems && statusLower === "open" ? `<button class="app-primary-button" type="button" data-rack-modal-complete="${escapeHtml(rack.code)}">Complete Rack</button>` : ""}
    ${hasItems && statusLower === "closed" ? `<button class="app-primary-button" type="button" data-rack-modal-uncomplete="${escapeHtml(rack.code)}">Uncomplete Rack</button>` : ""}
    ${statusLower === "in transit" ? `<button class="app-primary-button" type="button" data-rack-modal-return="${escapeHtml(rack.code)}">Mark Returned</button><button type="button" class="secondary" data-rack-modal-not-on-way="${escapeHtml(rack.code)}">Not On The Way</button>` : ""}
    <button class="app-primary-button" type="button" data-rack-modal-print="${escapeHtml(rack.code)}" ${hasItems && ["closed", "in transit"].includes(statusLower) ? "" : "disabled"}>${printLabel}</button>
    ${canTransfer && hasItems ? `<button class="icon-only icon-move rack-scope-move-button rack-move-all-icon" type="button" data-rack-modal-move-all="${escapeHtml(rack.code)}" ${transferOptions ? "" : "disabled"} title="Move all rack contents" aria-label="Move all contents from rack ${escapeHtml(rack.code)}"></button>` : ""}`;
}

function updateRackModalHeaderActions(rack) {
  if (!els.operationsModalRackActions) return;
  const html = rackModalHeaderActionsHtml(rack);
  els.operationsModalRackActions.innerHTML = html;
  els.operationsModalRackActions.hidden = !html;
  applyLanguageToRoot(els.operationsModalRackActions);
}

function rackDetailsModalHtml(rack) {
  if (!rack) return `<div class="admin-empty">Rack not found.</div>`;
  const items = rack.items || [];
  const canTransfer = hasPermission("transfer_rack_contents") || hasPermission("manage_racks");
  const transferOptions = rackTransferOptions(rack.code);
  const dateGroups = new Map();
  for (const item of items) {
    const key = String(item.deliveryDate || "No delivery date");
    if (!dateGroups.has(key)) dateGroups.set(key, []);
    dateGroups.get(key).push(item);
  }
  const itemHtml = [...dateGroups.entries()]
    .sort(([aDate], [bDate]) => aDate.localeCompare(bDate))
    .map(([deliveryDate, rows]) => {
      const pieceQty = rows.reduce((sum, row) => sum + Number(row.rackQty || 1), 0);
      return `
        <details class="rack-modal-date-group" open>
          <summary>
            <strong>${escapeHtml(deliveryDate === "No delivery date" ? deliveryDate : formatDisplayDate(deliveryDate))}</strong>
            <span>${escapeHtml(rows.length)} lines · ${escapeHtml(pieceQty)} pcs</span>
            ${canTransfer && deliveryDate !== "No delivery date" ? `<button class="icon-only icon-move rack-scope-move-button" type="button" data-rack-modal-move-date="${escapeHtml(deliveryDate)}" data-source-rack="${escapeHtml(rack.code)}" ${transferOptions ? "" : "disabled"} title="Move this delivery date" aria-label="Move all items for ${escapeHtml(formatDisplayDate(deliveryDate))}"></button>` : ""}
          </summary>
          <div class="rack-modal-date-lines">${rows.map((item) => compactRackItemHtml(item, rack.code)).join("")}</div>
        </details>`;
    }).join("");

  return `
    <section class="rack-details-modal-shell rack-details-modal-v184 ${escapeHtml(rackStatusClassName(rack))}">
      <div class="rack-details-modal-list" aria-label="Assigned rack pieces">${itemHtml || `<div class="admin-empty">No pieces are assigned.</div>`}</div>
    </section>`;
}

function chooseRackTransferDestination(sourceRackCode, options = {}) {
  const settings = typeof options === "string" ? { deliveryDate: options } : (options || {});
  const deliveryDate = String(settings.deliveryDate || "");
  const rackItemId = String(settings.rackItemId || "");
  const itemLabel = String(settings.itemLabel || "");
  const sourceRack = state.racks.find((rack) => String(rack.code) === String(sourceRackCode));
  const destinations = state.racks.filter((rack) => (
    String(rack.code) !== String(sourceRackCode)
    && String(rack.status || "Open").trim().toLowerCase() === "open"
  ));
  if (!sourceRack || !destinations.length) {
    return Promise.reject(new Error("No open destination racks are available."));
  }

  return new Promise((resolve) => {
    document.querySelector(".rack-transfer-backdrop")?.remove();
    const shell = document.createElement("div");
    shell.className = "rack-transfer-backdrop";
    const scopeText = rackItemId
      ? (itemLabel || "this rack item")
      : deliveryDate
        ? `all items dated ${formatDisplayDate(deliveryDate)}`
        : "every active item on this rack";
    shell.innerHTML = `
      <section class="rack-transfer-dialog" role="dialog" aria-modal="true" aria-labelledby="rackTransferTitle">
        <button class="modal-close-x gui-close-button rack-transfer-close" type="button" data-rack-transfer-cancel aria-label="Close">&times;</button>
        <div class="rack-transfer-dialog-copy">
          <small>Rack transfer</small>
          <h2 id="rackTransferTitle">Move ${escapeHtml(scopeText)}</h2>
          <p>Choose an open destination rack. The destination is validated before anything moves.</p>
        </div>
        <div class="rack-transfer-dialog-field">
          <span>Destination rack</span>
          <div class="rack-transfer-combobox" data-rack-transfer-combobox>
            <button type="button" class="rack-transfer-combobox-trigger" data-rack-transfer-trigger aria-haspopup="listbox" aria-expanded="false">
              <span data-rack-transfer-selection>Select destination rack...</span>
              <i aria-hidden="true"></i>
            </button>
            <div class="rack-transfer-combobox-menu" data-rack-transfer-menu role="listbox" hidden>
              ${destinations.map((rack) => `<button type="button" role="option" data-rack-transfer-option="${escapeHtml(rack.code)}">${escapeHtml(rackOptionLabel(rack))}</button>`).join("")}
            </div>
          </div>
        </div>
        <div class="rack-transfer-dialog-actions">
          <button type="button" class="secondary" data-rack-transfer-cancel>Cancel</button>
          <button type="button" data-rack-transfer-confirm disabled>Continue</button>
        </div>
      </section>`;

    const trigger = shell.querySelector("[data-rack-transfer-trigger]");
    const menu = shell.querySelector("[data-rack-transfer-menu]");
    const selection = shell.querySelector("[data-rack-transfer-selection]");
    const confirm = shell.querySelector("[data-rack-transfer-confirm]");
    let selectedCode = "";
    const setMenuOpen = (open) => {
      if (!menu || !trigger) return;
      menu.hidden = !open;
      trigger.setAttribute("aria-expanded", String(open));
      shell.classList.toggle("is-dropdown-open", open);
      if (open) menu.querySelector("[data-rack-transfer-option]")?.focus();
    };
    const close = (value = "") => {
      shell.remove();
      document.body.classList.remove("modal-scroll-locked");
      resolve(value);
    };
    trigger?.addEventListener("click", () => setMenuOpen(menu?.hidden !== false));
    shell.addEventListener("click", (event) => {
      const option = event.target.closest("[data-rack-transfer-option]");
      if (option) {
        selectedCode = option.dataset.rackTransferOption || "";
        if (selection) selection.textContent = option.textContent?.trim() || selectedCode;
        if (confirm) confirm.disabled = !selectedCode;
        menu?.querySelectorAll("[data-rack-transfer-option]").forEach((row) => row.setAttribute("aria-selected", String(row === option)));
        setMenuOpen(false);
        trigger?.focus();
        return;
      }
      if (event.target === shell || event.target.closest("[data-rack-transfer-cancel]")) {
        close("");
        return;
      }
      if (event.target.closest("[data-rack-transfer-confirm]")) close(selectedCode);
    });
    shell.addEventListener("keydown", (event) => {
      if (event.key === "Escape") {
        if (menu && !menu.hidden) setMenuOpen(false);
        else close("");
      }
    });
    document.body.appendChild(shell);
    document.body.classList.add("modal-scroll-locked");
    trigger?.focus();
  });
}

async function moveRackContents(sourceRackCode, targetRackCode, deliveryDate = "") {
  if (!targetRackCode) throw new Error("Select a destination rack.");
  const scopeLabel = deliveryDate ? `all items for ${formatDisplayDate(deliveryDate)}` : "all rack contents";
  const confirmed = await confirmWebAppAction({
    title: deliveryDate ? "Move delivery-date group?" : "Move all rack contents?",
    message: `Move <strong>${escapeHtml(scopeLabel)}</strong> from <strong>${escapeHtml(sourceRackCode)}</strong> to <strong>${escapeHtml(targetRackCode)}</strong>?`,
    details: "Every item is validated before anything moves. The transfer is cancelled if any item is incompatible.",
    confirmLabel: deliveryDate ? "Move Date Group" : "Move All Contents",
    danger: false,
  });
  if (!confirmed) return;
  const payload = await fetchJson("/api/racks/move-contents", {
    method: "POST",
    body: JSON.stringify({ sourceRackCode, targetRackCode, deliveryDate }),
  });
  state.racks = payload.racks || state.racks;
  state.rackSummary = payload.summary || state.rackSummary;
  playAppSound("rack_item_added");
  showSaveConfirmation(payload.message || "Rack contents were moved.");
  await refreshOpenRackDetails(sourceRackCode);
}

function openRackDetailsModal(rackCode) {
  const rack = state.racks.find((item) => String(item.code) === String(rackCode));
  if (!rack) return;
  state.selectedRackOverviewCode = rack.code;
  openOperationsModal({
    kind: "rack-details",
    eyebrow: rackGroupLabel(rack),
    title: rack.code === "T" ? "Truck / No Rack" : `Rack ${rack.code}`,
    description: `${rack.name || rack.type || rackGroupLabel(rack)} · ${rackStatusLabel(rack)} · ${Number(rack.qty || 0)} pieces`,
    context: rack.code === "T" ? "Truck loading workspace" : `${rack.type || "Rack"} workspace`,
    status: rackStatusLabel(rack),
    body: rackDetailsModalHtml(rack),
  });
  applyRackOperationsVisual(rack);
  updateRackModalHeaderActions(rack);
}

async function refreshOpenRackDetails(rackCode = state.selectedRackOverviewCode) {
  await ensureRacksLoaded();
  renderRacksPage();
  const rack = state.racks.find((item) => String(item.code) === String(rackCode));
  if (rack && state.operationsModalKind === "rack-details") {
    applyOperationsModalProfile("rack-details", {
      eyebrow: rackGroupLabel(rack),
      title: rack.code === "T" ? "Truck / No Rack" : `Rack ${rack.code}`,
      description: `${rack.name || rack.type || rackGroupLabel(rack)} · ${rackStatusLabel(rack)} · ${Number(rack.qty || 0)} pieces`,
      context: rack.code === "T" ? "Truck loading workspace" : `${rack.type || "Rack"} workspace`,
      status: rackStatusLabel(rack),
    });
    applyRackOperationsVisual(rack);
    els.operationsModalBody.innerHTML = rackDetailsModalHtml(rack);
    updateRackModalHeaderActions(rack);
  } else if (!rack) {
    closeOperationsModal();
  }
}

const PACKING_HISTORY_DAYS_PER_PAGE = 25;

function packingHistoryGroups(history = state.packingListHistory, query = state.packingHistoryQuery) {
  const cleanQuery = String(query || "").trim().toLowerCase();
  const groups = new Map();
  for (const row of Array.isArray(history) ? history : []) {
    const searchText = [row.rack_code, row.rack_name, row.delivery_date, row.printed_by, row.printed_at]
      .join(" ")
      .toLowerCase();
    if (cleanQuery && !searchText.includes(cleanQuery)) continue;
    const day = String(row.printed_at || row.printedAt || "").slice(0, 10) || "Unknown date";
    if (!groups.has(day)) groups.set(day, []);
    groups.get(day).push(row);
  }
  return [...groups.entries()]
    .sort(([a], [b]) => b.localeCompare(a))
    .map(([date, rows]) => ({
      date,
      rows: rows.slice().sort((a, b) => String(b.printed_at || "").localeCompare(String(a.printed_at || ""))),
    }));
}

function packingHistoryWeekGroups(dayGroups = []) {
  const weeks = new Map();
  for (const dayGroup of dayGroups) {
    const weekStart = deliveryBusinessWeekStart(dayGroup.date);
    const weekKey = weekStart ? deliveryDateKey(weekStart) : "unknown";
    if (!weeks.has(weekKey)) weeks.set(weekKey, []);
    weeks.get(weekKey).push(dayGroup);
  }
  return [...weeks.entries()]
    .sort(([a], [b]) => b.localeCompare(a))
    .map(([weekKey, days]) => ({
      weekKey,
      label: weekKey === "unknown" ? "Unknown print date" : deliveryBusinessWeekLabel(weekKey),
      days: days.slice().sort((a, b) => String(b.date).localeCompare(String(a.date))),
    }));
}

function packingHistoryRowHtml(row) {
  return `
    <article class="packing-history-row packing-history-row-v272" data-packing-history-search="${escapeHtml([row.rack_code, row.rack_name, row.delivery_date, row.printed_by, row.printed_at].join(" ").toLowerCase())}">
      <div class="packing-history-rack-v272"><strong>${escapeHtml(row.rack_name || row.rack_code)}</strong><span>${escapeHtml(row.rack_code)}</span></div>
      <div><small>Delivery date</small><strong>${escapeHtml(row.delivery_date ? formatDisplayDate(row.delivery_date) : "Mixed")}</strong></div>
      <div><small>Printed</small><strong>${escapeHtml(formatDateTime(row.printed_at))}</strong></div>
      <div><small>Contents</small><strong>${escapeHtml(row.piece_qty)} pcs · ${escapeHtml(row.line_count)} lines</strong></div>
      <div><small>Printed by</small><strong>${escapeHtml(row.printed_by || "system")}</strong></div>
      <div class="packing-history-row-actions-v272">
        <button type="button" class="secondary" data-packing-history-preview="${escapeHtml(row.id)}">Preview</button>
        <button type="button" class="app-primary-button" data-packing-history-print="${escapeHtml(row.id)}">Print Snapshot</button>
      </div>
    </article>`;
}

function packingHistoryModalHtml(history = state.packingListHistory) {
  const dayGroups = packingHistoryGroups(history);
  const daysPerPage = Math.max(Number(state.packingHistoryDaysPerPage || PACKING_HISTORY_DAYS_PER_PAGE), 1);
  const totalDays = dayGroups.length;
  const totalPages = Math.max(Math.ceil(totalDays / daysPerPage), 1);
  state.packingHistoryPage = Math.min(Math.max(Number(state.packingHistoryPage || 1), 1), totalPages);
  const pageStartIndex = (state.packingHistoryPage - 1) * daysPerPage;
  const pageDays = dayGroups.slice(pageStartIndex, pageStartIndex + daysPerPage);
  const weeks = packingHistoryWeekGroups(pageDays);
  const visibleSnapshotCount = pageDays.reduce((sum, group) => sum + group.rows.length, 0);
  const startDay = totalDays ? pageStartIndex + 1 : 0;
  const endDay = totalDays ? Math.min(pageStartIndex + pageDays.length, totalDays) : 0;

  return `
    <section class="packing-history-shell packing-history-shell-v184 packing-history-shell-v272" data-rack-history-panel="packing">
      <div class="packing-history-intro packing-history-intro-v272">
        <div><strong>Previously printed packing lists</strong><span>Snapshots are grouped by print week. Expand a week to review its historical rack contents.</span></div>
        <label class="search-box"><span class="search-icon"></span><input id="packingHistorySearch" type="search" autocomplete="off" value="${escapeHtml(state.packingHistoryQuery || "")}" placeholder="Search rack, date, or user..."></label>
      </div>
      <div class="packing-history-page-summary-v272">
        <span class="packing-history-page-summary-copy-v273">
          ${totalDays ? `<b>${escapeHtml(startDay)}-${escapeHtml(endDay)} of ${escapeHtml(totalDays)}</b> print days <i aria-hidden="true">&middot;</i> ` : ""}
          <b>${escapeHtml(visibleSnapshotCount)}</b> snapshot${visibleSnapshotCount === 1 ? "" : "s"}${totalDays ? "" : " found"}
        </span>
      </div>
      <div class="packing-history-groups packing-history-groups-v184 packing-history-groups-v272" id="packingHistoryGroups">
        ${weeks.length ? weeks.map((week) => {
          const weekSnapshots = week.days.reduce((sum, day) => sum + day.rows.length, 0);
          return `
            <details class="packing-history-week-v272">
              <summary>
                <span class="packing-history-week-chevron-v272" aria-hidden="true"></span>
                <div><strong>${escapeHtml(week.label)}</strong><span>${escapeHtml(week.days.length)} day${week.days.length === 1 ? "" : "s"} · ${escapeHtml(weekSnapshots)} snapshot${weekSnapshots === 1 ? "" : "s"}</span></div>
                <span class="packing-history-week-action-v272"><b class="is-closed">View snapshots</b><b class="is-open">Hide snapshots</b></span>
              </summary>
              <div class="packing-history-week-body-v272">
                ${week.days.map((day) => `
                  <section class="packing-history-day-v272">
                    <header><strong>${escapeHtml(day.date === "Unknown date" ? day.date : formatDisplayDate(day.date))}</strong><span>${escapeHtml(day.rows.length)} print${day.rows.length === 1 ? "" : "s"}</span></header>
                    <div class="packing-history-day-rows-v272">${day.rows.map(packingHistoryRowHtml).join("")}</div>
                  </section>`).join("")}
              </div>
            </details>`;
        }).join("") : `<div class="admin-empty">${state.packingHistoryQuery ? "No packing-list snapshots match this search." : "No packing lists have been printed since history tracking was installed."}</div>`}
      </div>
      <footer class="packing-history-pagination-v272" ${totalDays <= daysPerPage ? "hidden" : ""}>
        <button type="button" class="secondary" data-packing-history-page="${Math.max(state.packingHistoryPage - 1, 1)}" ${state.packingHistoryPage <= 1 ? "disabled" : ""}>Previous</button>
        <strong>Page ${escapeHtml(state.packingHistoryPage)} of ${escapeHtml(totalPages)}</strong>
        <button type="button" class="secondary" data-packing-history-page="${Math.min(state.packingHistoryPage + 1, totalPages)}" ${state.packingHistoryPage >= totalPages ? "disabled" : ""}>Next</button>
      </footer>
    </section>`;
}

function renderPackingHistoryPanel({ focusSearch = false } = {}) {
  const panel = document.querySelector('[data-rack-history-panel="packing"]');
  if (!panel) return;
  panel.outerHTML = packingHistoryModalHtml();
  setRackHistoryView(state.rackHistoryView || "packing");
  applyLanguageToRoot(document.querySelector('[data-rack-history-panel="packing"]'));
  if (focusSearch) {
    const search = document.getElementById("packingHistorySearch");
    search?.focus();
    const length = String(search?.value || "").length;
    search?.setSelectionRange?.(length, length);
  }
}

function filterPackingHistoryRows(query = "") {
  state.packingHistoryQuery = String(query || "");
  state.packingHistoryPage = 1;
  renderPackingHistoryPanel({ focusSearch: true });
}

async function openPackingHistoryPreview(historyId) {
  const cleanId = Number(historyId || 0);
  if (!cleanId) return;
  document.querySelector(".packing-snapshot-preview-backdrop-v272")?.remove();

  const response = await fetch(`/api/racks/packing-history/${encodeURIComponent(cleanId)}/print`, { cache: "no-store" });
  if (!response.ok) {
    const text = await response.text();
    throw new Error(text || `Snapshot preview failed: ${response.status}`);
  }
  let markup = await response.text();
  markup = markup
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, "")
    .replace(/<\/head>/i, "<style>button{display:none!important}body{margin:16px!important}.packing-sheet{page-break-after:auto!important}</style></head>");

  const shell = document.createElement("div");
  shell.className = "packing-snapshot-preview-backdrop-v272";
  shell.innerHTML = `
    <section class="packing-snapshot-preview-dialog-v272" role="dialog" aria-modal="true" aria-labelledby="packingSnapshotPreviewTitle">
      <header>
        <div><small>Packing List History</small><h2 id="packingSnapshotPreviewTitle">Snapshot Preview</h2><p>Exact saved rack contents from the original packing-list print.</p></div>
        <button type="button" class="gui-close-button" data-packing-preview-close aria-label="Close snapshot preview">&times;</button>
      </header>
      <div class="packing-snapshot-preview-frame-v272"><iframe title="Historical packing list snapshot" sandbox=""></iframe></div>
      <footer>
        <button type="button" class="app-primary-button" data-packing-preview-print="${escapeHtml(cleanId)}">Print Snapshot</button>
      </footer>
    </section>`;
  const close = () => {
    document.removeEventListener("keydown", keyHandler);
    shell.remove();
    document.body.classList.remove("modal-scroll-locked");
    updateModalScrollLock();
  };
  const keyHandler = (event) => {
    if (event.key === "Escape") close();
  };
  shell.addEventListener("click", (event) => {
    if (event.target === shell || event.target.closest("[data-packing-preview-close]")) {
      close();
      return;
    }
    const printButton = event.target.closest("[data-packing-preview-print]");
    if (printButton) launchManagedPrint(`/api/racks/packing-history/${encodeURIComponent(printButton.dataset.packingPreviewPrint)}/print`);
  });
  document.addEventListener("keydown", keyHandler);
  document.body.appendChild(shell);
  document.body.classList.add("modal-scroll-locked");
  const frame = shell.querySelector("iframe");
  if (frame) frame.srcdoc = markup;
  shell.querySelector("[data-packing-preview-close]")?.focus();
}

function rackHistoryDefaultFilters() {
  return {
    query: "",
    user: "",
    action: "",
    rackGroup: "",
    rackFrom: "",
    rackTo: "",
    dateFrom: "",
    dateTo: "",
  };
}

function rackHistoryNormalizeCode(value = "") {
  return String(value || "")
    .trim()
    .replace(/^RACK[-_ ]*/i, "")
    .toUpperCase();
}

function rackHistoryEventCodes(event = {}) {
  const payload = event.payload || {};
  const values = [];
  if (String(event.entityType || "") === "rack") {
    values.push(...String(event.entityId || "").split(/[;,|]+/));
  }
  for (const key of ["rackCode", "sourceRackCode", "targetRackCode", "oldCode"]) {
    if (payload[key]) values.push(payload[key]);
  }
  for (const key of ["rackCodes", "createdRackCodes", "affectedRackCodes"]) {
    if (Array.isArray(payload[key])) values.push(...payload[key]);
  }
  return [...new Set(values.map(rackHistoryNormalizeCode).filter(Boolean))];
}

function rackHistoryRackByCode(code = "") {
  const normalized = rackHistoryNormalizeCode(code);
  return state.racks.find((rack) => rackHistoryNormalizeCode(rack.code) === normalized) || null;
}

function rackHistoryEventGroups(event = {}) {
  const payload = event.payload || {};
  const groups = new Set();
  for (const code of rackHistoryEventCodes(event)) {
    const rack = rackHistoryRackByCode(code);
    if (rack) groups.add(rackGroupLabel(rack));
  }
  for (const value of [payload.rackGroup, payload.rackType, payload.type]) {
    if (String(value || "").trim()) groups.add(String(value).trim());
  }
  if (String(event.entityType || "") === "rack_set" && String(event.entityId || "").trim()) {
    groups.add(String(event.entityId).trim());
  }
  return [...groups];
}

function rackHistorySortedRacks(group = "") {
  return state.racks
    .filter((rack) => !group || rackGroupLabel(rack) === group)
    .slice()
    .sort((a, b) => String(a.code || "").localeCompare(String(b.code || ""), undefined, { numeric: true, sensitivity: "base" }));
}

function rackHistoryOptionValues(events = [], field = "") {
  return [...new Set(events.map((event) => String(event[field] || (field === "user" ? "system" : "")).trim()).filter(Boolean))]
    .sort((a, b) => actionHistoryLabel(a).localeCompare(actionHistoryLabel(b), undefined, { sensitivity: "base" }));
}

function rackHistoryAllowedCodes() {
  const filters = state.rackHistoryFilters || rackHistoryDefaultFilters();
  const rackChoices = rackHistorySortedRacks(filters.rackGroup);
  const rackIndexes = new Map(rackChoices.map((rack, index) => [rackHistoryNormalizeCode(rack.code), index]));
  let rangeStart = filters.rackFrom && rackIndexes.has(rackHistoryNormalizeCode(filters.rackFrom))
    ? rackIndexes.get(rackHistoryNormalizeCode(filters.rackFrom))
    : 0;
  let rangeEnd = filters.rackTo && rackIndexes.has(rackHistoryNormalizeCode(filters.rackTo))
    ? rackIndexes.get(rackHistoryNormalizeCode(filters.rackTo))
    : Math.max(rackChoices.length - 1, 0);
  if (rangeStart > rangeEnd) [rangeStart, rangeEnd] = [rangeEnd, rangeStart];
  const scopeActive = Boolean(filters.rackGroup || filters.rackFrom || filters.rackTo);
  if (!scopeActive) return null;
  return rackChoices
    .filter((_rack, index) => index >= rangeStart && index <= rangeEnd)
    .map((rack) => rackHistoryNormalizeCode(rack.code))
    .filter(Boolean);
}

function rackHistoryFilteredEvents() {
  return Array.isArray(state.rackHistoryEvents) ? state.rackHistoryEvents : [];
}

function rackHistoryFiltersActive(filters = state.rackHistoryFilters || {}) {
  return Object.values(filters).some((value) => Boolean(String(value || "").trim()));
}

function rackHistoryFilterMarkup() {
  const filters = state.rackHistoryFilters || rackHistoryDefaultFilters();
  const users = Array.isArray(state.rackHistoryUsers) ? state.rackHistoryUsers : [];
  const actions = Array.isArray(state.rackHistoryActions) ? state.rackHistoryActions : [];
  const groups = [...new Set([
    ...state.racks.map((rack) => rackGroupLabel(rack)),
  ].filter(Boolean))].sort((a, b) => a.localeCompare(b, undefined, { sensitivity: "base" }));
  const racks = rackHistorySortedRacks(filters.rackGroup);
  const rackOptions = (selectedCode = "") => racks
    .map((rack) => `<option value="${escapeHtml(rack.code)}" ${String(selectedCode) === String(rack.code) ? "selected" : ""}>${escapeHtml(rack.code)} · ${escapeHtml(rack.name || rack.type || rackGroupLabel(rack))}</option>`)
    .join("");
  return `
    <section class="rack-history-filters" aria-label="Rack history filters">
      <div class="rack-history-filter-grid">
        <label class="rack-history-filter-search"><span>Search log</span><input type="search" autocomplete="off" data-rack-history-filter="query" value="${escapeHtml(filters.query)}" placeholder="Search racks, actions, users, or details..."></label>
        <label><span>User</span><select data-rack-history-filter="user"><option value="">All users</option>${users.map((value) => `<option value="${escapeHtml(value)}" ${filters.user === value ? "selected" : ""}>${escapeHtml(value)}</option>`).join("")}</select></label>
        <label><span>Action</span><select data-rack-history-filter="action"><option value="">All actions</option>${actions.map((value) => `<option value="${escapeHtml(value)}" ${filters.action === value ? "selected" : ""}>${escapeHtml(actionHistoryLabel(value))}</option>`).join("")}</select></label>
        <label><span>Rack Group</span><select data-rack-history-filter="rackGroup"><option value="">All rack groups</option>${groups.map((value) => `<option value="${escapeHtml(value)}" ${filters.rackGroup === value ? "selected" : ""}>${escapeHtml(value)}</option>`).join("")}</select></label>
        <label><span>Rack from</span><select data-rack-history-filter="rackFrom"><option value="">First rack</option>${rackOptions(filters.rackFrom)}</select></label>
        <label><span>Through rack</span><select data-rack-history-filter="rackTo"><option value="">Last rack</option>${rackOptions(filters.rackTo)}</select></label>
        <label><span>From date</span><input type="date" data-rack-history-filter="dateFrom" value="${escapeHtml(filters.dateFrom)}"></label>
        <label><span>Through date</span><input type="date" data-rack-history-filter="dateTo" value="${escapeHtml(filters.dateTo)}"></label>
      </div>
      <div class="rack-history-filter-footer">
        <span id="rackHistoryResultCount"></span>
        <div class="rack-history-pager" aria-label="Rack history pages">
          <button type="button" class="secondary" data-rack-history-page="${Math.max(Number(state.rackHistoryPage || 1) - 1, 1)}" ${Number(state.rackHistoryPage || 1) <= 1 ? "disabled" : ""}>Previous</button>
          <strong>Page ${escapeHtml(state.rackHistoryPage || 1)} of ${escapeHtml(state.rackHistoryTotalPages || 1)}</strong>
          <button type="button" class="secondary" data-rack-history-page="${Number(state.rackHistoryPage || 1) + 1}" ${Number(state.rackHistoryPage || 1) >= Number(state.rackHistoryTotalPages || 1) ? "disabled" : ""}>Next</button>
        </div>
        <button type="button" class="secondary" data-rack-history-clear ${rackHistoryFiltersActive(filters) ? "" : "disabled"}>Clear filters</button>
      </div>
    </section>`;
}

function rackHistoryRowsMarkup(events = []) {
  if (!events.length) {
    return `<div class="admin-empty">${state.rackHistoryTotalCount ? "No rack-history events match the selected filters." : "No rack history has been recorded yet."}</div>`;
  }
  return events.map((event) => {
    const codes = rackHistoryEventCodes(event);
    const groups = rackHistoryEventGroups(event);
    return `
      <article class="rack-history-event-row">
        <span class="modal-action-history-icon" aria-hidden="true"></span>
        <div class="rack-history-event-copy">
          <strong>${escapeHtml(actionHistoryLabel(event.action))}</strong>
          <span>${escapeHtml(actionHistoryDetail(event))}</span>
          <div class="rack-history-event-tags">
            ${codes.map((code) => `<b>${escapeHtml(code)}</b>`).join("")}
            ${groups.map((group) => `<i>${escapeHtml(group)}</i>`).join("")}
          </div>
        </div>
        <div class="rack-history-event-meta">
          <time datetime="${escapeHtml(event.createdAt || "")}">${escapeHtml(actionHistoryDateTime(event.createdAt))}</time>
          <small>${escapeHtml(event.user || "system")}</small>
        </div>
      </article>`;
  }).join("");
}

function allRacksHistoryModalHtml() {
  const rows = rackHistoryFilteredEvents();
  return `
    <section class="all-racks-history-shell" id="allRacksHistoryPanel" data-rack-history-panel="all" hidden>
      <header class="all-racks-history-intro">
        <div><strong>All rack activity</strong><span>Investigate status, scanning, transfer, recovery, setup, and packing actions across every rack.</span></div>
        <b>${escapeHtml(state.rackHistoryTotalCount)} events</b>
      </header>
      ${rackHistoryFilterMarkup()}
      <div class="rack-history-event-list" id="allRacksHistoryList">${rackHistoryRowsMarkup(rows)}</div>
    </section>`;
}

function rackHistoryModalHtml() {
  return `
    <div class="rack-history-control-center">
      ${packingHistoryModalHtml()}
      ${allRacksHistoryModalHtml()}
    </div>`;
}

function syncRackHistoryRangeControls() {
  const filters = state.rackHistoryFilters || rackHistoryDefaultFilters();
  const racks = rackHistorySortedRacks(filters.rackGroup);
  const validCodes = new Set(racks.map((rack) => String(rack.code)));
  if (filters.rackFrom && !validCodes.has(filters.rackFrom)) filters.rackFrom = "";
  if (filters.rackTo && !validCodes.has(filters.rackTo)) filters.rackTo = "";
  const optionHtml = racks.map((rack) => `<option value="${escapeHtml(rack.code)}">${escapeHtml(rack.code)} · ${escapeHtml(rack.name || rack.type || rackGroupLabel(rack))}</option>`).join("");
  const from = document.querySelector('[data-rack-history-filter="rackFrom"]');
  const to = document.querySelector('[data-rack-history-filter="rackTo"]');
  if (from) {
    from.innerHTML = `<option value="">First rack</option>${optionHtml}`;
    from.value = filters.rackFrom;
  }
  if (to) {
    to.innerHTML = `<option value="">Last rack</option>${optionHtml}`;
    to.value = filters.rackTo;
  }
}

function renderAllRacksHistoryResults() {
  const rows = rackHistoryFilteredEvents();
  const page = Math.max(Number(state.rackHistoryPage || 1), 1);
  const pageSize = Math.max(Number(state.rackHistoryPageSize || 50), 1);
  const total = Math.max(Number(state.rackHistoryTotalCount || 0), 0);
  const pageStart = total ? ((page - 1) * pageSize) + 1 : 0;
  const pageEnd = total ? Math.min(pageStart + rows.length - 1, total) : 0;
  const panel = document.getElementById("allRacksHistoryPanel");
  if (panel) {
    const existingFilters = panel.querySelector(".rack-history-filters");
    if (existingFilters) existingFilters.outerHTML = rackHistoryFilterMarkup();
    const headerCount = panel.querySelector(".all-racks-history-intro > b");
    if (headerCount) headerCount.textContent = `${total} events`;
  }
  const list = document.getElementById("allRacksHistoryList");
  const result = document.getElementById("rackHistoryResultCount");
  const clear = document.querySelector("[data-rack-history-clear]");
  if (list) list.innerHTML = rackHistoryRowsMarkup(rows);
  if (result) result.textContent = total ? `${pageStart}-${pageEnd} of ${total} events` : "0 events";
  if (clear) clear.disabled = !rackHistoryFiltersActive();
  if (els.operationsAllRacksHistoryCount) els.operationsAllRacksHistoryCount.textContent = String(total);
  applyLanguageToRoot(panel);
}

async function loadRackHistoryPage() {
  const filters = state.rackHistoryFilters || rackHistoryDefaultFilters();
  const params = new URLSearchParams({
    context: "racks-history",
    page: String(Math.max(Number(state.rackHistoryPage || 1), 1)),
    pageSize: String(Math.min(Math.max(Number(state.rackHistoryPageSize || 50), 1), 50)),
  });
  for (const [key, value] of Object.entries(filters)) {
    if (["rackGroup", "rackFrom", "rackTo"].includes(key)) continue;
    if (String(value || "").trim()) params.set(key, String(value));
  }
  const rackCodes = rackHistoryAllowedCodes();
  if (rackCodes !== null) params.set("rackCodes", rackCodes.length ? rackCodes.join(",") : "__NO_RACKS__");
  const payload = await fetchJson(`/api/admin/action-history?${params.toString()}`);
  state.rackHistoryEvents = Array.isArray(payload.events) ? payload.events : [];
  state.rackHistoryPage = Math.max(Number(payload.page || 1), 1);
  state.rackHistoryPageSize = Math.min(Math.max(Number(payload.pageSize || 50), 1), 50);
  state.rackHistoryTotalCount = Math.max(Number(payload.totalCount || 0), 0);
  state.rackHistoryTotalPages = Math.max(Number(payload.totalPages || 1), 1);
  state.rackHistoryUsers = Array.isArray(payload.users) ? payload.users : [];
  state.rackHistoryActions = Array.isArray(payload.actions) ? payload.actions : [];
  renderAllRacksHistoryResults();
}

function setRackHistoryView(view = "packing") {
  state.rackHistoryView = view === "all" ? "all" : "packing";
  els.operationsRackRecordsTabs?.querySelectorAll("[data-rack-records-view]").forEach((button) => {
    const active = button.dataset.rackRecordsView === state.rackHistoryView;
    button.classList.toggle("is-active", active);
    button.setAttribute("aria-selected", String(active));
  });
  els.operationsModalBody?.querySelectorAll("[data-rack-history-panel]").forEach((panel) => {
    panel.hidden = panel.dataset.rackHistoryPanel !== state.rackHistoryView;
  });
  if (state.rackHistoryView === "all") renderAllRacksHistoryResults();
}

async function openRacksHistoryModal() {
  await ensureRacksLoaded();
  const packingPayload = await fetchJson("/api/racks/packing-history?limit=1000");
  state.packingListHistory = packingPayload.history || [];
  state.packingHistoryPage = 1;
  state.packingHistoryDaysPerPage = PACKING_HISTORY_DAYS_PER_PAGE;
  state.packingHistoryQuery = "";
  state.rackHistoryEvents = [];
  state.rackHistoryFilters = rackHistoryDefaultFilters();
  state.rackHistoryPage = 1;
  state.rackHistoryPageSize = 50;
  state.rackHistoryTotalCount = 0;
  state.rackHistoryTotalPages = 1;
  state.rackHistoryUsers = [];
  state.rackHistoryActions = [];
  state.rackHistoryView = "packing";
  openOperationsModal({
    kind: "rack-history",
    eyebrow: "Rack Records",
    title: "Racks History",
    description: "Packing-list snapshots and audited activity across every rack.",
    body: rackHistoryModalHtml(),
  });
  applyRackHistoryOperationsVisual();
  setRackHistoryView("packing");
  await loadRackHistoryPage();
}

function rejectDateKey(offsetDays = 0) {
  const value = new Date();
  value.setHours(12, 0, 0, 0);
  value.setDate(value.getDate() + Number(offsetDays || 0));
  const year = value.getFullYear();
  const month = String(value.getMonth() + 1).padStart(2, "0");
  const day = String(value.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function rejectFilterDescription() {
  const query = els.rejectSearchInput?.value.trim() || "";
  const dateFrom = els.rejectDateFrom?.value || "";
  const dateTo = els.rejectDateTo?.value || "";
  const location = rejectSelectedLocation();
  const reason = rejectSelectedReason();
  const rejectedBy = rejectSelectedUser();
  const parts = [];
  if (dateFrom && dateTo && dateFrom === dateTo) parts.push(`rejected on ${formatDisplayDate(dateFrom)}`);
  else if (dateFrom && dateTo) parts.push(`rejected from ${formatDisplayDate(dateFrom)} through ${formatDisplayDate(dateTo)}`);
  else if (dateFrom) parts.push(`rejected from ${formatDisplayDate(dateFrom)}`);
  else if (dateTo) parts.push(`rejected through ${formatDisplayDate(dateTo)}`);
  else parts.push("all rejected dates");
  if (location) parts.push(`at ${location}`);
  if (reason) parts.push(`for ${reason}`);
  if (rejectedBy) parts.push(`recorded by ${rejectedBy}`);
  if (query) parts.push(`matching “${query}”`);
  return parts.join(" · ");
}

function syncRejectDateLimits() {
  const from = els.rejectDateFrom?.value || "";
  const to = els.rejectDateTo?.value || "";
  if (els.rejectDateFrom) els.rejectDateFrom.max = to;
  if (els.rejectDateTo) els.rejectDateTo.min = from;
}

function setRejectDatePreset(value, { refresh = true } = {}) {
  const preset = String(value || "all");
  if (els.rejectDatePreset) els.rejectDatePreset.value = preset;
  if (!els.rejectDateFrom || !els.rejectDateTo) return;
  if (preset === "custom") {
    syncRejectDateLimits();
    syncRejectFilterButton();
    if (refresh) els.rejectDateFrom.focus();
    return;
  }
  if (preset === "today") {
    els.rejectDateFrom.value = rejectDateKey(0);
    els.rejectDateTo.value = rejectDateKey(0);
  } else if (preset === "7-days") {
    els.rejectDateFrom.value = rejectDateKey(-6);
    els.rejectDateTo.value = rejectDateKey(0);
  } else if (preset === "30-days") {
    els.rejectDateFrom.value = rejectDateKey(-29);
    els.rejectDateTo.value = rejectDateKey(0);
  } else if (preset === "all") {
    els.rejectDateFrom.value = "";
    els.rejectDateTo.value = "";
  }
  syncRejectDateLimits();
  syncRejectFilterButton();
  if (refresh) refreshRejectPage().catch((error) => showInlineError(error.message, true));
}

function markRejectDateRangeCustom() {
  syncRejectDateLimits();
  if (els.rejectDatePreset) els.rejectDatePreset.value = "custom";
  syncRejectFilterButton();
}

function rejectActiveFilterCount() {
  return [
    els.rejectDateFrom?.value,
    els.rejectDateTo?.value,
    rejectSelectedLocation(),
    rejectSelectedReason(),
    rejectSelectedUser(),
  ].filter(Boolean).length;
}

function syncRejectFilterButton() {
  const count = rejectActiveFilterCount();
  if (els.rejectFilterCount) {
    els.rejectFilterCount.textContent = String(count);
    els.rejectFilterCount.hidden = count === 0;
  }
  els.rejectFiltersBtn?.classList.toggle("is-active", count > 0);
}

function setRejectFilterPanelOpen(open) {
  const isOpen = Boolean(open);
  if (els.rejectFilterPanel) els.rejectFilterPanel.hidden = !isOpen;
  if (els.rejectFiltersBtn) els.rejectFiltersBtn.setAttribute("aria-expanded", String(isOpen));
}

function clearRejectFilters() {
  if (els.rejectSearchInput) {
    window.clearTimeout(els.rejectSearchInput._timer);
    els.rejectSearchInput.value = "";
  }
  setRejectDatePreset("all", { refresh: false });
  if (els.rejectLocationFilter) els.rejectLocationFilter.value = "";
  if (els.rejectReasonFilter) els.rejectReasonFilter.value = "";
  if (els.rejectUserFilter) els.rejectUserFilter.value = "";
  setRejectFilterPanelOpen(false);
  syncRejectFilterButton();
  renderRejectPage();
  refreshRejectPage().catch((error) => showInlineError(error.message, true));
}

